    cyber:    { unitName:'Servis / Saat',  baselineUnitsPerHour:1200, hourlyDowntimeCostUsd:68000, slaBreachPenaltyUsd:32000000, slaDeadlineTick:96,  hysteresisTick:192, tickMinutes:15, compliance:'Hedef Çerçeve Referansı: ISO 27001 / NIS2 Siber Süreklilik (Sertifikasyon Değildir)' },
