    health:   { unitName:'Hasta / Saat',   baselineUnitsPerHour:240,  hourlyDowntimeCostUsd:42000, slaBreachPenaltyUsd:25000000, slaDeadlineTick:72,  hysteresisTick:144, tickMinutes:15, compliance:'Hedef Çerçeve Referansı: Sağlık Hizmet Sürekliliği (Sertifikasyon Değildir)' },
    telecom:  { unitName:'Gbps Akış',      baselineUnitsPerHour:640,  hourlyDowntimeCostUsd:58000, slaBreachPenaltyUsd:36000000, slaDeadlineTick:96,  hysteresisTick:192, tickMinutes:15, compliance:'Hedef Çerçeve Referansı: Kritik Haberleşme SLA İlkeleri (Sertifikasyon Değildir)' },
    defense:  { unitName:'Birim / Saat',   baselineUnitsPerHour:150,  hourlyDowntimeCostUsd:82000, slaBreachPenaltyUsd:60000000, slaDeadlineTick:96,  hysteresisTick:192, tickMinutes:15, compliance:'Hedef Çerçeve Referansı: Kritik Tedarik Sürekliliği (Sertifikasyon Değildir)' },
    manufact: { unitName:'Ünite / Saat',   baselineUnitsPerHour:520,  hourlyDowntimeCostUsd:49000, slaBreachPenaltyUsd:28500000, slaDeadlineTick:144, hysteresisTick:240, tickMinutes:30, compliance:'Hedef Çerçeve Referansı: Endüstriyel Üretim Sürekliliği (Sertifikasyon Değildir)' },
    aviation: { unitName:'Uçuş / Saat',    baselineUnitsPerHour:95,   hourlyDowntimeCostUsd:64000, slaBreachPenaltyUsd:39000000, slaDeadlineTick:96,  hysteresisTick:192, tickMinutes:15, compliance:'Hedef Çerçeve Referansı: Havacılık Operasyonel Kontrol (Sertifikasyon Değildir)' },
    public:   { unitName:'Birim / Saat',   baselineUnitsPerHour:600,  hourlyDowntimeCostUsd:35000, slaBreachPenaltyUsd:22000000, slaDeadlineTick:120, hysteresisTick:240, tickMinutes:15, compliance:'Hedef Çerçeve Referansı: ISO 22301 Kamu Altyapı Sürekliliği (Sertifikasyon Değildir)' }
