  Object.entries(EXTRA_8_LOCALE_OVERRIDES).forEach(([locCode, cfg]) => {
    BUILTIN_LOCALE_PACKS[locCode] = {
      meta: {
        code: locCode,
        label: cfg.label,
        nativeName: cfg.nativeName,
        dir: cfg.dir,
        status: 'COMPLETE_VERIFIED',
        completenessPct: 100,
        machineTranslated: true,
        expertReviewed: false,
        humanReviewedPct: 0,
        reviewStatus: 'INSAN_INCELEMESI_BEKLIYOR',
        catalogVersion: I18N_CATALOG_VERSION,
        offlineReady: true,
        completedDomains: ['Ana Sahne', 'Ölçek Gezinimi', 'Zaman Çizgisi', 'Senaryolar', 'Hafıza', 'Bağlantılar', 'Ayarlar', 'Raporlar']
      },
      strings: {
        ...BUILTIN_LOCALE_PACKS['en-US'].strings,
        ...cfg.overrides
      }
    };
  });
  BUILTIN_LOCALE_PACKS['zh-CN'] = JSON.parse(JSON.stringify(BUILTIN_LOCALE_PACKS['zh-Hans']));
  BUILTIN_LOCALE_PACKS['zh-CN'].meta.code = 'zh-CN';

  const registeredLocalePacks = JSON.parse(JSON.stringify(BUILTIN_LOCALE_PACKS));
  let activeLocaleCode = 'tr-TR';
  const fallbackAuditLog = [];

  function resetLocalePacksToBuiltin() {
    Object.keys(registeredLocalePacks).forEach(k => delete registeredLocalePacks[k]);
    Object.entries(BUILTIN_LOCALE_PACKS).forEach(([k, v]) => {
      registeredLocalePacks[k] = JSON.parse(JSON.stringify(v));
    });
    return listSupportedLanguages();
  }

  function isRtlLocale(localeCode) {
    const clean = String(localeCode || '').trim().toLowerCase();
    const prefix = clean.split(/[-_]/)[0];
    return RTL_LANG_PREFIXES.includes(prefix);
  }

  function detectDeviceLocale(preferredCandidate) {
    const raw = String(
      preferredCandidate ||
      (typeof navigator !== 'undefined' && (navigator.language || (navigator.languages && navigator.languages[0]))) ||
      'tr-TR'
    ).trim();
    if (raw === 'zh' || raw.toLowerCase() === 'zh-hans' || raw.toLowerCase() === 'zh-cn') {
      return registeredLocalePacks['zh-Hans'] ? 'zh-Hans' : 'tr-TR';
    }
    if (registeredLocalePacks[raw]) return raw;
    const prefix = raw.toLowerCase().split(/[-_]/)[0];
    const matched = Object.keys(registeredLocalePacks).find(k => k.toLowerCase().startsWith(prefix + '-'));
    return matched || 'tr-TR';
  }

  function registerLocalePack(code, packDef) {
    if (!code || !packDef || typeof packDef !== 'object') {
      throw new Error('Geçerli bir dil kodu ve çeviri paketi gereklidir.');
    }
    const normCode = String(code).trim();
    const refKeys = Object.keys(BUILTIN_LOCALE_PACKS['tr-TR'].strings);
    const providedStrings = (packDef.strings && typeof packDef.strings === 'object') ? packDef.strings : {};
    const presentCount = refKeys.filter(k => typeof providedStrings[k] === 'string' && providedStrings[k].trim().length > 0).length;
    const completenessPct = Math.round((presentCount / Math.max(1, refKeys.length)) * 100);

    registeredLocalePacks[normCode] = {
      meta: {
        code: normCode,
        label: String((packDef.meta && packDef.meta.label) || normCode),
        nativeName: String((packDef.meta && packDef.meta.nativeName) || normCode),
        dir: (packDef.meta && packDef.meta.dir) || (isRtlLocale(normCode) ? 'rtl' : 'ltr'),
        status: completenessPct === 100 ? 'COMPLETE_VERIFIED' : 'PARTIAL_PACK_WITH_FALLBACK',
        completenessPct,
        machineTranslated: Boolean(packDef.meta && packDef.meta.machineTranslated),
        expertReviewed: Boolean(packDef.meta && packDef.meta.expertReviewed),
        offlineReady: true,
        completedDomains: Array.isArray(packDef.meta && packDef.meta.completedDomains)
          ? packDef.meta.completedDomains
          : (completenessPct === 100 ? ['Tüm Ana Akışlar'] : ['Kısmi Paket — Eksik Anahtarlar Yedek Dilden Gösterilir'])
      },
      strings: { ...providedStrings }
    };
    return registeredLocalePacks[normCode].meta;
  }

  function listSupportedLanguages() {
    const refKeys = Object.keys(BUILTIN_LOCALE_PACKS['tr-TR'].strings);
    return Object.entries(registeredLocalePacks).map(([code, pack]) => {
      const missingKeys = refKeys.filter(k => !pack.strings || typeof pack.strings[k] !== 'string' || !pack.strings[k].trim());
      const completenessPct = Math.round(((refKeys.length - missingKeys.length) / Math.max(1, refKeys.length)) * 100);
      return {
        code,
        label: pack.meta.label,
        nativeName: pack.meta.nativeName,
        dir: pack.meta.dir,
        status: completenessPct === 100 ? 'COMPLETE_VERIFIED' : pack.meta.status,
        completenessPct,
        missingKeyCount: missingKeys.length,
        humanReviewedPct: typeof pack.meta.humanReviewedPct === 'number' ? pack.meta.humanReviewedPct : 0,
        reviewStatus: pack.meta.reviewStatus || 'INSAN_INCELEMESI_BEKLIYOR',
        catalogVersion: pack.meta.catalogVersion || I18N_CATALOG_VERSION,
        completedDomains: pack.meta.completedDomains || [],
        offlineReady: true
      };
    });
  }

  function setActiveLocale(localeCode, persist = true) {
    const resolved = registeredLocalePacks[localeCode] ? localeCode : detectDeviceLocale(localeCode);
    activeLocaleCode = resolved;
    if (persist && typeof localStorage !== 'undefined') {
      try {
        localStorage.setItem(I18N_STORAGE_KEY, resolved);
      } catch (_) {}
    }
    return registeredLocalePacks[resolved].meta;
  }

  function getActiveLocale() {
    return activeLocaleCode;
  }

  function translate(key, options = {}) {
    const loc = options.locale || activeLocaleCode || 'tr-TR';
    const pack = registeredLocalePacks[loc] || registeredLocalePacks['tr-TR'];
    if (pack && pack.strings && typeof pack.strings[key] === 'string' && pack.strings[key].trim() !== '') {
      return pack.strings[key];
    }
    // Deterministic fallback: en-US -> tr-TR
    const fallbackLocale = (loc !== 'en-US' && registeredLocalePacks['en-US'].strings[key]) ? 'en-US' : 'tr-TR';
    const fallbackText = (registeredLocalePacks[fallbackLocale] && registeredLocalePacks[fallbackLocale].strings[key]) || key;
    fallbackAuditLog.push({
      requestedLocale: loc,
      missingKey: key,
      fallbackLocaleUsed: fallbackLocale
    });
    return options.markFallback ? `${fallbackText} [${fallbackLocale}]` : fallbackText;
  }

  function getPlainLanguageTerm(glossaryIdOrKey, localeCode) {
    const loc = localeCode || activeLocaleCode || 'tr-TR';
    const found = PLAIN_LANGUAGE_GLOSSARY.find(
      g => g.id === glossaryIdOrKey || g.plainKey === glossaryIdOrKey
    );
    if (found) {
      return translate(found.plainKey, { locale: loc });
    }
    return translate(glossaryIdOrKey, { locale: loc });
  }

  function formatLocaleNumber(value, localeCode, fractionDigits = 2) {
    const loc = localeCode || activeLocaleCode || 'tr-TR';
    const num = Number(value);
    if (!Number.isFinite(num)) return String(value ?? '');
    return new Intl.NumberFormat(loc, {
      minimumFractionDigits: fractionDigits,
      maximumFractionDigits: fractionDigits
    }).format(num);
  }

  function formatLocaleCurrency(value, currencyCode = 'USD', localeCode) {
    const loc = localeCode || activeLocaleCode || 'tr-TR';
    const num = Number(value);
    if (!Number.isFinite(num)) return String(value ?? '');
    return new Intl.NumberFormat(loc, {
      style: 'currency',
      currency: currencyCode || 'USD',
      maximumFractionDigits: 0
    }).format(num);
  }

  function formatLocaleDateTime(isoString, localeCode) {
    const loc = localeCode || activeLocaleCode || 'tr-TR';
    const d = new Date(isoString);
    if (Number.isNaN(d.getTime())) return String(isoString ?? '');
    return new Intl.DateTimeFormat(loc, {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
      timeZone: 'UTC'
    }).format(d) + ' UTC';
  }

  function formatPhysicalUnit(value, unit = '%', localeCode, options = {}) {
    const loc = localeCode || activeLocaleCode || 'tr-TR';
    const num = Number(value);
    if (!Number.isFinite(num)) return String(value ?? '');
    const digits = Number.isFinite(Number(options.fractionDigits))
      ? Number(options.fractionDigits)
      : (unit === '%' || unit === 'hPa' ? 0 : 2);
    const formattedNum = formatLocaleNumber(num, loc, digits);
    const cleanUnit = String(unit || '').trim();
    if (cleanUnit === '%') {
      return loc.startsWith('tr') ? `%${formattedNum}` : `${formattedNum}%`;
    }
    return `${formattedNum} ${cleanUnit}`.trim();
  }

  function formatLocalePlural(count, forms = {}, localeCode) {
    const loc = localeCode || activeLocaleCode || 'tr-TR';
    const num = Number(count);
    const formattedCount = Number.isFinite(num) ? formatLocaleNumber(num, loc, 0) : String(count ?? 0);
    let rule = 'other';
    try {
      if (typeof Intl !== 'undefined' && typeof Intl.PluralRules === 'function') {
        rule = new Intl.PluralRules(loc).select(Number.isFinite(num) ? num : 0);
      }
    } catch (_) {}
    const template = forms[rule] || forms.other || forms.one || '{count}';
    return String(template).replace(/\{count\}/g, formattedCount);
  }

