    { code: 'sv-SE', nativeName: 'Svenska', label: 'İsveççe (BCP 47 Katalog)', dir: 'ltr', keyCoveragePct: 0, humanReviewedPct: 0, packStatus: 'YEDEK_DIL_FALLBACK' }
