  let dynamicTranslationPolicy = {
    enabled: false,
    provider: 'NONE',
    userConsentGranted: false,
    showOriginalTextAlways: true,
    translateUserEntityNames: false
  };

  function getDynamicTranslationPolicy() {
    return { ...dynamicTranslationPolicy };
  }

  function setDynamicTranslationPolicy(nextPolicy = {}) {
    dynamicTranslationPolicy = {
      enabled: Boolean(nextPolicy.enabled && nextPolicy.userConsentGranted),
      provider: String(nextPolicy.provider || 'NONE'),
      userConsentGranted: Boolean(nextPolicy.userConsentGranted),
      showOriginalTextAlways: true, // Always preserve original text visibility
      translateUserEntityNames: false // Never mutate user entity IDs/names
    };
    return getDynamicTranslationPolicy();
  }

  function listWorldLanguageCatalog(searchQuery = '') {
    const q = String(searchQuery || '').trim().toLowerCase();
    const supportedMap = new Map(listSupportedLanguages().map(l => [l.code, l]));
    return WORLD_LANGUAGE_CATALOG.map(entry => {
      const live = supportedMap.get(entry.code);
      return {
        ...entry,
        keyCoveragePct: live ? live.completenessPct : entry.keyCoveragePct,
        humanReviewedPct: (live && typeof live.humanReviewedPct === 'number') ? live.humanReviewedPct : entry.humanReviewedPct,
        reviewStatus: (live && live.reviewStatus) ? live.reviewStatus : 'INSAN_INCELEMESI_BEKLIYOR',
        isInstalledPack: Boolean(live)
      };
    }).filter(item => {
      if (!q) return true;
      return item.code.toLowerCase().includes(q) ||
        item.nativeName.toLowerCase().includes(q) ||
        item.label.toLowerCase().includes(q);
    });
  }

  function scanUntranslatedKeys(targetLocaleCode) {
    const loc = targetLocaleCode || activeLocaleCode || 'tr-TR';
    const refKeys = Object.keys(BUILTIN_LOCALE_PACKS['tr-TR'].strings);
    const pack = registeredLocalePacks[loc];
    if (!pack) {
      return {
        locale: loc,
        registered: false,
        totalReferenceKeys: refKeys.length,
        missingKeys: refKeys,
        untranslatedCount: refKeys.length,
        completenessPct: 0
      };
    }
    const missingKeys = refKeys.filter(k => !pack.strings || typeof pack.strings[k] !== 'string' || !pack.strings[k].trim());
    return {
      locale: loc,
      registered: true,
      dir: pack.meta.dir,
      totalReferenceKeys: refKeys.length,
      missingKeys,
      untranslatedCount: missingKeys.length,
      completenessPct: Math.round(((refKeys.length - missingKeys.length) / Math.max(1, refKeys.length)) * 100)
    };
  }

  function auditDomTranslations(rootEl) {
    const nodes = rootEl && typeof rootEl.querySelectorAll === 'function'
      ? Array.from(rootEl.querySelectorAll('[data-i18n]'))
      : [];
    const rawKeyLeaks = [];
    const emptyTextNodes = [];
    nodes.forEach(node => {
      const key = node.getAttribute('data-i18n') || '';
      const txt = String(node.textContent || '').trim();
      if (!txt) {
        emptyTextNodes.push(key);
      } else if (txt === key && key.includes('.')) {
        rawKeyLeaks.push(key);
      }
    });
    return {
      checkedNodeCount: nodes.length,
      rawKeyLeaks,
      emptyTextNodes,
      passed: rawKeyLeaks.length === 0 && emptyTextNodes.length === 0
    };
  }

  function formatEntityDisplay(entity, options = {}) {
    if (!entity || typeof entity !== 'object') return { id: '', displayName: '' };
    // CRITICAL RULE: Never mutate or auto-translate user-defined entity IDs or labels!
    const preservedId = String(entity.id || '');
    const preservedUserLabel = String(entity.label || entity.name || preservedId);
    const allowSampleTranslation = Boolean(options.translateSampleDescriptions);
    const isSample = entity.sourceType === 'FICTIONAL_SAMPLE' || entity.data_source === 'FICTIONAL_SAMPLE';
    const localizedLabel = (allowSampleTranslation && isSample && entity.i18nLabels && entity.i18nLabels[activeLocaleCode])
      ? entity.i18nLabels[activeLocaleCode]
      : preservedUserLabel;
    return {
      id: preservedId,
      displayName: localizedLabel,
      userOriginalLabelPreserved: preservedUserLabel,
      wasTranslated: localizedLabel !== preservedUserLabel
    };
  }

  function getI18nAuditReport() {
    const refKeys = Object.keys(BUILTIN_LOCALE_PACKS['tr-TR'].strings);
    const localesSummary = Object.entries(registeredLocalePacks).map(([code, pack]) => {
      const missingKeys = refKeys.filter(k => !pack.strings || typeof pack.strings[k] !== 'string' || !pack.strings[k].trim());
      return {
        code,
        label: pack.meta.label,
        nativeName: pack.meta.nativeName,
        dir: pack.meta.dir,
        completenessPct: Math.round(((refKeys.length - missingKeys.length) / Math.max(1, refKeys.length)) * 100),
        missingKeyCount: missingKeys.length,
        missingKeys,
        humanReviewedPct: typeof pack.meta.humanReviewedPct === 'number' ? pack.meta.humanReviewedPct : 0,
        reviewStatus: pack.meta.reviewStatus || 'INSAN_INCELEMESI_BEKLIYOR',
        catalogVersion: pack.meta.catalogVersion || I18N_CATALOG_VERSION,
        completedDomains: pack.meta.completedDomains || [],
        machineTranslated: Boolean(pack.meta.machineTranslated),
        expertReviewRequired: Boolean(pack.meta.machineTranslated && !pack.meta.expertReviewed),
        offlineReady: true
      };
    });
    return {
      activeLocale: activeLocaleCode,
      catalogVersion: I18N_CATALOG_VERSION,
      target12Locales: TARGET_12_LOCALES,
      totalReferenceKeys: refKeys.length,
      offlineModeOnly: true,
      externalTranslationServiceUsed: false,
      userEntityNamesAutoTranslated: false,
      plainLanguageGlossary: PLAIN_LANGUAGE_GLOSSARY,
      expertReviewRequiredTerms: EXPERT_REVIEW_REQUIRED_TERMS,
      locales: localesSummary,
      recentFallbacks: fallbackAuditLog.slice(-20)
    };
  }

  const i18nApi = Object.freeze({
    I18N_STORAGE_KEY,
    I18N_CATALOG_VERSION,
    TARGET_12_LOCALES,
    EXPERT_REVIEW_REQUIRED_TERMS,
    PLAIN_LANGUAGE_GLOSSARY,
    WORLD_LANGUAGE_CATALOG,
    isRtlLocale,
    detectDeviceLocale,
    registerLocalePack,
    resetLocalePacksToBuiltin,
    listSupportedLanguages,
    listWorldLanguageCatalog,
    setActiveLocale,
    getActiveLocale,
    translate,
    getPlainLanguageTerm,
    formatLocaleNumber,
    formatLocaleCurrency,
    formatLocaleDateTime,
    formatPhysicalUnit,
    formatLocalePlural,
    getDynamicTranslationPolicy,
    setDynamicTranslationPolicy,
    scanUntranslatedKeys,
    auditDomTranslations,
    formatEntityDisplay,
    getI18nAuditReport
  });

  root.CaelusI18n = i18nApi;

