  function computeHaversineDistanceKm(lat1, lon1, lat2, lon2) {
    const aLat = Number(lat1);
    const aLon = Number(lon1);
    const bLat = Number(lat2);
    const bLon = Number(lon2);
    if (!Number.isFinite(aLat) || !Number.isFinite(aLon) || !Number.isFinite(bLat) || !Number.isFinite(bLon)) {
      return null;
    }
    const R = 6371.0;
    const dLat = ((bLat - aLat) * Math.PI) / 180.0;
    const dLon = ((bLon - aLon) * Math.PI) / 180.0;
    const rLat1 = (aLat * Math.PI) / 180.0;
    const rLat2 = (bLat * Math.PI) / 180.0;
    const sinDLat = Math.sin(dLat / 2.0);
    const sinDLon = Math.sin(dLon / 2.0);
    const h = sinDLat * sinDLat + Math.cos(rLat1) * Math.cos(rLat2) * sinDLon * sinDLon;
    const c = 2.0 * Math.atan2(Math.sqrt(Math.max(0, h)), Math.sqrt(Math.max(0, 1.0 - h)));
    return Number((R * c).toFixed(2));
  }

  function parseUsgsEarthquakeGeoJsonPayload(rawPayloadInput, options = {}) {
    const ingestedAtIso = String(options.ingestedAtIso || new Date().toISOString());
    const refIso = String(options.referenceNowIso || options.referenceTimeIso || ingestedAtIso);
    const refNowMs = Date.parse(refIso);
    const freshnessThresholdMinutes = clamp(Number(options.freshnessThresholdMinutes || 1440), 5, 43200);
    const refLat = Number.isFinite(Number(options.referenceLat)) ? Number(options.referenceLat) : 38.4381;
    const refLon = Number.isFinite(Number(options.referenceLon)) ? Number(options.referenceLon) : 27.1417;
    const refLabel = String(options.referenceLabel || 'İzmir Körfezi / Alsancak Limanı (Ege Referansı)');

    if (rawPayloadInput === null || rawPayloadInput === undefined || rawPayloadInput === '') {
      return {
        status: 'EMPTY_PAYLOAD',
        valid: false,
        records: [],
        recordsByVariable: {},
        seismicEvents: [],
        errors: ['Boş USGS GeoJSON yanıtı: Veri paketi boş.']
      };
    }

    let geoObj = null;
    if (typeof rawPayloadInput === 'string') {
      const trimmed = rawPayloadInput.trim();
      if (trimmed.length > 262144) {
        return {
          status: 'PAYLOAD_TOO_LARGE',
          valid: false,
          records: [],
          recordsByVariable: {},
          seismicEvents: [],
          errors: [`USGS GeoJSON yanıt boyutu sınırı aşıldı (${trimmed.length} > 262144 bayt).`]
        };
      }
      try {
        geoObj = JSON.parse(trimmed);
      } catch (err) {
        return {
          status: 'MALFORMED_JSON',
          valid: false,
          records: [],
          recordsByVariable: {},
          seismicEvents: [],
          errors: [`Bozuk USGS GeoJSON yanıtı: ${err && err.message ? err.message : 'JSON ayrıştırılamadı'}. Değer uydurulmadı.`]
        };
      }
    } else if (typeof rawPayloadInput === 'object' && !Array.isArray(rawPayloadInput)) {
      geoObj = rawPayloadInput;
    }

    if (!geoObj || !Array.isArray(geoObj.features)) {
      return {
        status: 'INVALID_GEOJSON_SCHEMA',
        valid: false,
        records: [],
        recordsByVariable: {},
        seismicEvents: [],
        errors: ['Geçersiz USGS GeoJSON şeması: "features" dizisi bulunamadı.']
      };
    }

    const rawPayloadHash = `FNV32-${hex32(hash32(JSON.stringify(geoObj)))}`;
    const validEvents = [];
    const errors = [];

    geoObj.features.forEach((feat, idx) => {
      if (!feat || typeof feat !== 'object') return;
      const props = feat.properties || {};
      const geom = feat.geometry || {};
      const coords = Array.isArray(geom.coordinates) ? geom.coordinates : [];
      const lon = coords.length >= 2 && coords[0] !== null ? Number(coords[0]) : NaN;
      const lat = coords.length >= 2 && coords[1] !== null ? Number(coords[1]) : NaN;
      const depthKm = coords.length >= 3 && coords[2] !== null ? Number(coords[2]) : NaN;
      const mag = props.mag !== null && props.mag !== undefined ? Number(props.mag) : NaN;
      const timeMs = props.time !== null && props.time !== undefined ? Number(props.time) : NaN;
      const updatedMs = props.updated !== null && props.updated !== undefined ? Number(props.updated) : NaN;

      if (!Number.isFinite(lat) || lat < -90 || lat > 90 || !Number.isFinite(lon) || lon < -180 || lon > 180) {
        errors.push(`Olay #${idx + 1}: Geçersiz deprem koordinatı [${lon}, ${lat}] reddedildi.`);
        return;
      }
      if (!Number.isFinite(mag) || mag < -2.0 || mag > 10.0) {
        errors.push(`Olay #${idx + 1}: Geçersiz deprem büyüklüğü (${props.mag}) reddedildi.`);
        return;
      }
      if (!Number.isFinite(depthKm) || depthKm < -5.0 || depthKm > 800.0) {
        errors.push(`Olay #${idx + 1}: Geçersiz odak derinliği (${ coords[2] }) reddedildi.`);
        return;
      }

      const validTimeIso = Number.isFinite(timeMs) && timeMs > 0
        ? new Date(timeMs).toISOString().replace(/\.000Z$/, 'Z')
        : ingestedAtIso;
      const publishedTimeIso = Number.isFinite(updatedMs) && updatedMs > 0
        ? new Date(updatedMs).toISOString().replace(/\.000Z$/, 'Z')
        : 'BİLİNMİYOR';
      const distKm = computeHaversineDistanceKm(refLat, refLon, lat, lon);
      // Attenuated structural stress index [0..100%]: combines magnitude Mw and distance attenuation
      const magFactor = clamp((mag - 2.5) / (7.0 - 2.5), 0.0, 1.0);
      const distAttenuation = distKm !== null ? clamp(1.0 - (distKm / 350.0), 0.15, 1.0) : 0.5;
      const stressPct = clamp(Math.round(magFactor * distAttenuation * 100), 4, 100);

      validEvents.push({
        eventId: String(feat.id || `USGS-${idx + 1}`),
        title: String(props.title || props.place || `Mw ${mag.toFixed(1)} Ege Depremi`),
        place: String(props.place || 'Ege-Akdeniz Sismik Kuşağı'),
        magnitude: Number(mag.toFixed(2)),
        magType: String(props.magType || 'Mw'),
        depthKm: Number(depthKm.toFixed(1)),
        lat: Number(lat.toFixed(4)),
        lon: Number(lon.toFixed(4)),
        distanceKm: distKm,
        structuralStressPct: stressPct,
        validTimeIso,
        publishedTimeIso,
        sourceUrl: String(props.url || 'https://earthquake.usgs.gov/fdsnws/event/1/')
      });
    });

    if (validEvents.length === 0) {
      return {
        status: 'NO_VALID_SEISMIC_EVENTS',
        valid: false,
        records: [],
        recordsByVariable: {},
        seismicEvents: [],
        errors: errors.length > 0 ? errors : ['USGS GeoJSON içinde geçerli sismik olay kaydı bulunamadı.']
      };
    }

    // Select the most significant event (highest attenuated stress / magnitude) as primary world-linked record
    validEvents.sort((a, b) => (b.structuralStressPct - a.structuralStressPct) || (b.magnitude - a.magnitude));
    const primary = validEvents[0];
    const ageMin = !Number.isNaN(Date.parse(primary.validTimeIso)) && !Number.isNaN(refNowMs)
      ? Math.max(0, Math.round((refNowMs - Date.parse(primary.validTimeIso)) / 60000))
      : 0;
    const isStale = ageMin > freshnessThresholdMinutes;
    const freshnessStatus = isStale ? 'STALE' : 'FRESH';
    const freshnessBadge = isStale
      ? `⏱ ESKİ SİSMİK KAYIT (${ageMin} dk önce)`
      : `✓ GÜNCEL SİSMİK GÖZLEM (${ageMin} dk önce)`;

    const requestedLocation = {
      id: 'USGS_EPICENTER_PRIMARY',
      label: `${primary.place} (${primary.lat.toFixed(2)}°K, ${primary.lon.toFixed(2)}°D)`,
      lat: primary.lat,
      lon: primary.lon,
      region: 'Ege-Anadolu Sismik Kuşağı',
      referencePortLabel: refLabel,
      referenceDistanceKm: primary.distanceKm
    };

    const makeSeismicRecord = (varName, labelTr, val, unit, rangeMin, rangeMax) => ({
      recordId: `REC-USGS-${varName}-${primary.eventId}`,
      connectorId: String(options.connectorId || 'UNIV_USGS_SEISMIC_AEGEAN'),
      category: 'ENVIRONMENT_SEISMIC',
      apiGroup: 'SEISMIC_GEOJSON',
      sourceName: 'USGS Earthquake Hazards Program (FDSNWS GeoJSON)',
      providerUrl: primary.sourceUrl,
      modelName: 'USGS ANSS Comprehensive Earthquake Catalog (ComCat)',
      modelVersion: 'FDSNWS-Event-v1',
      licenseAttribution: 'Public Domain (U.S. Geological Survey — earthquake.usgs.gov)',
      dataKind: 'OBSERVATION',
      dataKindBadge: 'GÖZLEM (SİSMOGRAF KAYDI)',
      variableName: varName,
      variableLabelTr: labelTr,
      rawValue: val,
      rawUnit: unit,
      normalizedValue: val,
      normalizedUnit: unit,
      unitConversions: {
        [unit]: val,
        displaySummary: `${val} ${unit} (${primary.place})`
      },
      physicalRange: [rangeMin, rangeMax],
      isValid: true,
      validationStatus: 'VALID',
      validationMessage: 'Geçerli sismograf gözlemi',
      hasCoordinates: true,
      requestedLocation,
      gridCellLocation: {
        lat: primary.lat,
        lon: primary.lon,
        elevationM: -primary.depthKm * 1000,
        note: `Deprem Merkez Üssü (${primary.lat}°K, ${primary.lon}°D, Derinlik: ${primary.depthKm} km)`
      },
      validTimeIso: primary.validTimeIso,
      modelPublishedTimeIso: primary.publishedTimeIso,
      ingestedAtIso,
      ageMinutes: ageMin,
      freshnessStatus,
      freshnessBadge,
      freshnessLabel: freshnessBadge,
      rawPayloadHash
    });

    const records = [
      makeSeismicRecord('seismic_magnitude', 'Deprem Büyüklüğü (Mw)', primary.magnitude, 'Mw', 0, 10),
      makeSeismicRecord('focal_depth_km', 'Deprem Odak Derinliği', primary.depthKm, 'km', 0, 750),
      makeSeismicRecord('epicenter_distance_km', 'Merkez Üssü Mesafesi (Referans Limana)', primary.distanceKm ?? 0, 'km', 0, 20000),
      makeSeismicRecord('seismic_structural_stress_pct', 'Sismik Altyapı Sarsıntı İndeksi', primary.structuralStressPct, '%', 0, 100)
    ];

    const recordsByVariable = {};
    records.forEach(r => { recordsByVariable[r.variableName] = r; });

    return {
      status: 'VALID',
      valid: true,
      category: 'ENVIRONMENT_SEISMIC',
      requestedLocation,
      validTimeIso: primary.validTimeIso,
      modelPublishedTimeIso: primary.publishedTimeIso,
      ingestedAtIso,
      rawPayloadHash,
      records,
      recordsByVariable,
      seismicEvents: validEvents,
      missingVariables: [],
      invalidVariables: [],
      errors
    };
  }

