  function parseOpenMeteoGeocodingPayload(rawPayloadInput, options = {}) {
    const ingestedAtIso = String(options.ingestedAtIso || new Date().toISOString());
    if (!rawPayloadInput) {
      return {
        status: 'EMPTY_PAYLOAD',
        valid: false,
        records: [],
        recordsByVariable: {},
        locations: [],
        errors: ['Boş Open-Meteo Geocoding yanıtı.']
      };
    }
    let geoObj = null;
    if (typeof rawPayloadInput === 'string') {
      try {
        geoObj = JSON.parse(rawPayloadInput.trim());
      } catch (err) {
        return {
          status: 'MALFORMED_JSON',
          valid: false,
          records: [],
          recordsByVariable: {},
          locations: [],
          errors: [`Bozuk Geocoding JSON yanıtı: ${err && err.message ? err.message : 'JSON hatası'}.`]
        };
      }
    } else if (typeof rawPayloadInput === 'object') {
      geoObj = rawPayloadInput;
    }

    const results = (geoObj && Array.isArray(geoObj.results)) ? geoObj.results : [];
    if (results.length === 0) {
      return {
        status: 'NO_GEOCODING_RESULTS',
        valid: false,
        records: [],
        recordsByVariable: {},
        locations: [],
        errors: ['Jeokodlama sorgusu için yerleşim sonucu bulunamadı.']
      };
    }

    const first = results[0];
    const lat = Number(first.latitude);
    const lon = Number(first.longitude);
    const elev = Number.isFinite(Number(first.elevation)) ? Number(first.elevation) : 0;
    const pop = Number.isFinite(Number(first.population)) ? Number(first.population) : 0;
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
      return {
        status: 'INVALID_COORDINATES',
        valid: false,
        records: [],
        recordsByVariable: {},
        locations: [],
        errors: ['Jeokodlama yanıtında geçerli enlem/boylam bulunamadı.']
      };
    }

    const rawPayloadHash = `FNV32-${hex32(hash32(JSON.stringify(geoObj)))}`;
    const locLabel = `${first.name || 'İzmir'} (${first.admin1 || first.country || 'TR'})`;
    const requestedLocation = {
      id: `GEOCODE-${first.id || 'IZMIR'}`,
      label: locLabel,
      lat: Number(lat.toFixed(4)),
      lon: Number(lon.toFixed(4)),
      elevationM: elev,
      region: String(first.country || 'Türkiye')
    };

    const records = [
      {
        recordId: `REC-GEO-ELEV-${first.id || '1'}`,
        connectorId: String(options.connectorId || 'UNIV_OPEN_METEO_GEOCODING'),
        category: 'GEO_SPACE',
        apiGroup: 'GEOCODING_DEM',
        sourceName: 'Open-Meteo Geocoding & Copernicus DEM 90m',
        providerUrl: 'https://geocoding-api.open-meteo.com/v1/search?name=Izmir&count=5&language=tr&format=json',
        modelName: 'GeoNames + Copernicus DEM',
        modelVersion: 'v1',
        licenseAttribution: 'CC-BY 4.0 (Open-Meteo.com & GeoNames.org)',
        dataKind: 'OBSERVATION',
        dataKindBadge: 'COĞRAFİ RAKIM & KOORDİNAT KAYDI',
        variableName: 'elevation_m',
        variableLabelTr: `${locLabel} Deniz Seviyesinden Rakım`,
        rawValue: elev,
        rawUnit: 'm',
        normalizedValue: elev,
        normalizedUnit: 'm',
        unitConversions: { m: elev, displaySummary: `${elev} m (${locLabel}: ${lat.toFixed(4)}°K, ${lon.toFixed(4)}°D)` },
        physicalRange: [-450, 9000],
        isValid: true,
        validationStatus: 'VALID',
        validationMessage: 'Geçerli Copernicus DEM rakım kaydı',
        hasCoordinates: true,
        requestedLocation,
        gridCellLocation: { lat: Number(lat.toFixed(4)), lon: Number(lon.toFixed(4)), elevationM: elev },
        validTimeIso: ingestedAtIso,
        modelPublishedTimeIso: 'BİLİNMİYOR',
        ingestedAtIso,
        ageMinutes: 0,
        freshnessStatus: 'FRESH',
        freshnessBadge: '✓ DOĞRULANMIŞ KOORDİNAT',
        freshnessLabel: '✓ DOĞRULANMIŞ KOORDİNAT',
        rawPayloadHash
      },
      {
        recordId: `REC-GEO-POP-${first.id || '1'}`,
        connectorId: String(options.connectorId || 'UNIV_OPEN_METEO_GEOCODING'),
        category: 'GEO_SPACE',
        apiGroup: 'GEOCODING_DEM',
        sourceName: 'Open-Meteo Geocoding & GeoNames.org',
        providerUrl: 'https://geocoding-api.open-meteo.com/v1/search?name=Izmir&count=5&language=tr&format=json',
        modelName: 'GeoNames Gazetteer',
        modelVersion: 'v1',
        licenseAttribution: 'CC-BY 4.0 (GeoNames.org)',
        dataKind: 'HISTORICAL_RECORD',
        dataKindBadge: 'COĞRAFİ YERLEŞİM KAYDI',
        variableName: 'settlement_population',
        variableLabelTr: `${locLabel} Yerleşim Nüfusu`,
        rawValue: pop,
        rawUnit: 'kişi',
        normalizedValue: pop,
        normalizedUnit: 'kişi',
        unitConversions: { 'kişi': pop, displaySummary: `${pop.toLocaleString('tr-TR')} kişi` },
        physicalRange: [0, 50000000],
        isValid: true,
        validationStatus: 'VALID',
        validationMessage: 'Geçerli GeoNames nüfus kaydı',
        hasCoordinates: true,
        requestedLocation,
        gridCellLocation: { lat: Number(lat.toFixed(4)), lon: Number(lon.toFixed(4)), elevationM: elev },
        validTimeIso: ingestedAtIso,
        modelPublishedTimeIso: 'BİLİNMİYOR',
        ingestedAtIso,
        ageMinutes: 0,
        freshnessStatus: 'FRESH',
        freshnessBadge: '✓ DOĞRULANMIŞ KOORDİNAT',
        freshnessLabel: '✓ DOĞRULANMIŞ KOORDİNAT',
        rawPayloadHash
      }
    ];

    const recordsByVariable = {};
    records.forEach(r => { recordsByVariable[r.variableName] = r; });

    return {
      status: 'VALID',
      valid: true,
      category: 'GEO_SPACE',
      requestedLocation,
      validTimeIso: ingestedAtIso,
      modelPublishedTimeIso: 'BİLİNMİYOR',
      ingestedAtIso,
      rawPayloadHash,
      records,
      recordsByVariable,
      locations: results.map(r => ({
        id: r.id,
        name: r.name,
        lat: Number(r.latitude),
        lon: Number(r.longitude),
        elevationM: Number(r.elevation || 0),
        country: r.country || 'Türkiye',
        admin1: r.admin1 || '',
        population: Number(r.population || 0),
        timezone: r.timezone || 'Europe/Istanbul'
      })),
      missingVariables: [],
      invalidVariables: [],
      errors: []
    };
  }

