  function ensureWorldUniversalDataNetwork(world) {
    if (!world || typeof world !== 'object') return null;
    if (!world.universalDataNetwork || typeof world.universalDataNetwork !== 'object') {
      world.universalDataNetwork = {
        version: '1.0.0',
        offlineModeDefault: true,
        secretBackgroundFetchForbidden: true,
        activeConnectors: {},
        customConnectors: [],
        connectionAuditLog: []
      };
    }
    const net = world.universalDataNetwork;
    if (!net.activeConnectors || typeof net.activeConnectors !== 'object') {
      net.activeConnectors = {};
    }
    if (!Array.isArray(net.customConnectors)) net.customConnectors = [];
    if (!Array.isArray(net.connectionAuditLog)) net.connectionAuditLog = [];

    // Populate default catalog states WITHOUT starting any internet connection secretly
    Object.values(UNIVERSAL_DATA_NETWORK_CATALOG).forEach(cat => {
      if (!net.activeConnectors[cat.catalogId]) {
        const isPlanned = cat.implementationStatus === 'PLANNED_EXTENSIBLE';
        const supportStatus = cat.supportStatus || (isPlanned ? 'AWAITING_API_KEY_OR_AUTH' : 'CONNECTED_VERIFIED');
        const supportStatusBadgeTr = cat.supportStatusBadgeTr || (
          supportStatus === 'CONNECTED_VERIFIED' ? 'BAĞLI VE DOĞRULANDI' :
          supportStatus === 'AWAITING_API_KEY_OR_AUTH' ? 'API ANAHTARI VEYA YETKİ BEKLİYOR' :
          supportStatus === 'UNAVAILABLE' ? 'ŞU ANDA ERİŞİLEMİYOR' : 'PLANLANDI, HENÜZ GELİŞTİRİLMEDİ'
        );
        net.activeConnectors[cat.catalogId] = {
          catalogId: cat.catalogId,
          driverId: cat.driverId,
          name: cat.name,
          version: cat.version,
          providerName: cat.providerName,
          providerUrl: cat.providerUrl,
          category: cat.category,
          categoryLabelTr: cat.categoryLabelTr,
          supportedGeography: cat.supportedGeography,
          hasCoordinates: cat.hasCoordinates,
          accessMethod: cat.accessMethod,
          endpointUrl: cat.defaultEndpointUrl,
          secondaryEndpointUrl: cat.secondaryEndpointUrl || null,
          supportedVariables: cat.supportedVariables,
          updateFrequency: cat.updateFrequency,
          authRequirement: cat.authRequirement,
          license: cat.license,
          attribution: cat.attribution,
          rateLimitPolicy: cat.rateLimitPolicy,
          costPolicy: cat.costPolicy,
          dataKind: cat.dataKind,
          dataKindBadge: cat.dataKindBadge,
          implementationStatus: cat.implementationStatus,
          supportStatus,
          supportStatusBadgeTr,
          implementationBadgeTr: cat.implementationBadgeTr,
          purposeTr: cat.purposeTr,
          minPollIntervalSec: Number(cat.minPollIntervalSec || 30),
          pollIntervalSec: Number(cat.minPollIntervalSec || 60),
          supportsHistoricalBackfill: Boolean(cat.supportsHistoricalBackfill),
          enabled: false,
          userOptInGranted: false,
          userOptInTimestampIso: null,
          connectionState: isPlanned ? 'PLANNED_EXTENSIBLE' : 'DISABLED_OPT_IN_REQUIRED',
          freshnessState: 'NO_DATA_YET',
          lastSuccessIso: null,
          lastCheckIso: null,
          lastPayloadHash: null,
          lastError: null,
          disconnectedAtIso: null,
          reconnectAttempts: 0,
          nextRetryDelaySec: 0,
          ingestedRecordCount: 0,
          duplicateSkipCount: 0,
          rateLimitSkipCount: 0,
          maxRecordsPerSource: 200,
          retentionDays: 90,
          checkHistory: [],
          errorLog: [],
          credentialsMasked: 'YETKİ ANAHTARI GEREKMİYOR (SALT OKUNUR)'
        };
      }
    });
    if (typeof net.allNetworkPaused !== 'boolean') {
      net.allNetworkPaused = false;
    }
    if (!net.executionArchitectureMode) {
      net.executionArchitectureMode = 'LOCAL_PROCESS_MODE';
    }
    return net;
  }

  function listUniversalConnectorCatalog(world = null) {
    if (world) {
      const net = ensureWorldUniversalDataNetwork(world);
      return [
        ...Object.values(net.activeConnectors),
        ...(net.customConnectors || [])
      ];
    }
    return Object.values(UNIVERSAL_DATA_NETWORK_CATALOG).map(c => ({ ...c }));
  }

  function enableUniversalConnector(world, catalogId, options = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) throw new Error('Evrensel Veri Ağı için geçerli bir dijital dünya gereklidir.');
    const nowIso = String(options.nowIso || new Date().toISOString());
    const entry = net.activeConnectors[catalogId] || (net.customConnectors || []).find(c => c.catalogId === catalogId);
    if (!entry) {
      return {
        ok: false,
        code: 'UNKNOWN_CONNECTOR',
        reason: `Tanımsız bağlayıcı kimliği: "${catalogId}"`
      };
    }
    if (entry.implementationStatus === 'PLANNED_EXTENSIBLE') {
      return {
        ok: false,
        code: 'PLANNED_CONNECTOR_NOT_IMPLEMENTED',
        reason: `"${entry.name}" şu anda "Planlanan / Bağlantı Eklenebilir" statüsündedir; kurumsal API anahtarı veya iç ağ geçidi olmadan sahte bağlantı kurulmaz.`
      };
    }
    if (entry.userOptInRequired !== false && options.userApprovedInternet !== true) {
      return {
        ok: false,
        code: 'USER_OPT_IN_REQUIRED',
        reason: `Güvenlik ve Gizlilik İlkesi: "${entry.name}" dış veri kaynağına bağlanmak için kullanıcının açık onayı (userApprovedInternet=true) zorunludur.`
      };
    }

    entry.enabled = true;
    entry.userOptInGranted = true;
    entry.userOptInTimestampIso = nowIso;
    entry.connectionState = 'ENABLED_READY';
    entry.lastError = null;

    net.connectionAuditLog.unshift({
      auditId: `AUD-EN-${hex32(hash32(catalogId + nowIso)).slice(0, 6)}`,
      timestampIso: nowIso,
      action: 'CONNECTOR_ENABLED_BY_USER',
      catalogId: entry.catalogId,
      providerName: entry.providerName,
      endpointUrl: entry.endpointUrl,
      note: 'Kullanıcı açık onayıyla veri kaynağı etkinleştirildi.'
    });

    return { ok: true, connector: entry };
  }

  function pauseUniversalConnector(world, catalogId, options = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, code: 'NO_WORLD' };
    const nowIso = String(options.nowIso || new Date().toISOString());
    const entry = net.activeConnectors[catalogId] || (net.customConnectors || []).find(c => c.catalogId === catalogId);
    if (!entry) return { ok: false, code: 'UNKNOWN_CONNECTOR' };

    entry.enabled = false;
    entry.connectionState = entry.implementationStatus === 'PLANNED_EXTENSIBLE' ? 'PLANNED_EXTENSIBLE' : 'PAUSED_BY_USER';
    net.connectionAuditLog.unshift({
      auditId: `AUD-PAUSE-${hex32(hash32(catalogId + nowIso)).slice(0, 6)}`,
      timestampIso: nowIso,
      action: 'CONNECTOR_PAUSED_BY_USER',
      catalogId: entry.catalogId,
      providerName: entry.providerName,
      endpointUrl: entry.endpointUrl,
      note: 'Kullanıcı tarafından veri kaynağı duraklatıldı.'
    });
    return { ok: true, connector: entry };
  }

  function removeUniversalConnector(world, catalogId, options = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, code: 'NO_WORLD' };
    const nowIso = String(options.nowIso || new Date().toISOString());
    const customIdx = (net.customConnectors || []).findIndex(c => c.catalogId === catalogId);
    if (customIdx >= 0) {
      const removed = net.customConnectors.splice(customIdx, 1)[0];
      net.connectionAuditLog.unshift({
        auditId: `AUD-REM-${hex32(hash32(catalogId + nowIso)).slice(0, 6)}`,
        timestampIso: nowIso,
        action: 'CUSTOM_CONNECTOR_REMOVED',
        catalogId,
        providerName: removed.providerName,
        endpointUrl: removed.endpointUrl,
        note: 'Kullanıcı tanımlı veri kaynağı kaldırıldı.'
      });
      return { ok: true, removedCustom: true, catalogId };
    }
    const entry = net.activeConnectors[catalogId];
    if (!entry) return { ok: false, code: 'UNKNOWN_CONNECTOR' };
    entry.enabled = false;
    entry.userOptInGranted = false;
    entry.connectionState = entry.implementationStatus === 'PLANNED_EXTENSIBLE' ? 'PLANNED_EXTENSIBLE' : 'DISABLED_OPT_IN_REQUIRED';
    return { ok: true, removedCustom: false, connector: entry };
  }

  function registerCustomUniversalConnector(world, customSpec = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) throw new Error('Özel veri kaynağı tanımlamak için aktif bir dijital dünya gereklidir.');
    const nowIso = String(customSpec.nowIso || new Date().toISOString());
    const name = String(customSpec.name || '').trim();
    const endpointUrl = String(customSpec.endpointUrl || '').trim();
    if (!name || !endpointUrl) {
      return {
        ok: false,
        code: 'MISSING_NAME_OR_URL',
        reason: 'Özel veri kaynağı için kaynak adı ve HTTP/HTTPS uç nokta adresi (URL) zorunludur.'
      };
    }

    const urlCheck = validateExternalConnectorUrl(endpointUrl, {
      connectorType: 'CUSTOM_AUTHORIZED_HTTP_JSON',
      method: 'GET',
      allowPrivateLan: Boolean(customSpec.allowPrivateLan),
      externalNetworkOptIn: true
    });
    if (!urlCheck.valid) {
      return {
        ok: false,
        code: urlCheck.code || 'INVALID_CUSTOM_URL',
        reason: urlCheck.reason
      };
    }

    const catalogId = String(customSpec.catalogId || `UNIV_CUSTOM_${hex32(hash32(name + endpointUrl + nowIso)).slice(0, 6)}`);
    const rawSecret = customSpec.apiKey || customSpec.bearerToken || customSpec.rawAuthSecret || '';
    const credentialsMasked = rawSecret ? redactCredentialValue(rawSecret) : 'YETKİ ANAHTARI GEREKMİYOR (SALT OKUNUR)';

    const customEntry = {
      catalogId,
      driverId: 'CUSTOM_AUTHORIZED_HTTP_JSON',
      name,
      version: String(customSpec.version || '1.0.0-custom'),
      providerName: String(customSpec.providerName || name),
      providerUrl: endpointUrl,
      category: String(customSpec.category || 'CUSTOM_AUTHORIZED'),
      categoryLabelTr: 'Kullanıcı Tanımlı Yetkili Kaynak (HTTP/JSON)',
      supportedGeography: String(customSpec.supportedGeography || 'Kullanıcı Tanımlı Coğrafya / Sistem'),
      hasCoordinates: Boolean(customSpec.hasCoordinates),
      accessMethod: urlCheck.isExternalNetwork ? 'HTTPS JSON (Kullanıcı Yetkili GET)' : 'Yerel Ağ HTTP JSON (LAN İzinli GET)',
      endpointUrl,
      supportedVariables: Array.isArray(customSpec.supportedVariables) && customSpec.supportedVariables.length > 0
        ? customSpec.supportedVariables
        : [{ name: String(customSpec.variableName || 'custom_metric_pct'), labelTr: String(customSpec.variableLabelTr || name), unit: String(customSpec.unit || '%'), range: [-10000, 100000] }],
      updateFrequency: String(customSpec.updateFrequency || 'İstek üzerine'),
      authRequirement: rawSecret ? 'API_KEY_MASKED' : 'NONE',
      license: String(customSpec.license || 'Kullanıcı Tanımlı Kaynak Lisansı'),
      attribution: String(customSpec.attribution || name),
      rateLimitPolicy: 'Maks. 256 KB, 6 sn zaman aşımı, salt-okunur GET',
      costPolicy: 'Kullanıcı tanımlı',
      dataKind: String(customSpec.dataKind || 'OBSERVATION'),
      dataKindBadge: 'KULLANICI YETKİLİ GÖZLEM KAYNAĞI',
      implementationStatus: 'WORKING_VERIFIED',
      implementationBadgeTr: 'ÇALIŞIYOR — KULLANICI TANIMLI KAYNAK',
      purposeTr: String(customSpec.purposeTr || 'Kullanıcı tarafından tanımlanan ve yetkilendirilen özel HTTP/JSON veri kaynağı.'),
      allowPrivateLan: Boolean(customSpec.allowPrivateLan),
      enabled: true,
      userOptInGranted: true,
      userOptInTimestampIso: nowIso,
      connectionState: 'ENABLED_READY',
      freshnessState: 'NO_DATA_YET',
      lastSuccessIso: null,
      lastError: null,
      ingestedRecordCount: 0,
      credentialsMasked
    };

    net.customConnectors.push(customEntry);
    net.connectionAuditLog.unshift({
      auditId: `AUD-CUST-${hex32(hash32(catalogId + nowIso)).slice(0, 6)}`,
      timestampIso: nowIso,
      action: 'CUSTOM_CONNECTOR_REGISTERED',
      catalogId,
      providerName: customEntry.providerName,
      endpointUrl: customEntry.endpointUrl,
      note: `Özel kaynak kaydedildi (Kimlik: ${credentialsMasked}, LAN İzni: ${customEntry.allowPrivateLan ? 'Açık' : 'Kapalı'}).`
    });

    return { ok: true, connector: customEntry };
  }

  /* ═════════════════════════════════════════════════════════════════════════
     BÖLÜM 8 & 9: SÜREKLİ TAKİP, ARKA PLAN GÜNCELLEME VE 7/24 MİMARİ AYRIMI
     - Kaynak bazlı kontrol sıklığı ve hız sınırı (rate-limit) koruması
     - İçerik özeti (hash) ile tekrarlı kayıt ve bildirim engelleme
     - Kesinti algılama, veri yaşı hesabı ve üstel geri çekilmeli yeniden bağlanma
     - Eksik dönem tamamlama (backfill) veya dürüst uyarı
     - Kota, saklama süresi (retention) ve kaynak verisi temizleme
     - Tüm ağ etkinliğini tek tuşla durdurma / devam ettirme
     - YEREL ÇALIŞMA MODU vs. İSTEĞE BAĞLI 7/24 SUNUCU MİMARİSİ TASLAĞI
     ═════════════════════════════════════════════════════════════════════════ */

  const SERVER_24_7_ARCHITECTURE_BLUEPRINT = Object.freeze({
    architectureId: 'CAELUS_OPTIONAL_24_7_SERVER_BLUEPRINT_V1',
    currentActiveMode: 'LOCAL_PROCESS_MODE',
    honestModeDisclosureTr: 'CAELUS şu anda Yerel Çalışma Modundadır: yalnızca bilgisayarınız ve CAELUS uygulaması açıkken kaynakları kontrol eder. Uygulama kapalıyken sahte 7/24 arka plan takibi yapılmış gibi gösterilmez.',
    honestModeDisclosureEn: 'CAELUS is currently running in Local Process Mode: it checks sources only while your computer and the CAELUS process are running. It never fabricates 24/7 background polling while closed.',
    autoCloudDeployForbidden: true,
    userApprovalAndSetupRequired: true,
    components: Object.freeze([
      {
        componentId: 'BACKGROUND_WORKER_SCHEDULER',
        titleTr: '1. Arka Plan İşçi Servisi (Worker Daemon)',
        descriptionTr: 'Kullanıcının kendi sunucusunda (systemd / Docker / Windows Service) çalışan, kaynak bazlı cron/interval zamanlayıcısı ve hız sınırı (token-bucket) denetleyicisi.'
      },
      {
        componentId: 'INGESTION_QUEUE_AND_DEDUP',
        titleTr: '2. Kuyruk, Tekrarlı Kayıt Önleme ve Eksik Dönem Tamamlama',
        descriptionTr: 'Gelen yanıtları FNV-1a / SHA-256 içerik özetiyle karşılaştıran, aynı veriyi tekrar yazmayan ve kesinti sonrası ERA5/USGS gibi tarih aralığı destekleyen kaynaklardan eksik dönemi (backfill) isteyen katman.'
      },
      {
        componentId: 'ENCRYPTED_CREDENTIAL_AND_EVENT_STORE',
        titleTr: '3. Şifreli Kimlik Kasası ve Zaman Damgalı Olay/Veri Deposu',
        descriptionTr: 'API anahtarlarını işletim sistemi kasasında (DPAPI / KMS) şifreleyen ve üç zaman damgalı (t_geçerli, t_yayın, t_giriş) kayıtları saklama süresi (retention) politikasıyla tutan depo.'
      },
      {
        componentId: 'USER_CONTROLLED_NOTIFICATION_GATE',
        titleTr: '4. Kullanıcı Kontrollü Bildirim ve Sessiz Saatler Geçidi',
        descriptionTr: 'Yalnızca kullanıcının belirlediği eşikleri aşan ve tekrarlı olmayan değişiklikleri bildiren, sessiz saatler ve bildirim sıklığı sınırına uyan katman.'
      }
    ])
  });

  function findUniversalConnectorEntry(net, catalogId) {
    if (!net) return null;
    return net.activeConnectors[catalogId] || (net.customConnectors || []).find(c => c.catalogId === catalogId) || null;
  }

  function configureContinuousTracking(world, catalogId, config = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, code: 'NO_WORLD' };
    const entry = findUniversalConnectorEntry(net, catalogId);
    if (!entry) return { ok: false, code: 'UNKNOWN_CONNECTOR' };

    if (config.enabled !== undefined) {
      entry.enabled = Boolean(config.enabled);
      if (entry.enabled) entry.userOptInGranted = true;
    }
    if (config.minPollIntervalSec !== undefined) {
      entry.minPollIntervalSec = Math.max(5, Number(config.minPollIntervalSec));
    }
    const minAllowed = Math.max(5, Number(entry.minPollIntervalSec || 10));
    if (config.pollIntervalSec !== undefined) {
      const requested = Number(config.pollIntervalSec);
      entry.pollIntervalSec = clamp(Math.round(requested), minAllowed, 86400);
      entry.rateLimitClamped = requested < minAllowed;
    }
    if (config.maxRecordsPerSource !== undefined) {
      entry.maxRecordsPerSource = clamp(Math.round(Number(config.maxRecordsPerSource)), 10, 10000);
    }
    if (config.retentionDays !== undefined) {
      entry.retentionDays = clamp(Math.round(Number(config.retentionDays)), 1, 3650);
    }
    if (config.scopeGeography !== undefined) {
      entry.supportedGeography = String(config.scopeGeography).trim() || entry.supportedGeography;
    }
    return {
      ok: true,
      catalogId: entry.catalogId,
      connector: entry,
      pollIntervalSec: entry.pollIntervalSec,
      minPollIntervalSec: minAllowed,
      rateLimitClamped: Boolean(entry.rateLimitClamped),
      maxRecordsPerSource: entry.maxRecordsPerSource,
      retentionDays: entry.retentionDays
    };
  }

  function runScheduledConnectorCheck(world, catalogId, options = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, status: 'NO_WORLD' };
    const nowIso = String(options.nowIso || new Date().toISOString());
    const nowMs = Date.parse(nowIso);

    if (net.allNetworkPaused) {
      return {
        ok: false,
        status: 'ALL_NETWORK_PAUSED',
        plainMessageTr: 'Tüm ağ ve arka plan takibi kullanıcı tarafından duraklatıldı.'
      };
    }

    const entry = findUniversalConnectorEntry(net, catalogId);
    if (!entry) return { ok: false, status: 'UNKNOWN_CONNECTOR' };
    if (!entry.enabled || !entry.userOptInGranted) {
      return {
        ok: false,
        status: 'CONNECTOR_NOT_ENABLED',
        plainMessageTr: 'Bu kaynak henüz kullanıcı tarafından etkinleştirilmedi.'
      };
    }

    if (!Array.isArray(entry.checkHistory)) entry.checkHistory = [];
    if (!Array.isArray(entry.errorLog)) entry.errorLog = [];

    // 1. Rate-limit guard
    const minIntervalSec = Math.max(5, Number(entry.minPollIntervalSec || 10));
    if (entry.lastCheckIso && !options.forceIgnoreRateLimit) {
      const elapsedSec = (nowMs - Date.parse(entry.lastCheckIso)) / 1000;
      if (Number.isFinite(elapsedSec) && elapsedSec >= 0 && elapsedSec < minIntervalSec) {
        entry.rateLimitSkipCount = Number(entry.rateLimitSkipCount || 0) + 1;
        return {
          ok: false,
          status: 'RATE_LIMIT_COOLDOWN',
          waitRemainingSec: Math.ceil(minIntervalSec - elapsedSec),
          plainMessageTr: `Kaynak hız sınırı korunuyor (${Math.ceil(minIntervalSec - elapsedSec)} sn sonra tekrar kontrol edilebilir).`
        };
      }
    }

    entry.lastCheckIso = nowIso;

    // 2. Simulated or real network disconnection / error handling
    if (options.simulateDisconnect || options.networkError) {
      const errMsg = String(options.networkError || 'Kaynak bağlantısı zaman aşımına uğradı veya ağ kesildi.');
      entry.connectionState = 'DISCONNECTED_SHOWING_LAST';
      entry.freshnessState = 'STALE_DISCONNECTED';
      if (!entry.disconnectedAtIso) entry.disconnectedAtIso = nowIso;
      entry.lastError = errMsg;
      entry.reconnectAttempts = Number(entry.reconnectAttempts || 0) + 1;
      entry.nextRetryDelaySec = Math.min(300, Math.pow(2, Math.min(6, entry.reconnectAttempts)) * 5);

      const lastDataAgeSeconds = entry.lastSuccessIso
        ? Math.max(0, Math.round((nowMs - Date.parse(entry.lastSuccessIso)) / 1000))
        : null;

      entry.errorLog.unshift({
        timestampIso: nowIso,
        error: errMsg,
        reconnectAttempts: entry.reconnectAttempts,
        nextRetryDelaySec: entry.nextRetryDelaySec
      });
      entry.errorLog = entry.errorLog.slice(0, 30);

      entry.checkHistory.unshift({
        timestampIso: nowIso,
        outcome: 'DISCONNECTED_ERROR',
        error: errMsg,
        lastDataAgeSeconds
      });
      entry.checkHistory = entry.checkHistory.slice(0, 50);

      return {
        ok: false,
        status: 'DISCONNECTED_SHOWING_LAST',
        lastDataAgeSeconds,
        reconnectAttempts: entry.reconnectAttempts,
        nextRetryDelaySec: entry.nextRetryDelaySec,
        plainMessageTr: 'Bağlantı kesildi. Son alınan bilgi gösteriliyor.'
      };
    }

    // 3. Payload parsing & deduplication
    const rawPayload = options.rawPayload !== undefined ? options.rawPayload : null;
    const payloadStr = typeof rawPayload === 'string' ? rawPayload : JSON.stringify(rawPayload || {});
    const payloadHash = `FNV32-${hex32(hash32(payloadStr))}`;

    if (entry.lastPayloadHash && entry.lastPayloadHash === payloadHash && !options.allowDuplicate) {
      entry.duplicateSkipCount = Number(entry.duplicateSkipCount || 0) + 1;
      entry.connectionState = 'CONNECTED_VERIFIED';
      entry.freshnessState = 'FRESH';
      entry.checkHistory.unshift({
        timestampIso: nowIso,
        outcome: 'DUPLICATE_SKIPPED',
        payloadHash
      });
      entry.checkHistory = entry.checkHistory.slice(0, 50);
      return {
        ok: true,
        status: 'DUPLICATE_SKIPPED',
        duplicateSkipped: true,
        notificationSuppressed: true,
        payloadHash,
        plainMessageTr: 'Kaynak kontrol edildi; veri değişmediği için tekrarlı kayıt ve bildirim oluşturulmadı.'
      };
    }

    // 4. Ingest new records into world if records are provided or parsed
    let parsedRecords = Array.isArray(options.records) ? options.records : [];
    if (parsedRecords.length === 0 && rawPayload) {
      if (entry.driverId === 'USGS_EARTHQUAKE_GEOJSON_API') {
        const p = parseUsgsEarthquakeGeoJsonPayload(rawPayload, { ingestedAtIso: nowIso, connectorId: entry.catalogId });
        if (p.valid) parsedRecords = p.records;
      } else if (entry.driverId === 'OPEN_METEO_GEOCODING_API') {
        const p = parseOpenMeteoGeocodingPayload(rawPayload, { ingestedAtIso: nowIso, connectorId: entry.catalogId });
        if (p.valid) parsedRecords = p.records;
      }
    }

    parsedRecords = parsedRecords.map(r => ({ ...r, connectorId: entry.catalogId }));

    let ingestSummary = null;
    if (parsedRecords.length > 0) {
      ingestSummary = ingestRealWorldRecordsToWorld(world, parsedRecords, getUniversalCategoryDefaultMappings(world), {
        ingestedAtIso: nowIso
      });
      if (!Array.isArray(world.realWorldRecords)) world.realWorldRecords = [];
      parsedRecords.forEach(pr => {
        if (!world.realWorldRecords.some(existing => existing.recordId === pr.recordId)) {
          world.realWorldRecords.unshift(pr);
        }
      });
    }

    // Enforce retention & storage quota per source
    if (Array.isArray(world.realWorldRecords)) {
      const maxRec = clamp(Number(entry.maxRecordsPerSource || 200), 10, 10000);
      const retentionMs = clamp(Number(entry.retentionDays || 90), 1, 3650) * 86400 * 1000;
      const kept = [];
      let sourceCount = 0;
      for (const r of world.realWorldRecords) {
        if (r.connectorId === entry.catalogId) {
          const recMs = Date.parse(r.ingestedAtIso || r.validTimeIso || nowIso);
          if (Number.isFinite(recMs) && (nowMs - recMs) > retentionMs) continue;
          if (sourceCount >= maxRec) continue;
          sourceCount++;
        }
        kept.push(r);
      }
      world.realWorldRecords = kept;
    }

    entry.lastPayloadHash = payloadHash;
    entry.lastSuccessIso = nowIso;
    entry.lastError = null;
    entry.disconnectedAtIso = null;
    entry.reconnectAttempts = 0;
    entry.nextRetryDelaySec = 0;
    entry.connectionState = 'CONNECTED_VERIFIED';
    entry.freshnessState = 'FRESH';
    entry.ingestedRecordCount = Number(entry.ingestedRecordCount || 0) + Math.max(1, parsedRecords.length);

    entry.checkHistory.unshift({
      timestampIso: nowIso,
      outcome: 'UPDATED_NEW_DATA',
      payloadHash,
      recordsAdded: parsedRecords.length
    });
    entry.checkHistory = entry.checkHistory.slice(0, 50);

    return {
      ok: true,
      status: 'UPDATED_NEW_DATA',
      duplicateSkipped: false,
      payloadHash,
      recordsAdded: parsedRecords.length,
      ingestSummary,
      plainMessageTr: 'Kaynak başarıyla kontrol edildi ve yeni bilgiler dünyayla ilişkilendirildi.'
    };
  }

  function reconnectTrackedSource(world, catalogId, options = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, status: 'NO_WORLD' };
    const entry = findUniversalConnectorEntry(net, catalogId);
    if (!entry) return { ok: false, status: 'UNKNOWN_CONNECTOR' };

    return runScheduledConnectorCheck(world, catalogId, {
      ...options,
      forceIgnoreRateLimit: true
    });
  }

  function backfillTrackedSourceGap(world, catalogId, gapSpec = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, status: 'NO_WORLD' };
    const entry = findUniversalConnectorEntry(net, catalogId);
    if (!entry) return { ok: false, status: 'UNKNOWN_CONNECTOR' };

    const startIso = String(gapSpec.gapStartIso || '');
    const endIso = String(gapSpec.gapEndIso || '');
    if (!entry.supportsHistoricalBackfill && entry.driverId !== 'USGS_EARTHQUAKE_GEOJSON_API') {
      return {
        ok: false,
        status: 'BACKFILL_NOT_SUPPORTED_BY_SOURCE',
        catalogId: entry.catalogId,
        gapStartIso: startIso,
        gapEndIso: endIso,
        plainMessageTr: 'Eksik dönem kaynak tarafından tamamlanamıyor (Bu kaynak yalnızca anlık durum sunar; geçmiş aralık uydurulmaz).'
      };
    }

    const backfillRecords = Array.isArray(gapSpec.records) ? gapSpec.records : [];
    const nowIso = String(gapSpec.nowIso || new Date().toISOString());
    if (backfillRecords.length > 0) {
      ingestRealWorldRecordsToWorld(world, backfillRecords, getUniversalCategoryDefaultMappings(world), {
        ingestedAtIso: nowIso
      });
    }
    entry.ingestedRecordCount = Number(entry.ingestedRecordCount || 0) + backfillRecords.length;
    return {
      ok: true,
      status: 'GAP_BACKFILLED',
      catalogId: entry.catalogId,
      gapStartIso: startIso,
      gapEndIso: endIso,
      backfilledCount: backfillRecords.length,
      plainMessageTr: `Kesinti dönemindeki (${startIso} – ${endIso}) eksik kayıtlar kaynağın tarihsel arşivinden tamamlandı.`
    };
  }

  function purgeTrackedSourceData(world, catalogId, options = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, status: 'NO_WORLD' };
    const entry = findUniversalConnectorEntry(net, catalogId);
    const beforeCount = Array.isArray(world.realWorldRecords) ? world.realWorldRecords.length : 0;
    if (Array.isArray(world.realWorldRecords)) {
      world.realWorldRecords = world.realWorldRecords.filter(r => r.connectorId !== catalogId);
    }
    const removedCount = beforeCount - (Array.isArray(world.realWorldRecords) ? world.realWorldRecords.length : 0);
    if (entry) {
      entry.ingestedRecordCount = 0;
      entry.lastPayloadHash = null;
      if (options.clearHistory) {
        entry.checkHistory = [];
        entry.errorLog = [];
      }
    }
    return {
      ok: true,
      catalogId,
      removedRecordCount: removedCount,
      plainMessageTr: `${removedCount} kayıt dünya deposundan temizlendi.`
    };
  }

  function pauseAllNetworkActivity(world, options = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, status: 'NO_WORLD' };
    const nowIso = String(options.nowIso || new Date().toISOString());
    net.allNetworkPaused = true;
    Object.values(net.activeConnectors).forEach(c => {
      if (c.enabled) {
        c.connectionState = 'PAUSED_BY_USER';
      }
    });
    (net.customConnectors || []).forEach(c => {
      if (c.enabled) {
        c.connectionState = 'PAUSED_BY_USER';
      }
    });
    net.connectionAuditLog.unshift({
      auditId: `AUD-PAUSEALL-${hex32(hash32(nowIso)).slice(0, 6)}`,
      timestampIso: nowIso,
      action: 'ALL_NETWORK_ACTIVITY_PAUSED',
      catalogId: 'ALL',
      providerName: 'CAELUS Evrensel Veri Ağı',
      endpointUrl: '-',
      note: 'Kullanıcı tüm ağ ve arka plan takibini durdurdu.'
    });
    return {
      ok: true,
      allNetworkPaused: true,
      plainMessageTr: 'Tüm dış veri bağlantıları ve arka plan kontrolleri durduruldu.'
    };
  }

  function resumeAllNetworkActivity(world, options = {}) {
    const net = ensureWorldUniversalDataNetwork(world);
    if (!net) return { ok: false, status: 'NO_WORLD' };
    const nowIso = String(options.nowIso || new Date().toISOString());
    net.allNetworkPaused = false;
    Object.values(net.activeConnectors).forEach(c => {
      if (c.enabled) {
        c.connectionState = 'ENABLED_READY';
      }
    });
    (net.customConnectors || []).forEach(c => {
      if (c.enabled) {
        c.connectionState = 'ENABLED_READY';
      }
    });
    net.connectionAuditLog.unshift({
      auditId: `AUD-RESUMEALL-${hex32(hash32(nowIso)).slice(0, 6)}`,
      timestampIso: nowIso,
      action: 'ALL_NETWORK_ACTIVITY_RESUMED',
      catalogId: 'ALL',
      providerName: 'CAELUS Evrensel Veri Ağı',
      endpointUrl: '-',
      note: 'Kullanıcı izinli veri kaynaklarının takibini yeniden başlattı.'
    });
    return {
      ok: true,
      allNetworkPaused: false,
      plainMessageTr: 'İzin verilen veri kaynaklarının düzenli takibi yeniden etkinleştirildi.'
    };
  }

  function getContinuousTrackingStatus(world, referenceNowIso) {
    const net = ensureWorldUniversalDataNetwork(world);
    const refMs = Date.parse(referenceNowIso || new Date().toISOString());
    const allSources = net
      ? [...Object.values(net.activeConnectors), ...(net.customConnectors || [])]
      : [];
    const enabledSources = allSources.filter(s => s.enabled);
    const disconnectedSources = enabledSources.filter(s => s.connectionState === 'DISCONNECTED_SHOWING_LAST');

    return {
      executionMode: 'LOCAL_PROCESS_MODE',
      tracksOnlyWhileAppRunning: true,
      simulatedBackgroundWhileClosed: false,
      allNetworkPaused: Boolean(net && net.allNetworkPaused),
      totalCatalogSources: allSources.length,
      enabledSourceCount: enabledSources.length,
      disconnectedSourceCount: disconnectedSources.length,
      serverArchitectureBlueprint: SERVER_24_7_ARCHITECTURE_BLUEPRINT,
      sources: allSources.map(s => {
        const lastSuccessMs = s.lastSuccessIso ? Date.parse(s.lastSuccessIso) : NaN;
        const dataAgeSeconds = Number.isFinite(lastSuccessMs) && Number.isFinite(refMs)
          ? Math.max(0, Math.round((refMs - lastSuccessMs) / 1000))
          : null;
        return {
          catalogId: s.catalogId,
          name: s.name,
          category: s.category,
          categoryLabelTr: s.categoryLabelTr,
          supportStatus: s.supportStatus || (s.implementationStatus === 'PLANNED_EXTENSIBLE' ? 'AWAITING_API_KEY_OR_AUTH' : 'CONNECTED_VERIFIED'),
          supportStatusBadgeTr: s.supportStatusBadgeTr || s.implementationBadgeTr,
          enabled: Boolean(s.enabled),
          connectionState: s.connectionState,
          pollIntervalSec: s.pollIntervalSec || 60,
          minPollIntervalSec: s.minPollIntervalSec || 10,
          supportsHistoricalBackfill: Boolean(s.supportsHistoricalBackfill),
          lastSuccessIso: s.lastSuccessIso,
          lastCheckIso: s.lastCheckIso,
          dataAgeSeconds,
          lastError: s.lastError,
          duplicateSkipCount: Number(s.duplicateSkipCount || 0),
          rateLimitSkipCount: Number(s.rateLimitSkipCount || 0),
          ingestedRecordCount: Number(s.ingestedRecordCount || 0),
          maxRecordsPerSource: Number(s.maxRecordsPerSource || 200),
          retentionDays: Number(s.retentionDays || 90)
        };
      })
    };
  }

  function extractWorld3DGlobeMarkers(world, options = {}) {
    const clusterRadiusDeg = Number.isFinite(Number(options.clusterRadiusDeg)) ? Number(options.clusterRadiusDeg) : 1.6;
    const rawGeoPoints = [];
    const nonGeoRecords = [];

    if (!world || typeof world !== 'object') {
      return { markers: [], clusters: [], nonGeoRecords: [], totalGeoPoints: 0 };
    }

    // 1. World entities with valid coordinates
    const entities = Array.isArray(world.entities) ? world.entities : [];
    entities.forEach(ent => {
      const lat = Number(ent.lat ?? ent.latitude ?? (ent.coordinates && ent.coordinates.lat));
      const lon = Number(ent.lon ?? ent.longitude ?? (ent.coordinates && ent.coordinates.lon));
      if (Number.isFinite(lat) && lat >= -90 && lat <= 90 && Number.isFinite(lon) && lon >= -180 && lon <= 180) {
        rawGeoPoints.push({
          pointId: `ENT-${ent.id}`,
          kind: 'WORLD_ENTITY',
          category: 'WORLD_ENTITY',
          label: String(ent.label || ent.id),
          shortLabel: String(ent.label || ent.id).slice(0, 24),
          lat: Number(lat.toFixed(4)),
          lon: Number(lon.toFixed(4)),
          valueSummary: `%${Math.round(Number(ent.statePct ?? 0))} Yük`,
          statePct: Math.round(Number(ent.statePct ?? 0)),
          dataKindBadge: ent.sourceType || 'DÜNYA VARLIĞI',
          entityId: ent.id
        });
      } else {
        nonGeoRecords.push({
          itemId: ent.id,
          kind: 'NON_GEO_ENTITY',
          label: String(ent.label || ent.id),
          reason: 'Varlık için doğrulanmış coğrafi enlem/boylam tanımlı değil; 3B Küre üzerine rastgele yerleştirilmez.'
        });
      }
    });

    // 2. Ingested real-world records
    const records = Array.isArray(world.realWorldRecords) ? world.realWorldRecords : [];
    const seenCoordVar = new Set();
    records.forEach(rec => {
      const loc = rec.gridCellLocation || rec.requestedLocation || null;
      const lat = loc ? Number(loc.lat) : NaN;
      const lon = loc ? Number(loc.lon) : NaN;
      if (rec.hasCoordinates !== false && Number.isFinite(lat) && lat >= -90 && lat <= 90 && Number.isFinite(lon) && lon >= -180 && lon <= 180) {
        const dedupKey = `${rec.category || 'DATA'}-${lat.toFixed(2)}-${lon.toFixed(2)}-${rec.variableName}`;
        if (seenCoordVar.has(dedupKey)) return;
        seenCoordVar.add(dedupKey);
        rawGeoPoints.push({
          pointId: rec.recordId || dedupKey,
          kind: 'REAL_WORLD_RECORD',
          category: rec.category || 'WEATHER_MARINE',
          label: `${rec.variableLabelTr || rec.variableName}: ${rec.normalizedValue} ${rec.normalizedUnit}`,
          shortLabel: `${rec.variableLabelTr || rec.variableName} (${rec.normalizedValue}${rec.normalizedUnit})`,
          locationLabel: (rec.requestedLocation && rec.requestedLocation.label) || `${lat.toFixed(2)}°K, ${lon.toFixed(2)}°D`,
          lat: Number(lat.toFixed(4)),
          lon: Number(lon.toFixed(4)),
          valueSummary: `${rec.normalizedValue} ${rec.normalizedUnit}`,
          validTimeIso: rec.validTimeIso,
          sourceName: rec.sourceName,
          dataKindBadge: rec.dataKindBadge || rec.dataKind,
          freshnessStatus: rec.freshnessStatus
        });
      } else {
        nonGeoRecords.push({
          itemId: rec.recordId || rec.variableName,
          kind: 'NON_GEO_RECORD',
          category: rec.category || 'ECONOMY_MACRO',
          label: `${rec.variableLabelTr || rec.variableName}: ${rec.normalizedValue} ${rec.normalizedUnit}`,
          sourceName: rec.sourceName,
          reason: rec.nonGeoScopeLabel || 'Ülke/küresel düzeyde konumsuz veri; 3B Küre üzerine rastgele yerleştirilmez.'
        });
      }
    });

    // 3. Spatial angular proximity clustering so dense markers never collide
    const clusters = [];
    rawGeoPoints.forEach(pt => {
      let matchedCluster = null;
      if (clusterRadiusDeg > 0) {
        for (let i = 0; i < clusters.length; i++) {
          const c = clusters[i];
          const dLat = Math.abs(c.lat - pt.lat);
          const dLon = Math.abs(c.lon - pt.lon);
          if (Math.hypot(dLat, dLon) <= clusterRadiusDeg) {
            matchedCluster = c;
            break;
          }
        }
      }
      if (matchedCluster) {
        matchedCluster.members.push(pt);
        matchedCluster.memberCount = matchedCluster.members.length;
        matchedCluster.isCluster = matchedCluster.memberCount > 1;
        // Recompute centroid
        const sumLat = matchedCluster.members.reduce((s, m) => s + m.lat, 0);
        const sumLon = matchedCluster.members.reduce((s, m) => s + m.lon, 0);
        matchedCluster.lat = Number((sumLat / matchedCluster.memberCount).toFixed(4));
        matchedCluster.lon = Number((sumLon / matchedCluster.memberCount).toFixed(4));
        matchedCluster.label = `${matchedCluster.members[0].locationLabel || matchedCluster.members[0].shortLabel} (+${matchedCluster.memberCount - 1} kayıt)`;
      } else {
        clusters.push({
          clusterId: `CLUST-${clusters.length + 1}`,
          isCluster: false,
          memberCount: 1,
          lat: pt.lat,
          lon: pt.lon,
          category: pt.category,
          label: pt.shortLabel,
          locationLabel: pt.locationLabel || pt.label,
          primaryMember: pt,
          members: [pt]
        });
      }
    });

    return {
      markers: clusters,
      clusters,
      rawGeoPoints,
      nonGeoRecords,
      totalGeoPoints: rawGeoPoints.length
    };
  }

  /* ═════════════════════════════════════════════════════════════════════════
     CAELUS — GERÇEK OLAYLA UÇTAN UCA DOĞRULAMA (REAL HISTORICAL INCIDENT VERIFICATION)
     - 1. Gerçek Olay Çalışma Alanı (createIncidentInvestigationWorkspace, attachUserRecordsToIncident)
     - 2. Gerçek Veriyi İlişkilendir & Gelecek Bilgisi Sızıntı Koruması (parseOpenMeteoHistoricalEra5Payload,
          evaluateIncidentLookAheadGate, associateConnectorDataToIncident)
     - 3. Senaryo (Dal A / Dal B) ve Gerçekleşen Sonuç — 5 Epistemik Kategori Ayrımı
          (runIncidentInvestigationEndToEnd)
     - 4. Kullanıcıya Sunulan Olay İnceleme Raporu (generateIncidentInvestigationReport,
          formatIncidentInvestigationReportMarkdown, formatIncidentInvestigationReportHtml)
     ═════════════════════════════════════════════════════════════════════════ */

