  function registerComputationEngine(engineSpec) {
    if (!engineSpec || !engineSpec.engineId) {
      throw new Error('Hesaplama motoru kaydı için geçerli bir engineId gereklidir.');
    }
    const id = String(engineSpec.engineId).trim().toUpperCase();
    COMPUTATION_ENGINE_REGISTRY[id] = {
      engineId: id,
      name: String(engineSpec.name || id),
      version: String(engineSpec.version || '1.0.0'),
      domain: String(engineSpec.domain || 'CUSTOM_DOMAIN'),
      supportedScales: Array.isArray(engineSpec.supportedScales) ? engineSpec.supportedScales : ['HUMAN_SYSTEMS'],
      supportedInputs: Array.isArray(engineSpec.supportedInputs) ? engineSpec.supportedInputs : [],
      units: String(engineSpec.units || 'Belirtilmedi'),
      validTimeHorizon: String(engineSpec.validTimeHorizon || 'Belirtilmedi'),
      epistemicOutputType: String(engineSpec.epistemicOutputType || 'MODEL_OUTPUT'),
      limitations: String(engineSpec.limitations || 'Kapsam ve sınırlamalar kullanıcı tarafından doğrulanmalıdır.'),
      crossEngineConversionRules: String(engineSpec.crossEngineConversionRules || 'Açık birim dönüşümü ve varsayım beyanı zorunludur.')
    };
    return COMPUTATION_ENGINE_REGISTRY[id];
  }

  function listComputationEngines() {
    return Object.values(COMPUTATION_ENGINE_REGISTRY).map(e => ({ ...e }));
  }

