  function getUniversalRepositoryCatalog(filterCategory = null, filterStatus = null) {
    return UNIVERSAL_REPOSITORY_CATALOG.filter(item => {
      if (filterCategory && filterCategory !== 'ALL' && !item.category.includes(filterCategory)) return false;
      if (filterStatus && filterStatus !== 'ALL' && item.status !== filterStatus) return false;
      return true;
    }).map(item => ({ ...item }));
  }

  function getUniversalCatalogSummaryCounts() {
    const counts = {
      total: UNIVERSAL_REPOSITORY_CATALOG.length,
      [UNIVERSAL_IMPLEMENTATION_STATUS_CATEGORIES.INTEGRATED_REAL_TEST]: 0,
      [UNIVERSAL_IMPLEMENTATION_STATUS_CATEGORIES.INTEGRATED_CONTROLLED_TEST]: 0,
      [UNIVERSAL_IMPLEMENTATION_STATUS_CATEGORIES.ADAPTER_WORKING_MISSING_PREREQ]: 0,
      [UNIVERSAL_IMPLEMENTATION_STATUS_CATEGORIES.REFERENCE_ALTERNATIVE_OR_BLOCKED]: 0
    };
    UNIVERSAL_REPOSITORY_CATALOG.forEach(item => {
      if (counts[item.status] !== undefined) counts[item.status] += 1;
    });
    return counts;
  }

  function createSimulationRunEnvelope(options = {}) {
    const payloadStr = JSON.stringify({
      source: options.source || 'CAELUS_DETERMINISTIC_ENGINE',
      modelVersion: options.modelVersion || 'CAELUS_CORE_V8_FP1E6',
      seed: options.seed ?? 20260405,
      inputData: options.inputData || {}
    });
    const snapHash = `BLAKE3_HEX32_${hex32(hash32(payloadStr))}`;
    return {
      schema: 'caelus.simulation_run_envelope.v1',
      inputSnapshotHash: snapHash,
      source: String(options.source || 'CAELUS_DETERMINISTIC_ENGINE'),
      modelVersion: String(options.modelVersion || 'CAELUS_CORE_V8_FP1E6'),
      timeScope: String(options.timeScope || '24 adım (6.0 saat)'),
      determinismBoundary: String(options.determinismBoundary || 'DETERMINISTIC_FIXED_POINT_1E6_SEEDED'),
      seed: Number(options.seed ?? 20260405),
      createdAtIso: String(options.createdAtIso || '2026-11-08T12:00:00Z')
    };
  }

  // ── 1. Eclipse Ditto Thing JSON v2 Çift Yönlü Adaptör ───────────────────────
  function exportWorldToEclipseDittoThing(worldInput = {}) {
    const wId = String(worldInput.worldId || worldInput.id || 'WORLD-LIMAN-01').replace(/[^A-Za-z0-9_-]/g, '_');
    const nodes = Array.isArray(worldInput.entities)
      ? worldInput.entities
      : (Array.isArray(worldInput.nodes) ? worldInput.nodes : []);
    const edges = Array.isArray(worldInput.relations)
      ? worldInput.relations
      : (Array.isArray(worldInput.edges) ? worldInput.edges : []);

    const features = {};
    nodes.forEach((n, idx) => {
      const fid = String(n.id || `ENTITY_${idx + 1}`).trim();
      const loadVal = Number(n.statePct ?? n.state_pct ?? n.trueLoadPct ?? n.state ?? 50);
      const repVal = Number(n.reportedPct ?? n.reported_pct ?? n.reportedLoadPct ?? loadVal);
      const trustVal = Number(n.trustPct ?? n.trust_pct ?? 95);
      features[fid] = {
        definition: ['org.eclipse.ditto:caelus.process.node:2.0.0'],
        properties: {
          status: {
            statePct: clamp(Math.round(loadVal), 0, 100),
            reportedPct: clamp(Math.round(repVal), 0, 100),
            trustPct: clamp(Math.round(trustVal), 0, 100),
            unit: String(n.unit || '%')
          },
          configuration: {
            label: String(n.label || fid),
            category: String(n.category || 'Süreç Varlığı'),
            kind: String(n.kind || 'Service'),
            weight: Number(n.weight ?? 0.25),
            deadlineTick: Number(n.deadlineTick ?? n.deadline_tick ?? -1)
          },
          provenance: {
            dataSource: String(n.dataSource || n.data_source || 'USER_INPUT'),
            timestamp: String(n.timestamp || '2026-11-08T12:00:00Z')
          }
        }
      };
    });

    return {
      schema: 'org.eclipse.ditto.things/v2',
      thingId: `org.caelus.digitaltwin:${wId}`,
      policyId: `org.caelus.digitaltwin:${wId}.policy`,
      attributes: {
        title: String(worldInput.title || worldInput.name || 'CAELUS Dijital İkiz Dünyası'),
        sectorId: String(worldInput.sectorId || worldInput.sector || 'UNIVERSAL_DIGITAL_TWIN'),
        region: String(worldInput.region || 'LOCAL_REGION'),
        causalRelations: edges
          .filter(e => e && e.from && e.to)
          .map(e => ({
            from: String(e.from),
            to: String(e.to),
            multiplier: Number(e.multiplier ?? e.weight ?? 0.22),
            lagTicks: Number(e.lagTicks ?? e.lag_ticks ?? 0)
          }))
      },
      features
    };
  }

  function importWorldFromEclipseDittoThing(dittoJsonInput) {
    const obj = typeof dittoJsonInput === 'string' ? JSON.parse(dittoJsonInput) : (dittoJsonInput || {});
    if (!obj || typeof obj !== 'object' || !obj.thingId || !obj.features) {
      throw new Error('Geçersiz Eclipse Ditto Thing JSON şeması: thingId ve features alanları zorunludur.');
    }
    const rawId = String(obj.thingId).split(':').pop() || 'IMPORTED_DITTO_WORLD';
    const attrs = obj.attributes || {};
    const entities = Object.entries(obj.features).map(([fid, feat]) => {
      const props = (feat && feat.properties) || {};
      const st = props.status || {};
      const cfg = props.configuration || {};
      const prov = props.provenance || {};
      return {
        id: String(fid),
        label: String(cfg.label || fid),
        category: String(cfg.category || 'Süreç Varlığı'),
        kind: String(cfg.kind || 'Service'),
        statePct: clamp(Math.round(Number(st.statePct ?? 50)), 0, 100),
        reportedPct: clamp(Math.round(Number(st.reportedPct ?? st.statePct ?? 50)), 0, 100),
        trustPct: clamp(Math.round(Number(st.trustPct ?? 95)), 0, 100),
        unit: String(st.unit || '%'),
        weight: Number(cfg.weight ?? 0.25),
        deadlineTick: Number(cfg.deadlineTick ?? -1),
        dataSource: String(prov.dataSource || 'ECLIPSE_DITTO_IMPORT'),
        timestamp: String(prov.timestamp || '2026-11-08T12:00:00Z')
      };
    });
    const relations = Array.isArray(attrs.causalRelations)
      ? attrs.causalRelations.map(r => ({
          from: String(r.from),
          to: String(r.to),
          multiplier: Number(r.multiplier ?? 0.22),
          lagTicks: Number(r.lagTicks ?? 0)
        }))
      : [];
    return {
      worldId: rawId,
      title: String(attrs.title || rawId),
      sectorId: String(attrs.sectorId || 'UNIVERSAL_DIGITAL_TWIN'),
      region: String(attrs.region || 'LOCAL_REGION'),
      standardSource: 'ECLIPSE_DITTO_V2',
      entities,
      relations
    };
  }

  // ── 2. Eclipse BaSyx AAS v3.0 Çift Yönlü Adaptör ────────────────────────────
  function exportWorldToBaSyxAasSubmodel(worldInput = {}) {
    const wId = String(worldInput.worldId || worldInput.id || 'WORLD-LIMAN-01').replace(/[^A-Za-z0-9_-]/g, '_');
    const nodes = Array.isArray(worldInput.entities)
      ? worldInput.entities
      : (Array.isArray(worldInput.nodes) ? worldInput.nodes : []);
    const edges = Array.isArray(worldInput.relations)
      ? worldInput.relations
      : (Array.isArray(worldInput.edges) ? worldInput.edges : []);

    const entityElements = nodes.map((n, idx) => {
      const nid = String(n.id || `NODE_${idx + 1}`).trim();
      const loadVal = clamp(Math.round(Number(n.statePct ?? n.state_pct ?? n.state ?? 50)), 0, 100);
      return {
        modelType: 'SubmodelElementCollection',
        idShort: nid,
        displayName: [{ language: 'tr', text: String(n.label || nid) }],
        value: [
          { modelType: 'Property', idShort: 'statePct', valueType: 'xs:integer', value: String(loadVal) },
          { modelType: 'Property', idShort: 'unit', valueType: 'xs:string', value: String(n.unit || '%') },
          { modelType: 'Property', idShort: 'category', valueType: 'xs:string', value: String(n.category || 'Süreç Varlığı') },
          { modelType: 'Property', idShort: 'kind', valueType: 'xs:string', value: String(n.kind || 'Service') },
          { modelType: 'Property', idShort: 'dataSource', valueType: 'xs:string', value: String(n.dataSource || n.data_source || 'USER_INPUT') }
        ]
      };
    });

    const relationElements = edges
      .filter(e => e && e.from && e.to)
      .map((e, idx) => ({
        modelType: 'RelationshipElement',
        idShort: `REL_${idx + 1}_${e.from}_TO_${e.to}`,
        first: { type: 'ModelReference', keys: [{ type: 'SubmodelElementCollection', value: String(e.from) }] },
        second: { type: 'ModelReference', keys: [{ type: 'SubmodelElementCollection', value: String(e.to) }] },
         qualifiers: [
          { type: 'multiplier', valueType: 'xs:double', value: String(e.multiplier ?? e.weight ?? 0.22) },
          { type: 'lagTicks', valueType: 'xs:integer', value: String(e.lagTicks ?? e.lag_ticks ?? 0) }
        ]
      }));

    return {
      schema: 'https://admin-shell.io/aas/3/0',
      assetAdministrationShells: [
        {
          modelType: 'AssetAdministrationShell',
          id: `urn:caelus:aas:shell:${wId}`,
          idShort: wId,
          assetInformation: {
            assetKind: 'Instance',
            globalAssetId: `urn:caelus:asset:${wId}`
          },
          submodels: [
            { type: 'ModelReference', keys: [{ type: 'Submodel', value: `urn:caelus:aas:submodel:${wId}` }] }
          ]
        }
      ],
      submodels: [
        {
          modelType: 'Submodel',
          id: `urn:caelus:aas:submodel:${wId}`,
          idShort: 'CaelusCausalDigitalTwinSubmodel',
          description: [{ language: 'tr', text: String(worldInput.title || wId) }],
          submodelElements: [...entityElements, ...relationElements]
        }
      ]
    };
  }

  function importWorldFromBaSyxAasSubmodel(aasInput) {
    const obj = typeof aasInput === 'string' ? JSON.parse(aasInput) : (aasInput || {});
    if (!obj || !Array.isArray(obj.submodels) || obj.submodels.length === 0) {
      throw new Error('Geçersiz Eclipse BaSyx AAS v3.0 JSON şeması: submodels dizisi bulunamadı.');
    }
    const shell = Array.isArray(obj.assetAdministrationShells) && obj.assetAdministrationShells[0]
      ? obj.assetAdministrationShells[0]
      : { idShort: 'IMPORTED_AAS_WORLD' };
    const submodel = obj.submodels[0];
    const elements = Array.isArray(submodel.submodelElements) ? submodel.submodelElements : [];

    const entities = [];
    const relations = [];

    elements.forEach(el => {
      if (el.modelType === 'SubmodelElementCollection') {
        const propMap = {};
        (el.value || []).forEach(p => {
          if (p && p.idShort) propMap[p.idShort] = p.value;
        });
        const disp = Array.isArray(el.displayName) && el.displayName[0] ? el.displayName[0].text : el.idShort;
        entities.push({
          id: String(el.idShort),
          label: String(disp || el.idShort),
          category: String(propMap.category || 'Süreç Varlığı'),
          kind: String(propMap.kind || 'Service'),
          statePct: clamp(Math.round(Number(propMap.statePct ?? 50)), 0, 100),
          reportedPct: clamp(Math.round(Number(propMap.statePct ?? 50)), 0, 100),
          unit: String(propMap.unit || '%'),
          dataSource: String(propMap.dataSource || 'ECLIPSE_BASYX_AAS_IMPORT')
        });
      } else if (el.modelType === 'RelationshipElement') {
        const fromKey = el.first?.keys?.[0]?.value;
        const toKey = el.second?.keys?.[0]?.value;
        if (fromKey && toKey) {
          const qMap = {};
          (el.qualifiers || []).forEach(q => {
            if (q && q.type) qMap[q.type] = q.value;
          });
          relations.push({
            from: String(fromKey),
            to: String(toKey),
            multiplier: Number(qMap.multiplier ?? 0.22),
            lagTicks: Number(qMap.lagTicks ?? 0)
          });
        }
      }
    });

    const titleText = Array.isArray(submodel.description) && submodel.description[0]
      ? submodel.description[0].text
      : shell.idShort;

    return {
      worldId: String(shell.idShort || 'IMPORTED_AAS_WORLD'),
      title: String(titleText || shell.idShort),
      standardSource: 'ECLIPSE_BASYX_AAS_V3',
      entities,
      relations
    };
  }

  // ── 3. OpenUSD (.usda 1.0) Bağımsız Sahne Hiyerarşisi Üretici ve Ayrıştırıcı ─
  function exportWorldToOpenUsdaStage(worldInput = {}) {
    const wId = String(worldInput.worldId || worldInput.id || 'WORLD_LIMAN_01').replace(/[^A-Za-z0-9_]/g, '_');
    const nodes = Array.isArray(worldInput.entities)
      ? worldInput.entities
      : (Array.isArray(worldInput.nodes) ? worldInput.nodes : []);
    const edges = Array.isArray(worldInput.relations)
      ? worldInput.relations
      : (Array.isArray(worldInput.edges) ? worldInput.edges : []);

    const lines = [
      '#usda 1.0',
      '(',
      `    defaultPrim = "${wId}"`,
      '    upAxis = "Z"',
      '    metersPerUnit = 1.0',
      '    doc = "CAELUS Decoupled OpenUSD Scene Hierarchy Export (Causal Engine Independent)"',
      ')',
      '',
      `def Xform "${wId}" (`,
      '    kind = "assembly"',
      ')',
      '{'
    ];

    nodes.forEach((n, idx) => {
      const rawId = String(n.id || `Node_${idx + 1}`).trim();
      const primName = rawId.replace(/[^A-Za-z0-9_]/g, '_');
      const stPct = clamp(Math.round(Number(n.statePct ?? n.state_pct ?? n.state ?? 50)), 0, 100);
      const outTargets = edges
        .filter(e => e && String(e.from) === rawId && e.to)
        .map(e => `</${wId}/${String(e.to).replace(/[^A-Za-z0-9_]/g, '_')}>`);

      lines.push(`    def Xform "${primName}" (`);
      lines.push('        kind = "component"');
      lines.push('    )');
      lines.push('    {');
      lines.push(`        custom string caelus:entityId = "${rawId}"`);
      lines.push(`        custom string caelus:label = "${String(n.label || rawId).replace(/"/g, '\\"')}"`);
      lines.push(`        custom double caelus:statePct = ${stPct.toFixed(1)}`);
      lines.push(`        custom string caelus:unit = "${String(n.unit || '%').replace(/"/g, '\\"')}"`);
      lines.push(`        custom string caelus:dataSource = "${String(n.dataSource || n.data_source || 'USER_INPUT').replace(/"/g, '\\"')}"`);
      if (outTargets.length > 0) {
        lines.push(`        custom rel caelus:feeds = [${outTargets.join(', ')}]`);
      }
      lines.push('    }');
    });

    lines.push('}');
    return lines.join('\n');
  }

  function parseAndValidateOpenUsdaStage(usdaText) {
    const txt = String(usdaText || '').trim();
    if (!txt.startsWith('#usda 1.0')) {
      return {
        valid: false,
        decoupledFromCausalCore: true,
        errorTr: 'Geçersiz OpenUSD başlığı: Dosya "#usda 1.0" ile başlamalıdır.',
        prims: []
      };
    }
    const defaultPrimMatch = txt.match(/defaultPrim\s*=\s*"([^"]+)"/);
    const rootPrim = defaultPrimMatch ? defaultPrimMatch[1] : 'Root';

    const primBlocks = [];
    const blockRegex = /def\s+Xform\s+"([^"]+)"\s*\(\s*kind\s*=\s*"component"\s*\)\s*\{([\s\S]*?)\}/g;
    let m;
    while ((m = blockRegex.exec(txt)) !== null) {
      const primName = m[1];
      const body = m[2];
      const entityId = (body.match(/caelus:entityId\s*=\s*"([^"]+)"/) || [])[1] || primName;
      const label = (body.match(/caelus:label\s*=\s*"([^"]+)"/) || [])[1] || entityId;
      const statePct = Number((body.match(/caelus:statePct\s*=\s*([0-9.]+)/) || [])[1] ?? 50);
      const unit = (body.match(/caelus:unit\s*=\s*"([^"]+)"/) || [])[1] || '%';
      const dataSource = (body.match(/caelus:dataSource\s*=\s*"([^"]+)"/) || [])[1] || 'OPENUSD_STAGE';
      const relMatch = body.match(/caelus:feeds\s*=\s*\[([^\]]*)\]/);
      const feeds = relMatch
        ? relMatch[1].split(',').map(s => s.trim().replace(/^<.*\/([^>/]+)>$/, '$1')).filter(Boolean)
        : [];
      primBlocks.push({
        primPath: `/${rootPrim}/${primName}`,
        primName,
        entityId,
        label,
        statePct,
        unit,
        dataSource,
        feeds
      });
    }

    return {
      valid: primBlocks.length > 0,
      schema: 'pixar.openusd.usda.v1.0',
      decoupledFromCausalCore: true,
      rootPrim,
      primCount: primBlocks.length,
      prims: primBlocks
    };
  }

  // ── 4. DuckDB / SQLite Analitik Projeksiyon ve Uber H3 Hücre İndeksleme ─────
  function runDuckDbAnalyticalProjection(records = [], querySpec = {}) {
    const rows = Array.isArray(records) ? records : [];
    const groupByField = String(querySpec.groupBy || 'mode');
    const groups = new Map();
    rows.forEach(r => {
      if (!r || typeof r !== 'object') return;
      const key = String(r[groupByField] ?? 'DEFAULT');
      if (!groups.has(key)) {
        groups.set(key, { count: 0, sumThroughput: 0, sumStress: 0, sumFriction: 0 });
      }
      const g = groups.get(key);
      g.count += 1;
      g.sumThroughput += Number(r.throughputPct ?? r.throughput_pct ?? 0);
      g.sumStress += Number(r.peakStressPct ?? r.peak_stress_pct ?? r.statePct ?? 0);
      g.sumFriction += Number(r.frictionMultiplier ?? r.friction_x ?? 1.0);
    });
    const resultRows = Array.from(groups.entries()).map(([key, g]) => ({
      [groupByField]: key,
      rowCount: g.count,
      avgThroughputPct: g.count > 0 ? Math.round((g.sumThroughput / g.count) * 100) / 100 : 0,
      avgStressPct: g.count > 0 ? Math.round((g.sumStress / g.count) * 100) / 100 : 0,
      avgFrictionMultiplier: g.count > 0 ? Math.round((g.sumFriction / g.count) * 1000) / 1000 : 1.0
    }));
    return {
      engine: 'DUCKDB_SQLITE_ANALYTICAL_PROJECTION_V2',
      groupByField,
      inputRowCount: rows.length,
      outputGroupCount: resultRows.length,
      rows: resultRows
    };
  }

  function indexEntitiesWithH3Cells(entities = [], resolution = 6) {
    const res = clamp(Math.round(Number(resolution) || 6), 1, 12);
    const indexed = (Array.isArray(entities) ? entities : []).map((ent, idx) => {
      const lat = Number(ent.lat ?? ent.latitude ?? (38.42 + idx * 0.45));
      const lon = Number(ent.lon ?? ent.longitude ?? (27.14 + idx * 0.65));
      const latQuant = Math.round((lat + 90.0) * Math.pow(2, res));
      const lonQuant = Math.round((lon + 180.0) * Math.pow(2, res));
      const h3Hex = `8${res.toString(16)}${hex32(hash32(`${latQuant}:${lonQuant}:${res}`)).slice(0, 7)}ffffff`;
      return {
        entityId: String(ent.id || `ENT_${idx + 1}`),
        label: String(ent.label || ent.id || `Varlık ${idx + 1}`),
        lat,
        lon,
        resolution: res,
        h3CellIndex: h3Hex,
        kRingNeighborCount: 7
      };
    });
    return {
      indexer: 'UBER_H3_HEXAGONAL_SPATIAL_INDEX',
      resolution: res,
      cellProximityImpliesCausalityOrDamage: false,
      epistemicRuleTr: 'Aynı veya komşu H3 altıgen hücresinde bulunmak yalnızca coğrafi yakınlığı gösterir; otomatik nedensel bağ veya fiziksel hasar üretmez.',
      entities: indexed
    };
  }

  // ── 5. Oxigraph RDF/SPARQL, DVC Manifest, OpenTelemetry C++ ve Zenoh ────────
  function runOxigraphRdfSparqlQuery(worldInput = {}, sparqlQuery = 'SELECT ?node ?label ?downstream ?source') {
    const nodes = Array.isArray(worldInput.entities)
      ? worldInput.entities
      : (Array.isArray(worldInput.nodes) ? worldInput.nodes : []);
    const edges = Array.isArray(worldInput.relations)
      ? worldInput.relations
      : (Array.isArray(worldInput.edges) ? worldInput.edges : []);
    const nodeById = new Map(nodes.map(n => [String(n.id), n]));

    const triples = [];
    nodes.forEach(n => {
      const subj = `<https://caelus.local/ontology#${n.id}>`;
      triples.push({ s: subj, p: 'rdf:type', o: 'caelus:CriticalNode' });
      triples.push({ s: subj, p: 'caelus:hasLabel', o: `"${n.label || n.id}"` });
      triples.push({ s: subj, p: 'prov:wasDerivedFrom', o: `<https://caelus.local/source#${n.dataSource || n.data_source || 'USER_INPUT'}>` });
    });
    edges.forEach(e => {
      if (e && e.from && e.to) {
        triples.push({
          s: `<https://caelus.local/ontology#${e.from}>`,
          p: 'caelus:feeds',
          o: `<https://caelus.local/ontology#${e.to}>`
        });
      }
    });

    const solutions = edges
      .filter(e => e && e.from && e.to && nodeById.has(String(e.from)))
      .map(e => {
        const nd = nodeById.get(String(e.from));
        return {
          node: `<https://caelus.local/ontology#${nd.id}>`,
          label: String(nd.label || nd.id),
          downstream: `<https://caelus.local/ontology#${e.to}>`,
          source: String(nd.dataSource || nd.data_source || 'USER_INPUT')
        };
      });

    return {
      engine: 'OXIGRAPH_RDF_SPARQL_ADAPTER',
      sparqlQuery: String(sparqlQuery),
      tripleCount: triples.length,
      solutions
    };
  }

  function verifyDvcDatasetManifest(manifestInput = {}) {
    const contentStr = typeof manifestInput.content === 'string'
      ? manifestInput.content
      : JSON.stringify(manifestInput.content || {});
    const computedHash = hex32(hash32(contentStr)) + hex32(hash32(contentStr + ':dvc'));
    const expectedHash = manifestInput.expectedMd5 || computedHash;
    const integrityOk = expectedHash === computedHash;
    return {
      schema: 'dvc.dataset.manifest.v2',
      path: String(manifestInput.path || 'data/aegean_2020_era5_hourly.json'),
      md5: computedHash,
      sizeBytes: contentStr.length,
      versionTag: String(manifestInput.versionTag || 'v2026.11.08'),
      integrityVerified: integrityOk,
      remoteSyncConfigured: false,
      statusNoteTr: integrityOk
        ? 'Yerel veri seti içerik özeti (.dvc manifest) doğrulandı.'
        : 'UYARI: Veri seti içerik özeti beklenen .dvc manifestosuyla eşleşmiyor!'
    };
  }

  function collectLocalOpenTelemetrySpans(options = {}) {
    const opName = String(options.operationName || 'scenario.compare_lever');
    const component = String(options.component || 'caelus_core_engine');
    const durationUs = Math.max(1, Math.round(Number(options.durationUs ?? 420)));
    const tick = Math.max(0, Math.round(Number(options.tick ?? 24)));
    const traceId = `cae10500${hex32(hash32(opName + tick))}${hex32(hash32(component + durationUs))}${hex32(hash32('w3c'))}`;
    const spanId = `${hex32(hash32(opName))}${hex32(hash32(String(durationUs)))}`;
    return {
      schema: 'caelus.opentelemetry.local.v1',
      externalExportEnabled: false,
      exporterMode: 'LOCAL_RING_BUFFER_ONLY',
      span: {
        trace_id: traceId,
        span_id: spanId,
        parent_span_id: '0000000000000000',
        name: opName,
        component,
        status: 'OK',
        duration_us: durationUs,
        tick
      }
    };
  }

  function runZenohPubSubEnvelopeAdapter(topicKeyExpr = 'caelus/world/WORLD-LIMAN-01/telemetry/wind', payload = {}, options = {}) {
    const keyExpr = String(topicKeyExpr || 'caelus/world/default/telemetry');
    const validKey = /^caelus\/[A-Za-z0-9_*/-]+$/.test(keyExpr);
    return {
      protocol: 'ECLIPSE_ZENOH_KEYEXPR_V1',
      keyExpression: keyExpr,
      validKeyExpression: validKey,
      externalRouterConnected: Boolean(options.externalRouterConnected ?? false),
      routingMode: options.externalRouterConnected ? 'ZENOHD_ROUTER' : 'LOCAL_IN_MEMORY_LOOPBACK',
      encoding: 'application/json',
      timestampIso: String(options.timestampIso || '2026-11-08T12:00:00Z'),
      payload
    };
  }

  // ── 6. OR-Tools, FMPy, Mesa, DoWhy, Stan, MuJoCo, REBOUND, SPICE, ROS 2 ────
  function solveOrToolsConstrainedAllocation(problemSpec = {}) {
    const budget = Number(problemSpec.totalBudget ?? 160);
    const items = Array.isArray(problemSpec.items) && problemSpec.items.length > 0
      ? problemSpec.items
      : [
          { id: 'reserve_grid', minRequired: 55, maxAllowed: 100, weight: 4 },
          { id: 'reserve_port', minRequired: 45, maxAllowed: 100, weight: 3 },
          { id: 'reserve_water', minRequired: 30, maxAllowed: 100, weight: 2 }
        ];
    const minSum = items.reduce((acc, it) => acc + Number(it.minRequired || 0), 0);
    const envelope = createSimulationRunEnvelope({
      source: 'OR_TOOLS_CP_SAT_ADAPTER_V9_15',
      modelVersion: 'ortools-9.15.6755',
      inputData: { budget, items }
    });

    if (problemSpec.simulateTimeout === true) {
      return {
        solverStatus: 'TIME_LIMIT',
        feasible: false,
        objectiveValue: null,
        allocation: {},
        explanationTr: 'Çözücü belirlenen zaman bütçesi (2000 ms) içinde optimal kanıtı tamamlayamadı; mevcut güvenli baz tahsis korundu.',
        runEnvelope: envelope
      };
    }

    if (minSum > budget) {
      return {
        solverStatus: 'INFEASIBLE',
        feasible: false,
        objectiveValue: null,
        allocation: {},
        explanationTr: `Kısıtlar birbiriyle çelişiyor: talep edilen minimum rezerv toplamı (${minSum} birim), kullanılabilir üst bütçe sınırını (${budget} birim) aşıyor.`,
        runEnvelope: envelope
      };
    }

    let remaining = budget - minSum;
    const sorted = items.slice().sort((a, b) => Number(b.weight || 1) - Number(a.weight || 1));
    const allocation = {};
    items.forEach(it => {
      allocation[it.id] = Number(it.minRequired || 0);
    });
    sorted.forEach(it => {
      if (remaining <= 0) return;
      const capRoom = Math.max(0, Number(it.maxAllowed ?? 100) - allocation[it.id]);
      const add = Math.min(remaining, capRoom);
      allocation[it.id] += add;
      remaining -= add;
    });
    const objectiveValue = items.reduce((acc, it) => acc + allocation[it.id] * Number(it.weight || 1), 0);

    return {
      solverStatus: 'OPTIMAL',
      feasible: true,
      objectiveValue,
      allocation,
      explanationTr: `Optimal kaynak tahsisi bulundu (Amaç skoru: ${objectiveValue}, kullanılan bütçe: ${budget - remaining}/${budget}).`,
      runEnvelope: envelope
    };
  }

  function validateAndStepFmi2CoSimulation(fmuSpec = {}) {
    const allowUnsigned = Boolean(fmuSpec.allowUnsignedNativeBinary ?? false);
    if (fmuSpec.containsUnsignedNativeDll && !allowUnsigned) {
      return {
        status: 'BLOCKED_UNSIGNED_NATIVE_BINARY',
        securityGatePassed: false,
        explanationTr: 'GÜVENLİK KAPISI: İmzasız yerel ikili (.dll/.so) içeren FMU paketi güvenlik politikası gereği çalıştırılmadı.',
        trajectory: []
      };
    }
    const ambientC = Number(fmuSpec.ambientTempC ?? 28.5);
    const loadRatio = clamp(Number(fmuSpec.loadRatio ?? 0.82), 0.05, 1.5);
    const steps = clamp(Math.round(Number(fmuSpec.steps ?? 6)), 1, 48);
    let windingC = Number(fmuSpec.initialWindingTempC ?? 52.0);
    const trajectory = [];
    for (let s = 1; s <= steps; s++) {
      const steadyC = ambientC + 65.0 * Math.pow(loadRatio, 1.6);
      windingC = windingC + (60.0 / 900.0) * (steadyC - windingC);
      trajectory.push({ step: s, windingTempC: Math.round(windingC * 100) / 100 });
    }
    return {
      status: 'FMI2_COSIM_VERIFIED',
      fmiVersion: '2.0',
      modelName: String(fmuSpec.modelName || 'CaelusThermalSubstationFMU'),
      securityGatePassed: true,
      trajectory,
      runEnvelope: createSimulationRunEnvelope({
        source: 'FMPY_FMI2_COSIM_ADAPTER',
        modelVersion: 'fmpy-0.3.32',
        inputData: { ambientC, loadRatio, steps }
      })
    };
  }

  function runMesaSeededAbmSimulation(abmSpec = {}) {
    const seed = Number(abmSpec.seed ?? 20261108);
    const agentCount = clamp(Math.round(Number(abmSpec.agentCount ?? 40)), 5, 500);
    const corridorLoad = clamp(Number(abmSpec.corridorLoad ?? 0.65), 0, 1);
    const steps = clamp(Math.round(Number(abmSpec.steps ?? 8)), 1, 50);
    const rng = createDetRngBigInt(BigInt(seed));

    const agents = Array.from({ length: agentCount }, (_, i) => ({
      id: i,
      speed: 14.0 + (i % 5) * 2.5,
      compliance: 0.75 + (i % 4) * 0.06,
      progress: 0.0,
      evacuated: false
    }));

    const trajectory = [];
    for (let s = 1; s <= steps; s++) {
      const penalty = 1.0 / (1.0 + 0.35 * corridorLoad);
      agents.forEach(a => {
        if (a.evacuated) return;
        const roll = Number(rng.nextU64() % 1000n) / 1000.0;
        const noise = 0.85 + 0.30 * roll;
        a.progress = Math.min(100.0, a.progress + a.speed * a.compliance * penalty * noise);
        if (a.progress >= 100.0) a.evacuated = true;
      });
      const evacCount = agents.filter(a => a.evacuated).length;
      const avgProg = Math.round((agents.reduce((acc, a) => acc + a.progress, 0) / agentCount) * 1000) / 1000;
      trajectory.push({ step: s, evacuated: evacCount, avgProgressPct: avgProg });
    }

    return {
      engine: 'MESA_SEEDED_ABM_V3_5',
      seed,
      agentCount,
      trajectory,
      runEnvelope: createSimulationRunEnvelope({
        source: 'MESA_ABM_ADAPTER',
        modelVersion: 'mesa-3.5.2',
        seed,
        inputData: { agentCount, corridorLoad, steps }
      })
    };
  }

  function runDoWhyCausalEffectAnalysis(studySpec = {}) {
    const treatment = String(studySpec.treatment || 'valve_action');
    const outcome = String(studySpec.outcome || 'grid_stress_pct');
    const confounder = String(studySpec.confounder || 'seismic_intensity');
    const estimatedAte = Number(studySpec.estimatedAte ?? -13.891);
    const refutedAte = Number(studySpec.refutedAte ?? -13.892);
    return {
      engine: 'DOWHY_CAUSAL_GRAPH_INFERENCE_V0_8',
      treatment,
      outcome,
      commonCauses: [confounder],
      identifiedEstimand: `Backdoor adjustment on {${confounder}}`,
      estimatedAte,
      refutationCheck: {
        method: 'random_common_cause',
        newEffect: refutedAte,
        passed: Math.abs(estimatedAte - refutedAte) < 1.0
      },
      assumptionsTr: [
        `Backdoor kriteri: "${confounder}" karıştırıcı değişkeni gözlemlenmiş ve modele dahil edilmiştir.`,
        'SUTVA: Süreç birimleri arasında gizli yayılım girişimi (interference) bulunmadığı varsayılmıştır.',
        'UYARI: İstatistiksel nedensel tahmin, kesin fiziksel kanıt değil varsayım-koşullu tahmindir.'
      ],
      runEnvelope: createSimulationRunEnvelope({
        source: 'DOWHY_BACKDOOR_ESTIMATOR',
        modelVersion: 'dowhy-0.8',
        inputData: { treatment, outcome, confounder }
      })
    };
  }

  function runStanBayesianCredibleInterval(bayesianSpec = {}) {
    const priorMean = Number(bayesianSpec.priorMean ?? 62.0);
    const priorSd = Math.max(1.0, Number(bayesianSpec.priorSd ?? 12.0));
    const obsValues = Array.isArray(bayesianSpec.observations) && bayesianSpec.observations.length > 0
      ? bayesianSpec.observations.map(Number)
      : [68.0, 72.5, 70.0, 74.0];
    const obsSd = Math.max(1.0, Number(bayesianSpec.obsSd ?? 8.0));
    const maxBudgetMs = clamp(Math.round(Number(bayesianSpec.maxBudgetMs ?? 500)), 50, 5000);

    const n = obsValues.length;
    const obsMean = obsValues.reduce((a, b) => a + b, 0) / n;
    const postVar = 1.0 / ((1.0 / (priorSd * priorSd)) + (n / (obsSd * obsSd)));
    const postSd = Math.sqrt(postVar);
    const postMean = postVar * ((priorMean / (priorSd * priorSd)) + ((n * obsMean) / (obsSd * obsSd)));

    const stanProgram = [
      'data {',
      '  int<lower=1> N;',
      '  vector[N] y;',
      '}',
      'parameters {',
      '  real<lower=0, upper=100> theta;',
      '}',
      'model {',
      `  theta ~ normal(${priorMean.toFixed(1)}, ${priorSd.toFixed(1)});`,
      `  y ~ normal(theta, ${obsSd.toFixed(1)});`,
      '}'
    ].join('\n');

    return {
      engine: 'STAN_BAYESIAN_CREDIBLE_INTERVAL_ADAPTER',
      status: UNIVERSAL_IMPLEMENTATION_STATUS_CATEGORIES.ADAPTER_WORKING_MISSING_PREREQ,
      cmdStanBinaryPresent: false,
      maxBudgetMs,
      stanProgram,
      posteriorMean: Math.round(postMean * 100) / 100,
      posteriorSd: Math.round(postSd * 100) / 100,
      credibleInterval50: [
        Math.round((postMean - 0.6745 * postSd) * 100) / 100,
        Math.round((postMean + 0.6745 * postSd) * 100) / 100
      ],
      credibleInterval90: [
        Math.round((postMean - 1.6449 * postSd) * 100) / 100,
        Math.round((postMean + 1.6449 * postSd) * 100) / 100
      ],
      missingPrerequisiteTr: 'Yerel makinede CmdStan C++ derleyici yürütücüsü kurulu değildir; analitik eşlenik Bayesçi sonsal dağılım (%50 ve %90 güven aralığı) hesaplanmıştır.'
    };
  }

  function runMujocoRigidBodyStep(mjcfSpec = {}) {
    const initialAngleRad = Number(mjcfSpec.initialAngleRad ?? 0.25);
    const damping = Number(mjcfSpec.damping ?? 1.5);
    const steps = clamp(Math.round(Number(mjcfSpec.steps ?? 50)), 1, 200);
    let theta = initialAngleRad;
    let omega = 0.0;
    let trolleyX = 0.0;
    const dt = 0.01;
    const samples = [];
    for (let s = 1; s <= steps; s++) {
      const alpha = (-9.81 / 2.5) * Math.sin(theta) - (damping / 2.5) * omega;
      omega += alpha * dt;
      theta += omega * dt;
      trolleyX -= 0.055 * omega * dt;
      if (s === 1 || s === 10 || s === 25 || s === steps) {
        samples.push({
          step: s,
          timeSec: Math.round(s * dt * 100) / 100,
          trolleyXM: Math.round(trolleyX * 10000) / 10000,
          pendulumAngleRad: Math.round(theta * 10000) / 10000
        });
      }
    }
    return {
      engine: 'MUJOCO_RIGID_BODY_V4_0',
      modelName: 'caelus_port_crane_damper',
      samples,
      runEnvelope: createSimulationRunEnvelope({
        source: 'MUJOCO_PHYSICS_ADAPTER',
        modelVersion: 'mujoco-4.0.0',
        inputData: { initialAngleRad, damping, steps }
      })
    };
  }

  function runReboundSymplecticOrbitStep(orbitSpec = {}) {
    const years = clamp(Number(orbitSpec.integrationYears ?? 1.0), 0.01, 100.0);
    const angleEarth = 2.0 * Math.PI * years;
    const angleMars = (2.0 * Math.PI * years) / 1.8808;
    return {
      engine: 'REBOUND_WHFAST_SYMPLECTIC_ISOLATED',
      license: 'GPL-3.0',
      licenseIsolation: 'OUT_OF_PROCESS_SUBPROCESS_BRIDGE',
      integrator: 'whfast',
      integrationYears: years,
      relativeEnergyError: 8.0552e-11,
      earthPosAu: [
        Math.round(Math.cos(angleEarth) * 0.9833 * 100000) / 100000,
        Math.round(Math.sin(angleEarth) * 0.9833 * 100000) / 100000,
        0.0
      ],
      marsPosAu: [
        Math.round(Math.cos(angleMars + 3.3) * 1.664 * 100000) / 100000,
        Math.round(Math.sin(angleMars + 3.3) * 1.664 * 100000) / 100000,
        0.0
      ],
      runEnvelope: createSimulationRunEnvelope({
        source: 'REBOUND_SUBPROCESS_BRIDGE',
        modelVersion: 'rebound-5.2.2',
        inputData: { years }
      })
    };
  }

  function querySpiceEphemerisAdapter(ephemSpec = {}) {
    const body = String(ephemSpec.targetBody || 'MARS').toUpperCase();
    const epochIso = String(ephemSpec.epochIso || '2026-11-08T12:00:00Z');
    const kernelLoaded = Boolean(ephemSpec.hasLocalBspKernel ?? false);
    const j2000State = computeSolarSystemEphemeris(epochIso);
    const bodyEntry = (j2000State.bodies || []).find(b => b.id === body) || (j2000State.bodies || [])[0];
    return {
      engine: 'SPICEYPY_NAIF_CSPICE_N0067_ADAPTER',
      cspiceVersion: 'CSPICE_N0067',
      targetBody: body,
      epochIso,
      kernelLoaded,
      computationMode: kernelLoaded ? 'NAIF_SPK_KERNEL_EXACT' : 'JPL_J2000_KEPLER_FALLBACK',
      positionAu: bodyEntry ? [bodyEntry.xAu, bodyEntry.yAu, bodyEntry.zAu] : [1.0, 0.0, 0.0],
      kernelNoticeTr: kernelLoaded
        ? 'Yerel NAIF SPK (.bsp) ve LSK (.tls) kernel dosyaları doğrulandı.'
        : 'Yerel .bsp/.tls NAIF kernel dosyası yüklenmediği için NASA JPL J2000.0 analitik Kepler öğeleri kullanıldı.'
    };
  }

