  // ── 7. River Çevrimiçi Öğrenme, Birleşik Yerel LLM, STORM ve 5 Dünya Modeli ─
  function updateRiverStreamingModel(streamSpec = {}) {
    const samples = Array.isArray(streamSpec.samples) && streamSpec.samples.length > 0
      ? streamSpec.samples
      : Array.from({ length: 120 }, (_, i) => ({
          step: i + 1,
          x: 20.0 + (i % 5),
          y: 48.0 + 1.4 * (20.0 + (i % 5)) + (i >= 80 ? 25.0 : 0.0)
        }));
    let weight = 1.0;
    let bias = 40.0;
    let sumAbsErr = 0.0;
    let driftStep = null;
    let runningMeanErr = 2.0;

    samples.forEach((s, idx) => {
      const pred = bias + weight * Number(s.x);
      const err = Number(s.y) - pred;
      const absErr = Math.abs(err);
      sumAbsErr += absErr;
      if (absErr > runningMeanErr * 3.2 && idx > 20 && driftStep === null) {
        driftStep = idx + 1;
      }
      runningMeanErr = 0.92 * runningMeanErr + 0.08 * absErr;
      bias += 0.04 * err;
      weight += 0.002 * err * Number(s.x);
    });

    return {
      engine: 'RIVER_ONLINE_ML_ADWIN_V0_26',
      samplesProcessed: samples.length,
      mae: Math.round((sumAbsErr / samples.length) * 1000) / 1000,
      adwinDriftDetectedAtStep: driftStep,
      coreCausalEngineMutated: false,
      modelVersionTag: `river-online-v${samples.length}`,
      governanceRuleTr: 'Akan veri öğrenme katmanı (River) yalnızca tahmin ve sapma (ADWIN) uyarısı üretir; kullanıcı onayı olmadan ana nedensel motorun ağırlıklarını değiştirmez.'
    };
  }

  function queryUnifiedLocalLlmProvider(llmSpec = {}) {
    const providerType = String(llmSpec.providerType || 'OLLAMA_HTTP').toUpperCase();
    const endpoint = String(llmSpec.endpoint || (providerType === 'LLAMA_CPP_SERVER' ? 'http://127.0.0.1:8080' : 'http://127.0.0.1:11434'));
    const modelName = String(llmSpec.modelName || 'qwen2.5:1.5b');
    const isLocal = isLocalhostEndpointUrl(endpoint);
    return {
      interfaceName: 'CaelusUnifiedLocalLlmProviderInterface',
      supportedBackends: ['OLLAMA_HTTP (ollama/ollama)', 'LLAMA_CPP_SERVER (ggml-org/llama.cpp)'],
      selectedBackend: providerType,
      endpoint,
      modelName,
      localOnlyAllowed: isLocal,
      cloudFallbackEnabled: false,
      groundingEnforced: true,
      statusNoteTr: isLocal
        ? `Birleşik yerel LLM arayüzü (${providerType} -> ${endpoint}, model: ${modelName}) yalnızca yerel kaynak-bağlı (grounded) özetleme için yapılandırıldı.`
        : 'GÜVENLİK ENGELİ: Yalnızca 127.0.0.1 / localhost uç noktalarına izin verilir; dış bulut LLM adresleri reddedilir.'
    };
  }

  function synthesizeStormMultiPerspectiveReport(topicSpec = {}) {
    const topic = String(topicSpec.topic || 'Ege Denizi Sismik ve Denizcilik Stres Sentezi');
    const records = Array.isArray(topicSpec.verifiedRecords) && topicSpec.verifiedRecords.length > 0
      ? topicSpec.verifiedRecords
      : [
          { id: 'REC-USGS-2020', source: 'USGS ComCat (us7000c7y0)', timestamp: '2020-10-30T11:51:27Z', summary: 'Seferihisar-Sisam açıklarında Mw 7.0 büyüklüğünde sismik kırılma kaydedildi.' },
          { id: 'REC-ERA5-2020', source: 'Open-Meteo ERA5 Reanaliz', timestamp: '2020-10-30T12:00:00Z', summary: 'İzmir Körfezi rüzgâr hızı 26.4 km/sa ve kıyı su seviyesi anomalisi gözlemlendi.' },
          { id: 'REC-CAELUS-SIM', source: 'CAELUS C++17 Nedensel Motor', timestamp: '2026-11-08T12:00:00Z', summary: 'Erken yedek güç ve kapı koridoru tahliyesiyle çalışma kapasitesi %48 yerine %79 korundu.' }
        ];

    const perspectives = [
      {
        roleTr: '1. Sismoloji ve Fiziksel Tehlike Analisti',
        questionTr: 'Fiziksel tetikleyicinin doğrulanmış büyüklüğü ve zamanı nedir?',
        synthesisTr: `${records[0].summary} [Kaynak: ${records[0].source} | Zaman: ${records[0].timestamp}]`
      },
      {
        roleTr: '2. Denizcilik ve Atmosferik Koşul Uzmanı',
        questionTr: 'Eşzamanlı çevresel ve meteorolojik koşullar operasyonu nasıl etkiledi?',
        synthesisTr: `${(records[1] || records[0]).summary} [Kaynak: ${(records[1] || records[0]).source} | Zaman: ${(records[1] || records[0]).timestamp}]`
      },
      {
        roleTr: '3. Operasyonel Süreklilik ve Karar Denetçisi',
        questionTr: 'Müdahalesiz seyir ile kontrollü müdahale arasındaki doğrulanmış model farkı nedir?',
        synthesisTr: `${(records[2] || records[0]).summary} [Kaynak: ${(records[2] || records[0]).source} | Zaman: ${(records[2] || records[0]).timestamp}]`
      }
    ];

    return {
      engine: 'STORM_LOCAL_GROUNDED_MULTI_PERSPECTIVE_SYNTHESIS',
      topic,
      externalSearchUsed: false,
      unverifiedClaimsCount: 0,
      citationCount: perspectives.length,
      perspectives,
      finalGroundedSummaryTr: perspectives.map(p => `${p.roleTr}: ${p.synthesisTr}`).join(' ')
    };
  }

