  function verifyOpenAtlasGlobeMath(lat = 38.4408, lon = 27.1478, radius = 1.0) {
    const phi = (90 - Number(lat)) * (Math.PI / 180);
    const theta = (Number(lon) + 180) * (Math.PI / 180);
    const x = -radius * Math.sin(phi) * Math.cos(theta);
    const y = radius * Math.cos(phi);
    const z = radius * Math.sin(phi) * Math.sin(theta);
    const norm = Math.sqrt(x * x + y * y + z * z);
    const spinStep = (2 * Math.PI) / 140 * 0.5;
    const isConsistent = Math.abs(norm - radius) < 1e-5;
    return {
      valid: isConsistent,
      computedNorm: Number(norm.toFixed(6)),
      expectedRadius: radius,
      lat,
      lon,
      radius,
      localVector: { x: Number(x.toFixed(6)), y: Number(y.toFixed(6)), z: Number(z.toFixed(6)) },
      norm: Number(norm.toFixed(6)),
      isUnitSphereConsistent: isConsistent,
      spinStepHalfSecRad: Number(spinStep.toFixed(6))
    };
  }

