  function computeDeterministicSha256Hex(canonicalStr) {
    const text = String(canonicalStr || '');
    // Deterministic 256-bit (8x32-bit lanes) mixing hash so browser and Node produce identical 64-char hex without async WebCrypto requirements
    const seeds = [
      0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
      0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    ];
    for (let i = 0; i < text.length; i++) {
      const ch = text.charCodeAt(i);
      const lane = i & 7;
      let h = seeds[lane] ^ Math.imul(ch + i + 1, 0x9e3779b1);
      h = Math.imul(h ^ (h >>> 16), 0x85ebca6b);
      h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35);
      seeds[lane] = (h ^ (h >>> 16)) >>> 0;
      const nextLane = (lane + 1) & 7;
      seeds[nextLane] = (seeds[nextLane] + Math.imul(seeds[lane], 0x27d4eb2d)) >>> 0;
    }
    return seeds.map(v => (v >>> 0).toString(16).padStart(8, '0')).join('');
  }

  function validateExternalSourceRequest(urlInput, options) {
    const opts = options && typeof options === 'object' ? options : {};
    const rawUrl = String(urlInput || '').trim();
    const timeoutMs = Number.isFinite(Number(opts.timeoutMs)) ? Math.max(500, Math.min(30000, Number(opts.timeoutMs))) : 8000;
    const maxRetries = Number.isFinite(Number(opts.maxRetries)) ? Math.max(0, Math.min(5, Number(opts.maxRetries))) : 2;
    const maxBytes = Number.isFinite(Number(opts.maxBytes)) ? Math.max(1024, Math.min(10 * 1024 * 1024, Number(opts.maxBytes))) : 2 * 1024 * 1024;
    if (!rawUrl) {
      return { ok: false, errorCode: 'EMPTY_URL', reasonTr: 'Harici kaynak adresi boş olamaz.' };
    }
    if (rawUrl.includes('..') || rawUrl.includes('\\')) {
      return { ok: false, errorCode: 'PATH_TRAVERSAL_BLOCKED', reasonTr: 'Güvenlik kapısı: Yol geçişi (path traversal) engellendi.' };
    }
    let parsed = null;
    try {
      parsed = new URL(rawUrl);
    } catch (_) {
      return { ok: false, errorCode: 'INVALID_URL_SYNTAX', reasonTr: 'Geçersiz URL sözdizimi.' };
    }
    const hostname = String(parsed.hostname || '').toLowerCase();
    const isLocalhost = hostname === '127.0.0.1' || hostname === 'localhost';
    if (parsed.protocol !== 'https:' && !(isLocalhost && parsed.protocol === 'http:')) {
      return {
        ok: false,
        errorCode: 'HTTPS_REQUIRED',
        reasonTr: 'Güvenlik kapısı: Harici veri kaynakları için yalnızca HTTPS protokolü kabul edilir.'
      };
    }
    if (/^(10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2[0-9]|3[0-1])\.)/.test(hostname)) {
      return {
        ok: false,
        errorCode: 'SSRF_PRIVATE_IP_BLOCKED',
        reasonTr: 'Güvenlik kapısı: Özel ağ ve bulut meta-veri IP adreslerine erişim (SSRF) engellendi.'
      };
    }
    if (!REAL_WORLD_ALLOWED_HTTPS_HOSTS.includes(hostname)) {
      return {
        ok: false,
        errorCode: 'HOST_NOT_IN_ALLOWLIST',
        hostname,
        reasonTr: `Güvenlik kapısı: '${hostname}' izin verilen bilimsel/kamusal kaynak listesinde yer almıyor.`
      };
    }
    if (opts.payloadByteLength != null && Number(opts.payloadByteLength) > maxBytes) {
      return {
        ok: false,
        errorCode: 'PAYLOAD_TOO_LARGE',
        payloadByteLength: Number(opts.payloadByteLength),
        maxBytes,
        reasonTr: `Veri boyutu üst sınırı (${maxBytes} bayt) aşıldı.`
      };
    }
    return {
      ok: true,
      normalizedUrl: parsed.toString(),
      hostname,
      protocol: parsed.protocol,
      policy: {
        timeoutMs,
        maxRetries,
        backoffScheduleMs: [300, 900],
        maxBytes,
        rateLimitPerMinute: 30
      }
    };
  }

  function normalizeIsoOrNull(val) {
    if (val === null || val === undefined || val === '') return null;
    if (typeof val === 'number' && Number.isFinite(val)) {
      const d = new Date(val);
      return Number.isNaN(d.getTime()) ? null : d.toISOString();
    }
    const str = String(val).trim();
    if (!str) return null;
    const d = new Date(str);
    return Number.isNaN(d.getTime()) ? null : d.toISOString();
  }

  function normalizeObservationRecord(rawInput, sourceMeta) {
    const raw = rawInput && typeof rawInput === 'object' ? rawInput : {};
    const meta = sourceMeta && typeof sourceMeta === 'object' ? sourceMeta : {};
    const source_id = String(raw.source_id || raw.sourceId || meta.source_id || meta.sourceId || '').trim();
    const source_event_id = String(raw.source_event_id || raw.sourceEventId || raw.id || meta.source_event_id || '').trim();
    if (!source_id || !source_event_id) {
      return {
        ok: false,
        errorCode: 'MISSING_SOURCE_OR_EVENT_ID',
        reasonTr: 'Normalize gözlem kaydı için source_id ve source_event_id zorunludur.',
        record: null
      };
    }

    const source_url = String(raw.source_url || raw.sourceUrl || meta.source_url || meta.sourceUrl || 'https://caelus.local/sources/unknown').trim();
    const attribution = String(raw.attribution || meta.attribution || source_id).trim();
    const license_terms_pointer = String(
      raw.license_terms_pointer || raw.licenseTermsPointer || meta.license_terms_pointer || meta.licenseTermsPointer || 'Public Domain / Open Scientific Data Terms'
    ).trim();

    const fetched_at = normalizeIsoOrNull(raw.fetched_at || raw.fetchedAt || meta.fetched_at || meta.fetchedAt) || new Date().toISOString();
    const observed_at = normalizeIsoOrNull(raw.observed_at || raw.observedAt || raw.event_time || raw.time || meta.observed_at);
    // CRITICAL RULE: Missing published_at must NEVER be fabricated; keep null if unknown
    const published_at = normalizeIsoOrNull(raw.published_at !== undefined ? raw.published_at : (raw.publishedAt !== undefined ? raw.publishedAt : meta.published_at));
    const event_time = observed_at || published_at || fetched_at;

    // Coordinates & CRS validation
    let coordinates = null;
    let crs = String(raw.crs || meta.crs || 'EPSG:4326').trim();
    const rawCoords = raw.coordinates || raw.location || null;
    if (rawCoords && typeof rawCoords === 'object') {
      const lat = Number(rawCoords.lat !== undefined ? rawCoords.lat : rawCoords[1]);
      const lon = Number(rawCoords.lon !== undefined ? rawCoords.lon : rawCoords[0]);
      const depthKm = rawCoords.depthKm !== undefined && rawCoords.depthKm !== null ? Number(rawCoords.depthKm) : (rawCoords[2] !== undefined ? Number(rawCoords[2]) : null);
      if (!Number.isFinite(lat) || !Number.isFinite(lon) || lat < -90 || lat > 90 || lon < -180 || lon > 180) {
        return {
          ok: false,
          errorCode: 'INVALID_COORDINATE_RANGE',
          reasonTr: `Geçersiz koordinat aralığı (lat=${lat}, lon=${lon}). EPSG:4326 sınırları [-90..90, -180..180] olmalıdır.`,
          record: null
        };
      }
      coordinates = Object.freeze({
        lat: Number(lat.toFixed(6)),
        lon: Number(lon.toFixed(6)),
        depthKm: Number.isFinite(depthKm) ? Number(depthKm.toFixed(3)) : null
      });
    }

    // Value & Unit (Missing unit must NEVER be fabricated; keep null if unknown)
    const value = raw.value !== undefined ? raw.value : (raw.magnitude !== undefined ? raw.magnitude : null);
    const unitRaw = raw.unit !== undefined ? raw.unit : meta.unit;
    const unit = (unitRaw === null || unitRaw === undefined || String(unitRaw).trim() === '') ? null : String(unitRaw).trim();

    const revisionNum = Number(raw.revision !== undefined ? raw.revision : (meta.revision !== undefined ? meta.revision : 1));
    const revision = Number.isFinite(revisionNum) && revisionNum >= 1 ? Math.floor(revisionNum) : 1;

    const validDataKinds = ['MEASUREMENT', 'OBSERVATION', 'CALCULATED_EPHEMERIS', 'SIMULATION', 'SAMPLE_FIXTURE'];
    const rawKind = String(raw.data_kind || raw.dataKind || meta.data_kind || 'OBSERVATION').toUpperCase();
    const data_kind = validDataKinds.includes(rawKind) ? rawKind : 'OBSERVATION';

    const freshness = String(raw.freshness || meta.freshness || (data_kind === 'SAMPLE_FIXTURE' ? 'SAMPLE_FIXTURE' : 'LIVE')).toUpperCase();
    const missingOptionalFields = [];
    if (observed_at === null) missingOptionalFields.push('observed_at');
    if (published_at === null) missingOptionalFields.push('published_at');
    if (unit === null) missingOptionalFields.push('unit');
    if (value === null) missingOptionalFields.push('value');

    const quality = missingOptionalFields.length === 0 ? 'VERIFIED' : 'PARTIAL_MISSING_FIELDS';

    const normalized = Object.freeze({
      record_id: `${source_id}:${source_event_id}`,
      source_id,
      source_url,
      attribution,
      source_event_id,
      observed_at,
      published_at,
      fetched_at,
      event_time,
      coordinates,
      crs,
      value,
      unit,
      revision,
      license_terms_pointer,
      data_kind,
      freshness,
      quality,
      missingOptionalFields: Object.freeze(missingOptionalFields),
      title: String(raw.title || raw.label || `${source_id} ${source_event_id}`).trim(),
      category: String(raw.category || meta.category || 'GENERAL').trim(),
      summary: String(raw.summary || '').trim()
    });

    return {
      ok: true,
      errorCode: null,
      record: normalized
    };
  }

