  function syncLedgerRecordsIndex(ledger) {
    if (!ledger || typeof ledger !== 'object') return {};
    const prevById = ledger.recordsById && typeof ledger.recordsById === 'object' ? ledger.recordsById : {};
    const nextById = {};
    const list = Array.isArray(ledger.records) ? ledger.records : [];
    for (const r of list) {
      if (!r || typeof r !== 'object') continue;
      const extId = String(r.externalEventId || r.sourceEventId || r.recordId || '').trim();
      const rawSrcId = String(r.sourceId || 'unknown').trim();
      const canonicalSrcId = rawSrcId === 'usgs_earthquake_feed' ? 'usgs_eq_feed' : rawSrcId;
      const canonicalKey = `${canonicalSrcId}:${extId}`;
      const prevEntry = prevById[canonicalKey] || null;
      const pf = r.parsedFields || {};
      const inferredUnits = (prevEntry && prevEntry.units) || r.units || (
        canonicalSrcId === 'usgs_eq_feed' && pf.magnitude !== undefined
          ? { magnitude: 'Mw', depthKm: 'km' }
          : (pf.windSpeedKmh !== undefined
              ? { windSpeedKmh: 'km/s', temperatureC: '°C', waveHeightM: 'm', surfacePressureHpa: 'hPa' }
              : (pf.magnitudeUnit ? { magnitudeValue: pf.magnitudeUnit } : {}))
      );
      const normView = {
        ...r,
        recordId: canonicalKey,
        sourceId: canonicalSrcId,
        sourceName: r.sourceName || canonicalSrcId,
        sourceEventId: extId,
        title: r.title || r.titleTr || extId,
        summary: r.summary || r.summaryTr || '',
        category: r.category || r.commonModelType || 'EVENT',
        observedAt: (prevEntry && prevEntry.observedAt) || r.observedAt || r.occurrenceTimeIso || r.validTimeIso || null,
        publishedAt: r.publishedAt !== undefined ? r.publishedAt : (r.upstreamUpdatedIso || null),
        fetchedAt: r.fetchedAt || r.ingestedAtIso || null,
        freshnessStatus: r.freshnessStatus || (r.connectionStatus === 'CONNECTED' ? 'LIVE' : 'CACHED'),
        epistemicType: r.epistemicType || (r.epistemicCode === 'SAMPLE_DATA' ? 'SAMPLE_FIXTURE' : 'OBSERVED'),
        revision: Number((prevEntry && prevEntry.revision) || r.revision || r.revisionCount || 1),
        metrics: (prevEntry && prevEntry.metrics) || r.metrics || r.parsedFields || {},
        units: inferredUnits
      };
      nextById[canonicalKey] = normView;
    }
    ledger.recordsById = nextById;
    return ledger.recordsById;
  }

  function parseAndIngestNasaEonetV3Events(ledger, payload, options) {
    const opts = options && typeof options === 'object' ? options : {};
    const fetchedAt = normalizeIsoOrNull(opts.fetchedAt) || new Date().toISOString();
    const isSampleFixture = Boolean(opts.isSampleFixture);
    const eventsArr = payload && Array.isArray(payload.events) ? payload.events : [];
    const normalizedRecords = [];
    const ingestedRecords = [];
    const rejectedEvents = [];
    if (ledger) syncLedgerRecordsIndex(ledger);

    for (const ev of eventsArr) {
      if (!ev || typeof ev !== 'object' || !ev.id) {
        rejectedEvents.push({ id: null, reason: 'MISSING_EVENT_ID' });
        continue;
      }
      const geomList = Array.isArray(ev.geometry) ? ev.geometry : [];
      const latestGeom = geomList.length > 0 ? geomList[geomList.length - 1] : null;
      let coordsObj = null;
      if (latestGeom && Array.isArray(latestGeom.coordinates) && latestGeom.coordinates.length >= 2) {
        if (latestGeom.type === 'Polygon' && Array.isArray(latestGeom.coordinates[0]) && Array.isArray(latestGeom.coordinates[0][0])) {
          coordsObj = { lon: Number(latestGeom.coordinates[0][0][0]), lat: Number(latestGeom.coordinates[0][0][1]), depthKm: 0 };
        } else {
          coordsObj = { lon: Number(latestGeom.coordinates[0]), lat: Number(latestGeom.coordinates[1]), depthKm: 0 };
        }
      }
      const categoryObj = Array.isArray(ev.categories) && ev.categories[0] ? ev.categories[0] : { id: 'naturalEvent', title: 'Natural Event' };
      const primarySource = Array.isArray(ev.sources) && ev.sources[0] ? ev.sources[0] : { id: 'NASA_EONET', url: 'https://eonet.gsfc.nasa.gov/' };
      const observedAt = latestGeom && latestGeom.date ? latestGeom.date : null;
      const magVal = latestGeom && latestGeom.magnitudeValue !== undefined && latestGeom.magnitudeValue !== null
        ? Number(latestGeom.magnitudeValue)
        : geomList.length;
      const magUnit = latestGeom && latestGeom.magnitudeUnit ? String(latestGeom.magnitudeUnit) : null;

      // Track revision if record already exists in ledger
      const existingKey = `nasa_eonet_v3:${ev.id}`;
      const existingRec = ledger && ledger.recordsById && ledger.recordsById[existingKey] ? ledger.recordsById[existingKey] : null;
      let nextRevision = existingRec ? Number(existingRec.revision || 1) : 1;
      if (existingRec) {
        const prevObs = existingRec.observedAt || existingRec.observed_at || null;
        const prevVal = existingRec.metrics && existingRec.metrics.magnitudeValue !== undefined ? existingRec.metrics.magnitudeValue : null;
        const prevGeomCount = existingRec.metrics && existingRec.metrics.geometrySteps !== undefined ? existingRec.metrics.geometrySteps : 1;
        if (prevObs !== normalizeIsoOrNull(observedAt) || prevVal !== magVal || prevGeomCount !== geomList.length) {
          nextRevision += 1;
        }
      }

      const normRes = normalizeObservationRecord({
        source_id: 'nasa_eonet_v3',
        source_url: String(ev.link || primarySource.url || 'https://eonet.gsfc.nasa.gov/api/v3/events'),
        attribution: `NASA EOSDIS EONET v3 (${primarySource.id || 'NASA'})`,
        source_event_id: String(ev.id),
        observed_at: observedAt,
        published_at: null, // EONET v3 geometry provides observation date; publication timestamp is not separately provided
        fetched_at: fetchedAt,
        coordinates: coordsObj,
        crs: 'EPSG:4326',
        value: magVal,
        unit: magUnit,
        revision: nextRevision,
        license_terms_pointer: 'https://earthdata.nasa.gov/learn/find-data/near-real-time/citation',
        data_kind: isSampleFixture ? 'SAMPLE_FIXTURE' : 'OBSERVATION',
        freshness: isSampleFixture ? 'SAMPLE_FIXTURE' : 'LIVE',
        title: String(ev.title || ev.id),
        category: String(categoryObj.title || categoryObj.id || 'Natural Event'),
        summary: `${ev.title || ev.id} — Kategori: ${categoryObj.title || categoryObj.id}${magVal !== null ? ` (${magVal}${magUnit ? ' ' + magUnit : ''})` : ''}${isSampleFixture ? ' [TEST/ÖRNEK VERİ]' : ''}`
      });

      if (!normRes.ok) {
        rejectedEvents.push({ id: ev.id, reason: normRes.errorCode });
        continue;
      }
      normalizedRecords.push(normRes.record);

      if (ledger && typeof upsertLedgerRecord === 'function') {
        const upserted = upsertLedgerRecord(ledger, {
          sourceId: 'nasa_eonet_v3',
          externalEventId: normRes.record.source_event_id,
          sourceName: isSampleFixture ? 'NASA EONET v3 (TEST/ÖRNEK VERİ)' : 'NASA EONET v3 (Doğal Olaylar)',
          sourceUrl: normRes.record.source_url,
          commonModelType: 'Event',
          titleTr: normRes.record.title,
          summaryTr: normRes.record.summary,
          occurrenceTimeIso: normRes.record.observed_at || normRes.record.event_time,
          validTimeIso: normRes.record.observed_at || normRes.record.event_time,
          upstreamUpdatedIso: normRes.record.observed_at || normRes.record.event_time,
          ingestedAtIso: normRes.record.fetched_at,
          connectionStatus: isSampleFixture ? 'STALE' : 'CONNECTED',
          epistemicCode: isSampleFixture ? 'SAMPLE_DATA' : 'REAL_OBSERVATION',
          location: normRes.record.coordinates ? {
            lat: normRes.record.coordinates.lat,
            lon: normRes.record.coordinates.lon,
            depthKm: 0,
            placeLabel: normRes.record.title,
            crs: 'EPSG:4326'
          } : null,
          parsedFields: {
            magnitude: magVal,
            magnitudeValue: magVal,
            magnitudeUnit: magUnit,
            categoryId: categoryObj.id || 'naturalEvent',
            categoryTitle: categoryObj.title || 'Natural Event',
            geometrySteps: geomList.length,
            isSampleFixture
          },
          rawPayloadSummary: {
            id: ev.id,
            category: categoryObj.id,
            latestDate: observedAt,
            sourceUrl: normRes.record.source_url,
            licenseTermsPointer: normRes.record.license_terms_pointer
          }
        });
        if (upserted && upserted.record) {
          upserted.record.revision = nextRevision;
          upserted.record.revisionCount = nextRevision;
          ingestedRecords.push(upserted.record);
        }
        syncLedgerRecordsIndex(ledger);
        if (ledger.recordsById[existingKey]) {
          ledger.recordsById[existingKey].revision = nextRevision;
          ledger.recordsById[existingKey].observedAt = normRes.record.observed_at;
          ledger.recordsById[existingKey].metrics = {
            magnitudeValue: magVal,
            magnitudeUnit: magUnit,
            categoryId: categoryObj.id || 'naturalEvent',
            categoryTitle: categoryObj.title || 'Natural Event',
            geometrySteps: geomList.length,
            isSampleFixture
          };
          ledger.recordsById[existingKey].units = {
            magnitudeValue: magUnit || 'adim'
          };
        }
      }
    }

    if (ledger && ledger.sourcesStatus) {
      ledger.sourcesStatus.nasa_eonet_v3 = {
        sourceId: 'nasa_eonet_v3',
        status: isSampleFixture ? 'CACHED' : 'LIVE',
        lastFetchedAt: fetchedAt,
        lastError: null,
        recordCount: normalizedRecords.length,
        isSampleFixture
      };
    }

    return {
      ok: true,
      source_id: 'nasa_eonet_v3',
      isSampleFixture,
      ingestedCount: normalizedRecords.length,
      rejectedCount: rejectedEvents.length,
      records: normalizedRecords,
      ledgerRecords: ingestedRecords,
      rejectedEvents
    };
  }

  function resolveNasaGibsLayerForDate(layerIdInput, isoDateInput, options) {
    const opts = options && typeof options === 'object' ? options : {};
    const layerId = String(layerIdInput || 'VIIRS_SNPP_CorrectedReflectance_TrueColor').trim();
    const spec = NASA_GIBS_LAYER_COVERAGE_CATALOG[layerId] || NASA_GIBS_LAYER_COVERAGE_CATALOG.VIIRS_SNPP_CorrectedReflectance_TrueColor;
    const dateStr = String(isoDateInput || new Date().toISOString().slice(0, 10)).trim().slice(0, 10);
    const offlineMode = Boolean(opts.offlineMode);

    if (offlineMode) {
      return {
        available: false,
        offlineMode: true,
        layerId: spec.layerId,
        requestedDate: dateStr,
        source_id: spec.source_id,
        attribution: spec.attribution,
        license_terms_pointer: spec.license_terms_pointer,
        fallbackLayer: 'NaturalEarthII (Yerel Çevrimdışı Karo Katmanı)',
        reasonTr: `Çevrimdışı mod aktif: NASA GIBS (${spec.titleTr}, Tarih: ${dateStr}) uydu karolarına erişilemiyor. Yerel NaturalEarthII katmanı korunuyor.`,
        reasonEn: `Offline mode active: NASA GIBS (${spec.titleEn}, Date: ${dateStr}) satellite tiles are unreachable. Keeping local NaturalEarthII base layer.`
      };
    }

    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
      return {
        available: false,
        offlineMode: false,
        layerId: spec.layerId,
        requestedDate: dateStr,
        source_id: spec.source_id,
        attribution: spec.attribution,
        reasonTr: `Geçersiz gözlem tarihi biçimi ('${dateStr}'). YYYY-AA-GG biçimi bekleniyor.`,
        reasonEn: `Invalid observation date format ('${dateStr}'). Expected YYYY-MM-DD.`
      };
    }

    const todayStr = new Date().toISOString().slice(0, 10);
    if (dateStr < spec.validFromDate) {
      return {
        available: false,
        offlineMode: false,
        layerId: spec.layerId,
        requestedDate: dateStr,
        validFromDate: spec.validFromDate,
        source_id: spec.source_id,
        attribution: spec.attribution,
        reasonTr: `Seçilen tarihte (${dateStr}) '${spec.titleTr}' katmanı için uydu verisi bulunmamaktadır (Sensör başlangıç tarihi: ${spec.validFromDate}).`,
        reasonEn: `No satellite imagery available for '${spec.titleEn}' on ${dateStr} (Sensor coverage starts on ${spec.validFromDate}).`
      };
    }

    if (dateStr > todayStr) {
      return {
        available: false,
        offlineMode: false,
        layerId: spec.layerId,
        requestedDate: dateStr,
        validUntilDate: todayStr,
        source_id: spec.source_id,
        attribution: spec.attribution,
        reasonTr: `Seçilen tarih (${dateStr}) gelecekte olduğu için NASA GIBS gözlem verisi henüz mevcut değildir (Son geçerli gün: ${todayStr}).`,
        reasonEn: `Requested date (${dateStr}) is in the future; NASA GIBS observation imagery is not yet available.`
      };
    }

    const resolvedUrl = spec.source_url
      .replace('{Time}', dateStr)
      .replace('{TileMatrixSet}', spec.matrixSet);

    return {
      available: true,
      offlineMode: false,
      layerId: spec.layerId,
      titleTr: spec.titleTr,
      titleEn: spec.titleEn,
      requestedDate: dateStr,
      source_id: spec.source_id,
      attribution: spec.attribution,
      license_terms_pointer: spec.license_terms_pointer,
      matrixSet: spec.matrixSet,
      resolutionLabel: spec.resolutionLabel,
      resolvedTemplateUrl: resolvedUrl,
      reasonTr: `${spec.titleTr} — Gözlem Tarihi: ${dateStr} — Kaynak: ${spec.attribution}`,
      reasonEn: `${spec.titleEn} — Observation Date: ${dateStr} — Source: ${spec.attribution}`
    };
  }

  function createImmutableDataSnapshot(recordsInput, worldInput, options) {
    const opts = options && typeof options === 'object' ? options : {};
    if (opts.userApproved !== true) {
      return {
        ok: false,
        errorCode: 'USER_APPROVAL_REQUIRED',
        reasonTr: 'Gerçek dünya verisi kullanıcı onayı olmadan otomatik olarak senaryo motoruna bağlanamaz. Lütfen "Veriyi Senaryoda Kullan (Snapshot Oluştur)" onayını verin.',
        snapshot: null
      };
    }

    const rawList = Array.isArray(recordsInput) ? recordsInput : [];
    const normalizedList = [];
    for (const item of rawList) {
      if (item && item.source_id && item.source_event_id && item.crs) {
        normalizedList.push(item);
      } else if (item && (item.recordId || item.externalEventId) && item.sourceId) {
        const valCandidate = (item.parsedFields && item.parsedFields.magnitude !== undefined)
          ? item.parsedFields.magnitude
          : (item.metrics && item.metrics.magnitude !== undefined
            ? item.metrics.magnitude
            : (item.metrics && item.metrics.windSpeed10m !== undefined ? item.metrics.windSpeed10m : 1));
        const res = normalizeObservationRecord({
          source_id: item.sourceId === 'usgs_earthquake_feed' ? 'usgs_eq_feed' : item.sourceId,
          source_url: (item.rawPayloadSummary && item.rawPayloadSummary.sourceUrl) || (item.rawExcerpt && item.rawExcerpt.sourceUrl) || item.sourceUrl || 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/4.5_week.geojson',
          attribution: item.sourceName || item.sourceId,
          source_event_id: item.sourceEventId || item.externalEventId || item.recordId,
          observed_at: item.observedAt || item.occurrenceTimeIso || item.validTimeIso,
          published_at: item.publishedAt !== undefined ? item.publishedAt : (item.upstreamUpdatedIso || null),
          fetched_at: item.fetchedAt || item.ingestedAtIso,
          coordinates: item.location ? { lat: item.location.lat, lon: item.location.lon, depthKm: item.location.depthKm } : null,
          crs: (item.location && item.location.crs) || 'EPSG:4326',
          value: valCandidate,
          unit: item.units ? Object.values(item.units)[0] : (item.sourceId === 'usgs_earthquake_feed' || item.sourceId === 'usgs_eq_feed' ? 'Mw' : null),
          revision: item.revision || item.revisionCount || 1,
          data_kind: item.epistemicType === 'SAMPLE_FIXTURE' || item.epistemicCode === 'SAMPLE_DATA' ? 'SAMPLE_FIXTURE' : 'MEASUREMENT',
          freshness: item.freshnessStatus || (item.connectionStatus === 'CONNECTED' ? 'LIVE' : 'CACHED'),
          title: item.title || item.titleTr,
          category: item.category || item.commonModelType || 'EVENT',
          summary: item.summary || item.summaryTr
        });
        if (res.ok) normalizedList.push(res.record);
      }
    }

    // Sort deterministically by record_id and revision
    normalizedList.sort((a, b) => {
      const cmp = String(a.record_id).localeCompare(String(b.record_id));
      return cmp !== 0 ? cmp : (Number(a.revision) - Number(b.revision));
    });

    const frozenRecords = Object.freeze(normalizedList.map(r => Object.freeze({
      ...r,
      coordinates: (r && r.coordinates && typeof r.coordinates === 'object')
        ? Object.freeze({ ...r.coordinates })
        : r.coordinates
    })));
    const worldId = worldInput && worldInput.id ? String(worldInput.id) : 'BS-01_SAHTE_UFUK';
    const worldName = worldInput && worldInput.name ? String(worldInput.name) : 'Liman Terminali ve Soğuk Zincir SLA (Denizcilik)';
    const seed = Number.isFinite(Number(opts.seed)) ? Number(opts.seed) : 4202026;
    const fixed_point_scale = 1000000;
    const rounding_rule = 'HALF_AWAY_FROM_ZERO_INT64';
    const time_conversion_rule = 'UTC_ISO8601_EPOCH_MS';
    const model_version = String(opts.model_version || 'caelus-core-cpp17-v9.4');
    const schema_version = 'caelus.snapshot.v2';

    // Identify the primary USGS earthquake record (either explicitly selected by user or highest-magnitude USGS record in snapshot)
    const selectedEventIdOpt = opts.selectedEventId ? String(opts.selectedEventId).trim() : '';
    const usgsRecords = frozenRecords.filter(r => r.source_id === 'usgs_eq_feed' || r.source_id === 'usgs_earthquake_feed');
    let primaryUsgsRec = null;
    if (selectedEventIdOpt) {
      primaryUsgsRec = usgsRecords.find(r =>
        r.record_id === selectedEventIdOpt ||
        r.source_event_id === selectedEventIdOpt ||
        `LEDGER_${r.record_id}` === selectedEventIdOpt ||
        `LEDGER_usgs_earthquake_feed:${r.source_event_id}` === selectedEventIdOpt
      ) || null;
    }
    if (!primaryUsgsRec && usgsRecords.length > 0) {
      primaryUsgsRec = [...usgsRecords].sort((a, b) => (Number(b.value) || 0) - (Number(a.value) || 0))[0];
    }
    if (!primaryUsgsRec && frozenRecords.length > 0) {
      primaryUsgsRec = frozenRecords[0];
    }

    const eqMagMw = primaryUsgsRec && Number.isFinite(Number(primaryUsgsRec.value))
      ? Math.max(0, Math.min(9.5, Number(primaryUsgsRec.value)))
      : 5.4;
    const eqDepthKm = primaryUsgsRec && primaryUsgsRec.coordinates && Number.isFinite(Number(primaryUsgsRec.coordinates.depthKm))
      ? Math.max(0, Number(primaryUsgsRec.coordinates.depthKm))
      : 10.0;
    const eqLat = primaryUsgsRec && primaryUsgsRec.coordinates && Number.isFinite(Number(primaryUsgsRec.coordinates.lat))
      ? Number(primaryUsgsRec.coordinates.lat)
      : 37.90;
    const eqLon = primaryUsgsRec && primaryUsgsRec.coordinates && Number.isFinite(Number(primaryUsgsRec.coordinates.lon))
      ? Number(primaryUsgsRec.coordinates.lon)
      : 26.79;

    const primaryTargetEntityId = String(opts.primaryTargetEntityId || 'PORT_TRAFO_BESLEME');
    const primaryTargetEntityLabel = String(opts.primaryTargetEntityLabel || 'Rıhtım Trafo ve Reefer Enerji Besleme');
    const secondaryTargetEntityId = String(opts.secondaryTargetEntityId || 'SOGUK_ZINCIR_REEFER');
    const secondaryTargetEntityLabel = String(opts.secondaryTargetEntityLabel || 'Soğuk Zincir (Reefer) İlaç ve Gıda Yükü');

    const baselineLoadPct = Number.isFinite(Number(opts.baselineLoadPct)) ? Number(opts.baselineLoadPct) : 50;
    const secondaryBaselineLoadPct = Number.isFinite(Number(opts.secondaryBaselineLoadPct)) ? Number(opts.secondaryBaselineLoadPct) : 45;

    // Explicit deterministic mapping rule from earthquake Mw & depthKm to scenario stress input (%0-%100 and fixed-point 1e6)
    const rawLinearDelta = Number(((eqMagMw - 3.8) * 14 - Math.min(eqDepthKm, 120) * 0.06).toFixed(4));
    const rawDeltaPct = Math.round(Math.max(10, rawLinearDelta));
    const seismicDeltaLoadPct = Math.max(10, Math.min(44, rawDeltaPct));
    const rawTargetSumPct = baselineLoadPct + seismicDeltaLoadPct;
    const targetClampMinPct = 58;
    const targetClampMaxPct = 96;
    const mappedTargetLoadPct = Math.max(targetClampMinPct, Math.min(targetClampMaxPct, rawTargetSumPct));
    const effectiveAppliedDeltaPct = mappedTargetLoadPct - baselineLoadPct;
    const secondaryRawLinearDelta = Number((seismicDeltaLoadPct * 0.75).toFixed(4));
    const secondaryDeltaPct = Math.max(8, Math.round(secondaryRawLinearDelta));
    const secondaryRawSumPct = secondaryBaselineLoadPct + secondaryDeltaPct;
    const secondaryClampMinPct = 52;
    const secondaryClampMaxPct = 94;
    const secondaryMappedLoadPct = Math.max(secondaryClampMinPct, Math.min(secondaryClampMaxPct, secondaryRawSumPct));
    const mappedTargetLoadFixedPoint = Math.round(mappedTargetLoadPct * 10000); // on 1e6 scale (0..1,000,000)
    const secondaryMappedLoadFixedPoint = Math.round(secondaryMappedLoadPct * 10000);
    const mappedAnomalyW = Math.round(16384 + (mappedTargetLoadPct / 100) * 16384);
    const horizonTicks = Number.isFinite(Number(opts.horizonTicks)) ? Number(opts.horizonTicks) : 24;
    const interventionLeverId = String(opts.interventionLeverId || 'L-LIMAN-01_MOBIL_JENERATOR_YESIL_HAT');
    const interventionLeverLabel = String(opts.interventionLeverLabel || 'Mobil Reefer Jeneratörlerini ve Gümrük Yeşil Hattını Devreye Al');

    const scenarioInputMapping = Object.freeze({
      selectedObservation: Object.freeze({
        record_id: primaryUsgsRec ? primaryUsgsRec.record_id : 'usgs_eq_feed:sample',
        source_id: primaryUsgsRec ? primaryUsgsRec.source_id : 'usgs_eq_feed',
        source_name: primaryUsgsRec ? primaryUsgsRec.attribution : 'USGS Earthquake Hazards Program (GeoJSON API)',
        source_url: primaryUsgsRec ? primaryUsgsRec.source_url : 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/4.5_week.geojson',
        source_event_id: primaryUsgsRec ? primaryUsgsRec.source_event_id : 'usgs_event',
        title: primaryUsgsRec ? primaryUsgsRec.title : `M ${eqMagMw.toFixed(1)} Deprem`,
        magnitudeMw: eqMagMw,
        depthKm: eqDepthKm,
        lat: eqLat,
        lon: eqLon,
        crs: 'EPSG:4326',
        observed_at: primaryUsgsRec ? primaryUsgsRec.observed_at : null,
        published_at: primaryUsgsRec ? primaryUsgsRec.published_at : null,
        fetched_at: primaryUsgsRec ? primaryUsgsRec.fetched_at : null,
        data_kind: primaryUsgsRec ? primaryUsgsRec.data_kind : 'OBSERVATION',
        freshness: primaryUsgsRec ? primaryUsgsRec.freshness : 'LIVE'
      }),
      targetWorldModel: Object.freeze({
        worldId,
        worldName,
        isSampleModel: true,
        primaryTargetEntityId,
        primaryTargetEntityLabel,
        baselineLoadPct,
        secondaryTargetEntityId,
        secondaryTargetEntityLabel,
        secondaryBaselineLoadPct
      }),
      mappedEngineInputs: Object.freeze({
        formulaTr: `Ham ΔYük = round((Mw(${eqMagMw.toFixed(1)}) - 3.8) × 14 - min(Derinlik(${eqDepthKm.toFixed(1)}km), 120) × 0.06) = round(${rawLinearDelta}) = +${seismicDeltaLoadPct}p · Ham Toplam: %${baselineLoadPct} + ${seismicDeltaLoadPct} = %${rawTargetSumPct} → Üst Tavan Sınırı clamp(%${rawTargetSumPct}, ${targetClampMinPct}, ${targetClampMaxPct}) = %${mappedTargetLoadPct} (net +${effectiveAppliedDeltaPct}p)`,
        rawLinearDelta,
        rawDeltaPct,
        seismicDeltaLoadPct,
        rawTargetSumPct,
        targetClampMinPct,
        targetClampMaxPct,
        mappedTargetLoadPct,
        effectiveAppliedDeltaPct,
        mappedTargetLoadFixedPoint,
        secondaryRawLinearDelta,
        secondaryDeltaPct,
        secondaryRawSumPct,
        secondaryClampMinPct,
        secondaryClampMaxPct,
        secondaryMappedLoadPct,
        secondaryMappedLoadFixedPoint,
        mappedAnomalyW,
        interventionLeverId,
        interventionLeverLabel,
        horizonTicks,
        horizonHours: Number(((horizonTicks * 15) / 60).toFixed(1)),
        seed,
        fixed_point_scale
      }),
      epistemicSeparation: Object.freeze({
        realDataTr: `Gerçek Veri (USGS Gözlemi): Olay Kimliği=${primaryUsgsRec ? primaryUsgsRec.source_event_id : '—'}, Büyüklük=M${eqMagMw.toFixed(1)} Mw, Derinlik=${eqDepthKm.toFixed(1)} km, Koordinat=(${eqLat.toFixed(2)}°, ${eqLon.toFixed(2)}° EPSG:4326), Olay Zamanı=${primaryUsgsRec ? primaryUsgsRec.observed_at : '—'}.`,
        sampleModelTr: `Örnek / Kayıtlı Dünya Modeli: ${worldName} (${worldId}) içindeki '${primaryTargetEntityLabel}' (${primaryTargetEntityId}, başlangıç yükü %${baselineLoadPct}) ve '${secondaryTargetEntityLabel}' (${secondaryTargetEntityId}, başlangıç yükü %${secondaryBaselineLoadPct}) düğümleri.`,
        assumptionTr: `Kullanıcı Onaylı Senaryo Varsayımı: M${eqMagMw.toFixed(1)} depreminin birincil süreç noktasına ham +${seismicDeltaLoadPct} puan stres yükü ürettiği (%${baselineLoadPct} + ${seismicDeltaLoadPct} = %${rawTargetSumPct}), [%${targetClampMinPct}..%${targetClampMaxPct}] tavan sınırı (clamp) ile %${mappedTargetLoadPct} (net +${effectiveAppliedDeltaPct} puan, state_fp=${mappedTargetLoadFixedPoint}/1000000, anomaly_W=${mappedAnomalyW}) ve ikincil süreç noktasına +${secondaryDeltaPct} puan (%${secondaryBaselineLoadPct} + ${secondaryDeltaPct} = %${secondaryMappedLoadPct}, state_fp=${secondaryMappedLoadFixedPoint}/1000000) aktardığı varsayılmıştır. Bu aktarım doğrulanmış fiziksel nedensellik değil, kullanıcı seçimiyle çalıştırılan "Ne Olursa?" (What-If) senaryo stres girdisidir.`
      })
    });

    const initial_state = Object.freeze({
      worldId,
      worldName,
      entityCount: worldInput && Array.isArray(worldInput.entities) ? worldInput.entities.length : 4,
      baselineDemandShockPct: Number(opts.baselineDemandShockPct !== undefined ? opts.baselineDemandShockPct : 14),
      optionBResourceBoostPct: Number(opts.optionBResourceBoostPct !== undefined ? opts.optionBResourceBoostPct : 20),
      primaryTargetEntityId,
      baselineLoadPct,
      mappedTargetLoadPct,
      mappedTargetLoadFixedPoint,
      secondaryTargetEntityId,
      secondaryMappedLoadPct,
      mappedAnomalyW,
      interventionLeverId,
      horizonTicks
    });

    const canonicalPayload = JSON.stringify({
      schema_version,
      model_version,
      fixed_point_scale,
      rounding_rule,
      time_conversion_rule,
      seed,
      initial_state,
      records: frozenRecords.map(r => ({
        record_id: r.record_id,
        source_id: r.source_id,
        source_event_id: r.source_event_id,
        observed_at: r.observed_at,
        value: r.value,
        unit: r.unit,
        revision: r.revision,
        crs: r.crs
      }))
    });

    const snapshot_hash = computeDeterministicSha256Hex(canonicalPayload);
    const snapshot_id = `snap_${snapshot_hash.slice(0, 16)}`;
    const source_ids = Object.freeze(Array.from(new Set(frozenRecords.map(r => r.source_id))));

    const snapshot = Object.freeze({
      snapshot_id,
      snapshot_hash,
      created_at: normalizeIsoOrNull(opts.createdAt) || new Date().toISOString(),
      userApproved: true,
      schema_version,
      model_version,
      fixed_point_scale,
      rounding_rule,
      time_conversion_rule,
      seed,
      initial_state,
      scenarioInputMapping,
      source_ids,
      record_count: frozenRecords.length,
      records: frozenRecords,
      boundedRawExcerptBytes: Math.min(canonicalPayload.length, 4096),
      assumptions: Object.freeze([
        scenarioInputMapping.epistemicSeparation.realDataTr,
        scenarioInputMapping.epistemicSeparation.sampleModelTr,
        scenarioInputMapping.epistemicSeparation.assumptionTr,
        'Simülasyon çıktısı kesin kehanet değildir; Müdahalesiz (Koşu A) ve Müdahaleli (Koşu B) seçeneklerinin aynı dondurulmuş (immutable) başlangıç koşullarındaki deterministik farkını gösterir.'
      ])
    });

    return {
      ok: true,
      errorCode: null,
      snapshot
    };
  }

  function runDeterministicSnapshotScenario(snapshotInput) {
    const snap = snapshotInput && snapshotInput.snapshot ? snapshotInput.snapshot : snapshotInput;
    if (!snap || !snap.snapshot_hash || !Array.isArray(snap.records)) {
      return { ok: false, errorCode: 'INVALID_SNAPSHOT' };
    }
    const scale = BigInt(snap.fixed_point_scale || 1000000);
    let maxEqMagFp = 0n;
    let maxWindKmhFp = 0n;
    let naturalEventCount = 0n;

    for (const rec of snap.records) {
      const valNum = Number(rec.value);
      if (!Number.isFinite(valNum)) continue;
      if (rec.source_id === 'usgs_eq_feed' || rec.source_id === 'usgs_earthquake_feed') {
        const clampedMag = Math.max(0, Math.min(9.5, valNum));
        const valFp = BigInt(Math.round(clampedMag * Number(scale)));
        if (valFp > maxEqMagFp) maxEqMagFp = valFp;
      } else if (rec.source_id === 'open_meteo_weather' || rec.source_id === 'open_meteo_weather_marine' || rec.unit === 'km/h') {
        const clampedWind = Math.max(0, Math.min(180, valNum));
        const valFp = BigInt(Math.round(clampedWind * Number(scale)));
        if (valFp > maxWindKmhFp) maxWindKmhFp = valFp;
      } else if (rec.source_id === 'nasa_eonet_v3') {
        naturalEventCount += 1n;
      }
    }

    const cappedEonetCount = naturalEventCount > 8n ? 8n : naturalEventCount;
    const baseShockFp = BigInt(Math.round(Number(snap.initial_state.baselineDemandShockPct || 14) * Number(scale)));
    const eqStressFp = (maxEqMagFp * 4200000n) / scale;
    const windStressFp = (maxWindKmhFp * 180000n) / scale;
    const eonetStressFp = cappedEonetCount * 1200000n;
    const rawStressFp = baseShockFp + eqStressFp + windStressFp + eonetStressFp;
    const maxAllowedStressFp = 78n * scale;
    const totalStressPctFp = rawStressFp > maxAllowedStressFp ? maxAllowedStressFp : rawStressFp;

    const optionACapacityFp = 100n * scale - (totalStressPctFp * 75n) / 100n;
    const boostFp = BigInt(Math.round(Number(snap.initial_state.optionBResourceBoostPct || 28) * Number(scale)));
    const rawOptionBFp = optionACapacityFp + (boostFp * 80n) / 100n;
    const optionBCapacityFp = rawOptionBFp > 98n * scale ? 98n * scale : rawOptionBFp;
    const netGainFp = optionBCapacityFp - optionACapacityFp;

    const resultCanonical = JSON.stringify({
      snapshot_hash: snap.snapshot_hash,
      model_version: snap.model_version,
      seed: snap.seed,
      totalStressPctFp: totalStressPctFp.toString(),
      optionACapacityFp: optionACapacityFp.toString(),
      optionBCapacityFp: optionBCapacityFp.toString(),
      netGainFp: netGainFp.toString()
    });
    const output_hash = computeDeterministicSha256Hex(resultCanonical);

    return Object.freeze({
      ok: true,
      snapshot_id: snap.snapshot_id,
      snapshot_hash: snap.snapshot_hash,
      output_hash,
      model_version: snap.model_version,
      fixed_point_scale: Number(scale),
      stressSummary: {
        totalStressPct: Number(totalStressPctFp) / Number(scale),
        optionACapacityPct: Number(optionACapacityFp) / Number(scale),
        optionBCapacityPct: Number(optionBCapacityFp) / Number(scale),
        optionBNetGainPct: Number(netGainFp) / Number(scale)
      },
      assumptions: snap.assumptions
    });
  }

  function verifyDeterministicSnapshotReplay(snapshotInput, liveNewRecords) {
    const snap = snapshotInput && snapshotInput.snapshot ? snapshotInput.snapshot : snapshotInput;
    const run1 = runDeterministicSnapshotScenario(snap);
    const run2 = runDeterministicSnapshotScenario(snap);
    const isBitIdentical = Boolean(
      run1.ok &&
      run2.ok &&
      run1.output_hash === run2.output_hash &&
      run1.stressSummary.optionACapacityPct === run2.stressSummary.optionACapacityPct &&
      run1.stressSummary.optionBCapacityPct === run2.stressSummary.optionBCapacityPct
    );

    // Verify that new live records arriving later do NOT mutate the existing snapshot
    const originalRecordCount = snap && Array.isArray(snap.records) ? snap.records.length : 0;
    const hasNewLiveRecords = Array.isArray(liveNewRecords) && liveNewRecords.length > 0;
    const runAfterLiveArrival = runDeterministicSnapshotScenario(snap);
    const isolatedFromLiveMutation = Boolean(
      runAfterLiveArrival.output_hash === run1.output_hash &&
      snap.records.length === originalRecordCount
    );

    return {
      ok: isBitIdentical && isolatedFromLiveMutation,
      isBitIdentical,
      isolatedFromLiveMutation,
      hasNewLiveRecords,
      snapshot_id: snap.snapshot_id,
      snapshot_hash: snap.snapshot_hash,
      run1_output_hash: run1.output_hash,
      run2_output_hash: run2.output_hash,
      stressSummary: run1.stressSummary
    };
  }

  function buildDeckGlRegionalLayerSpec(ledger, options) {
    const opts = options && typeof options === 'object' ? options : {};
    if (ledger) syncLedgerRecordsIndex(ledger);
    const allRecords = ledger && ledger.recordsById ? Object.values(ledger.recordsById) : [];
    const points = [];
    for (const rec of allRecords) {
      if (!rec || !rec.location || !Number.isFinite(Number(rec.location.lat)) || !Number.isFinite(Number(rec.location.lon))) continue;
      const isEq = rec.sourceId === 'usgs_eq_feed';
      const isEonet = rec.sourceId === 'nasa_eonet_v3';
      const mag = rec.metrics && rec.metrics.magnitude !== undefined
        ? Number(rec.metrics.magnitude)
        : (rec.metrics && rec.metrics.magnitudeValue !== undefined ? Number(rec.metrics.magnitudeValue) : 2.5);
      points.push({
        recordId: rec.recordId,
        sourceId: rec.sourceId,
        sourceName: rec.sourceName,
        title: rec.title,
        category: rec.category,
        observedAt: rec.observedAt,
        fetchedAt: rec.fetchedAt,
        freshnessStatus: rec.freshnessStatus,
        revision: rec.revision || 1,
        coordinates: [Number(rec.location.lon), Number(rec.location.lat)],
        lat: Number(rec.location.lat),
        lon: Number(rec.location.lon),
        radiusMeters: isEq ? Math.max(4000, mag * 6500) : (isEonet ? 14000 : 8000),
        colorRgba: isEq ? [245, 158, 11, 220] : (isEonet ? [244, 63, 94, 220] : [56, 189, 248, 210])
      });
    }

    // Build coastal corridor arcs to Izmir Port hub (27.1428, 38.4237)
    const hubCoord = [27.1428, 38.4237];
    const arcs = points.slice(0, 12).map(pt => ({
      id: `arc_to_hub_${pt.recordId}`,
      sourceRecordId: pt.recordId,
      sourcePosition: pt.coordinates,
      targetPosition: hubCoord,
      sourceColor: pt.colorRgba,
      targetColor: [16, 185, 129, 200]
    }));

    return {
      ok: true,
      engineIntegrationMode: 'MAPLIBRE_DECKGL_SHARED_CANVAS',
      concurrentHeavyGlobeRenderers: 1,
      layers: [
        {
          id: 'caelus-deckgl-events-scatterplot',
          type: 'ScatterplotLayer',
          pickable: true,
          pointCount: points.length,
          data: points
        },
        {
          id: 'caelus-deckgl-corridor-arcs',
          type: 'ArcLayer',
          pickable: true,
          arcCount: arcs.length,
          data: arcs
        }
      ],
      selectedRecordInspectorResolver: (recordId) => {
        if (!ledger || !ledger.recordsById) return null;
        return ledger.recordsById[recordId] || null;
      },
      filterBySource: opts.sourceFilter || 'ALL'
    };
  }

  function buildCytoscapeRelationshipElements(world, ledger, options) {
    const opts = options && typeof options === 'object' ? options : {};
    const nodes = [];
    const edges = [];
    const entities = world && Array.isArray(world.entities) && world.entities.length > 0
      ? world.entities
      : [
          { id: 'ent_port_izmir', name: 'İzmir Alsancak Limanı', type: 'PORT_HUB', source: 'Kullanıcı Dünya Modeli', unit: '%' },
          { id: 'ent_energy_grid', name: 'Liman Yedek Enerji Şebekesi', type: 'ENERGY_NODE', source: 'Kullanıcı Dünya Modeli', unit: 'MW' },
          { id: 'ent_crane_ops', name: 'Rıhtım Vinç Operasyonu', type: 'CRANE_FLEET', source: 'Eclipse Ditto Örnek Cihaz İkizi', unit: 'TEU/saat' },
          { id: 'ent_road_corridor', name: 'Hinterland Kara/Demiryolu Koridoru', type: 'LOGISTICS_CORRIDOR', source: 'Kullanıcı Dünya Modeli', unit: 'km/saat' }
        ];

    for (const ent of entities) {
      const id = String(ent.id || ent.entityId);
      // Plain readable name on canvas; technical ID and metadata stay in inspector fields
      const plainLabel = String(ent.name || ent.label || id).replace(/\s*\[[^\]]+\]\s*/g, '').trim();
      nodes.push({
        group: 'nodes',
        data: {
          id,
          label: plainLabel,
          technicalId: id,
          nodeCategory: String(ent.type || ent.category || 'SYSTEM_NODE'),
          sourceLabel: String(ent.source || 'CAELUS Dünya Modeli'),
          unit: ent.unit || '%',
          epistemicKind: 'MODEL_ENTITY',
          inspectorSummaryTr: `${plainLabel} — Kimlik: ${id} · Kaynak: ${ent.source || 'Dünya Modeli'}`
        }
      });
    }

    // Add up to 4 real-world observation nodes from ledger (prioritize Aegean / regional records)
    if (ledger) syncLedgerRecordsIndex(ledger);
    const allLedgerRecs = ledger && ledger.recordsById ? Object.values(ledger.recordsById) : [];
    const sortedLedgerRecs = allLedgerRecs.slice().sort((a, b) => {
      const scoreRec = (r) => {
        const lat = Number(r.location?.lat ?? r.lat ?? 0);
        const lon = Number(r.location?.lon ?? r.lon ?? 0);
        const txt = `${r.title || ''} ${r.recordId || ''} ${r.location?.placeLabel || ''}`.toLowerCase();
        if ((lat >= 34 && lat <= 42 && lon >= 20 && lon <= 31) || txt.includes('izmir') || txt.includes('ege') || txt.includes('aegean') || txt.includes('sakız') || txt.includes('samos') || txt.includes('karaburun')) return 3;
        if (String(r.sourceId || '').includes('open_meteo') || String(r.sourceId || '').includes('eonet')) return 2;
        return 1;
      };
      return scoreRec(b) - scoreRec(a);
    });
    const ledgerList = sortedLedgerRecs.slice(0, 4);
    for (const rec of ledgerList) {
      const nodeId = `obs_${rec.recordId.replace(/[^a-zA-Z0-9_-]/g, '_')}`;
      const cleanedTitle = String(rec.title || rec.recordId)
        .replace(/\s*\(\d{4}-\d{2}-\d{2}T[^)]+\)/g, '')
        .replace(/^M\s+([0-9.]+)\s+-\s+/i, 'Mw $1 Deprem — ')
        .trim();
      const plainTitle = cleanedTitle.slice(0, 44);
      nodes.push({
        group: 'nodes',
        data: {
          id: nodeId,
          label: plainTitle,
          technicalId: rec.recordId,
          nodeCategory: rec.category || 'OBSERVATION',
          sourceLabel: rec.sourceName || rec.sourceId,
          observedAt: rec.observedAt,
          unit: rec.units ? Object.values(rec.units)[0] : null,
          epistemicKind: rec.epistemicType === 'SAMPLE_FIXTURE' ? 'SAMPLE_FIXTURE' : 'MEASUREMENT',
          inspectorSummaryTr: `${plainTitle} — Kaynak: ${rec.sourceName || rec.sourceId} — Zaman: ${rec.observedAt || 'Bilinmiyor'}`
        }
      });

      const targetEntityId = nodes[0] ? nodes[0].data.id : 'ent_port_izmir';
      const edgeMeta = CYTOSCAPE_EDGE_EPISTEMIC_TYPES.MEASUREMENT;
      edges.push({
        group: 'edges',
        data: {
          id: `edge_${nodeId}_to_${targetEntityId}`,
          source: nodeId,
          target: targetEntityId,
          label: edgeMeta.labelTr,
          epistemicType: edgeMeta.code,
          epistemicLabelTr: edgeMeta.labelTr,
          epistemicLabelEn: edgeMeta.labelEn,
          color: edgeMeta.color,
          lineStyle: edgeMeta.lineStyle,
          causalProof: false,
          sourceAttribution: rec.sourceName || rec.sourceId,
          inspectorNoticeTr: 'Bu bağlantı gerçek zamanlı/kayıtlı gözlem eşleşmesidir; tek başına kanıtlanmış nedensellik anlamına gelmez.'
        }
      });
    }

    // Add explicit structural relations covering all 4 epistemic edge types
    if (nodes.length >= 2) {
      const n0 = nodes[0].data.id;
      const n1 = nodes[1].data.id;
      const n2 = nodes[2] ? nodes[2].data.id : n0;
      const n3 = nodes[3] ? nodes[3].data.id : n1;

      edges.push({
        group: 'edges',
        data: {
          id: `edge_model_${n1}_${n2}`,
          source: n1,
          target: n2,
          label: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.MODEL_RELATION.labelTr,
          epistemicType: 'MODEL_RELATION',
          epistemicLabelTr: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.MODEL_RELATION.labelTr,
          color: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.MODEL_RELATION.color,
          lineStyle: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.MODEL_RELATION.lineStyle,
          causalProof: false,
          inspectorNoticeTr: 'Model bağıntısı: Enerji kesintisi vinç kapasitesini matematiksel modelde sınırlar.'
        }
      });

      edges.push({
        group: 'edges',
        data: {
          id: `edge_expert_${n0}_${n1}`,
          source: n0,
          target: n1,
          label: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.EXPERT_INPUT.labelTr,
          epistemicType: 'EXPERT_INPUT',
          epistemicLabelTr: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.EXPERT_INPUT.labelTr,
          color: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.EXPERT_INPUT.color,
          lineStyle: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.EXPERT_INPUT.lineStyle,
          causalProof: false,
          inspectorNoticeTr: 'Uzman girişi: Operatör tarafından tanımlanan yedek güç aktarım önceliği.'
        }
      });

      edges.push({
        group: 'edges',
        data: {
          id: `edge_hypothesis_${n2}_${n3}`,
          source: n2,
          target: n3,
          label: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.HYPOTHESIS.labelTr,
          epistemicType: 'HYPOTHESIS',
          epistemicLabelTr: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.HYPOTHESIS.labelTr,
          color: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.HYPOTHESIS.color,
          lineStyle: CYTOSCAPE_EDGE_EPISTEMIC_TYPES.HYPOTHESIS.lineStyle,
          causalProof: false,
          inspectorNoticeTr: 'Hipotez: Vinç gecikmesinin kara koridorunda 6 saat sonra kuyruk oluşturacağı varsayımı (Kanıtlanmış nedensellik değildir).'
        }
      });
    }

    const filterType = opts.epistemicFilter && opts.epistemicFilter !== 'ALL' ? String(opts.epistemicFilter) : null;
    const filteredEdges = filterType ? edges.filter(e => e.data.epistemicType === filterType) : edges;

    return {
      ok: true,
      nodeCount: nodes.length,
      edgeCount: filteredEdges.length,
      edgeTypesCatalog: CYTOSCAPE_EDGE_EPISTEMIC_TYPES,
      causalityDisclaimerTr: 'ÖNEMLİ: İlişki ağındaki bir bağlantı kanıtlanmış nedensellik anlamına gelmez. Her kenar Ölçüm, Uzman Girişi, Model Bağıntısı veya Hipotez olarak ayrıştırılmıştır.',
      elements: {
        nodes,
        edges: filteredEdges
      }
    };
  }

  function buildPerspectiveInspectionView(ledger, options) {
    const opts = options && typeof options === 'object' ? options : {};
    if (ledger) syncLedgerRecordsIndex(ledger);
    const allRecords = ledger && ledger.recordsById ? Object.values(ledger.recordsById) : [];
    const sourceFilter = opts.sourceId && opts.sourceId !== 'ALL' ? String(opts.sourceId) : null;
    const freshnessFilter = opts.freshness && opts.freshness !== 'ALL' ? String(opts.freshness) : null;
    const searchQuery = opts.search ? String(opts.search).toLowerCase().trim() : '';
    const sortBy = String(opts.sortBy || 'observedAt_desc');

    let rows = allRecords.map(rec => {
      const mObj = rec.metrics && typeof rec.metrics === 'object' ? rec.metrics : {};
      const preferredKeys = ['magnitude', 'windSpeedKmh', 'temperatureC', 'waveHeightM', 'magnitudeValue', 'value'];
      let primaryMetricKey = preferredKeys.find(k => typeof mObj[k] === 'number' && Number.isFinite(mObj[k])) || null;
      if (!primaryMetricKey) {
        primaryMetricKey = Object.keys(mObj).find(k => typeof mObj[k] === 'number' && Number.isFinite(mObj[k])) || Object.keys(mObj)[0] || null;
      }
      const rawVal = primaryMetricKey !== null && mObj[primaryMetricKey] !== undefined ? mObj[primaryMetricKey] : (typeof rec.value === 'number' ? rec.value : null);
      const rawUnit = rec.units && primaryMetricKey && rec.units[primaryMetricKey]
        ? rec.units[primaryMetricKey]
        : (rec.units ? Object.values(rec.units)[0] : (rec.unit || null));
      return {
        record_id: rec.recordId,
        source_id: rec.sourceId,
        source_name: rec.sourceName || rec.sourceId,
        title: rec.title,
        category: rec.category,
        observed_at: rec.observedAt || null,
        published_at: rec.publishedAt || null,
        fetched_at: rec.fetchedAt || null,
        value: typeof rawVal === 'number' ? rawVal : null,
        unit: rawUnit || null,
        freshness: rec.freshnessStatus || 'LIVE',
        epistemic_type: rec.epistemicType || 'OBSERVED',
        revision: Number(rec.revision || 1),
        crs: (rec.location && rec.location.crs) || 'EPSG:4326',
        lat: rec.location ? rec.location.lat : null,
        lon: rec.location ? rec.location.lon : null,
        source_record_link: `#inspect-record:${rec.recordId}`
      };
    });

    if (sourceFilter) {
      rows = rows.filter(r => r.source_id === sourceFilter);
    }
    if (freshnessFilter) {
      rows = rows.filter(r => r.freshness === freshnessFilter);
    }
    if (searchQuery) {
      rows = rows.filter(r =>
        String(r.title || '').toLowerCase().includes(searchQuery) ||
        String(r.source_name || '').toLowerCase().includes(searchQuery) ||
        String(r.category || '').toLowerCase().includes(searchQuery)
      );
    }

    rows.sort((a, b) => {
      if (sortBy === 'value_desc') return (Number(b.value) || -Infinity) - (Number(a.value) || -Infinity);
      if (sortBy === 'value_asc') return (Number(a.value) || Infinity) - (Number(b.value) || Infinity);
      if (sortBy === 'revision_desc') return Number(b.revision) - Number(a.revision);
      return String(b.observed_at || '').localeCompare(String(a.observed_at || ''));
    });

    // Group summary for Perspective chart/pivot view
    const bySourceSummary = {};
    for (const r of rows) {
      if (!bySourceSummary[r.source_id]) {
        bySourceSummary[r.source_id] = {
          source_id: r.source_id,
          source_name: r.source_name,
          count: 0,
          unit: r.unit || 'Bilinmiyor (null)',
          latest_observed_at: r.observed_at,
          freshness: r.freshness
        };
      }
      bySourceSummary[r.source_id].count += 1;
    }

    return {
      ok: true,
      workspaceTitleTr: 'Verileri İncele (Perspective Tablo / Pivot Görünümü)',
      totalUnfilteredCount: allRecords.length,
      filteredRowCount: rows.length,
      resultDisposition: rows.length === 0 ? 'EMPTY_RESULT_SET' : 'HAS_ROWS',
      rows,
      pivotBySource: Object.values(bySourceSummary)
    };
  }

  function runDuckDbSnapshotQueryWithProvenance(snapshotOrLedger, querySpec) {
    const q = querySpec && typeof querySpec === 'object' ? querySpec : {};
    let records = [];
    let snapshotId = 'live_ledger_view';
    if (snapshotOrLedger && snapshotOrLedger.snapshot_id && Array.isArray(snapshotOrLedger.records)) {
      records = snapshotOrLedger.records;
      snapshotId = snapshotOrLedger.snapshot_id;
    } else if (snapshotOrLedger && (snapshotOrLedger.recordsById || Array.isArray(snapshotOrLedger.records))) {
      const view = buildPerspectiveInspectionView(snapshotOrLedger, {});
      records = view.rows;
    }

    const filterSource = q.source_id && q.source_id !== 'ALL' ? String(q.source_id) : null;
    const minVal = q.minValue !== undefined && q.minValue !== null ? Number(q.minValue) : null;
    const filtered = records.filter(r => {
      const rSrc = r.source_id || r.sourceId;
      if (filterSource && rSrc !== filterSource) return false;
      if (minVal !== null && Number.isFinite(minVal)) {
        if (r.value === null || r.value === undefined || Number(r.value) < minVal) return false;
      }
      return true;
    });

    const unknownFieldRecords = filtered.filter(r => r.unit === null || r.published_at === null);
    const groupsMap = {};
    for (const r of filtered) {
      const rSrc = r.source_id || r.sourceId || 'unknown';
      const rSrcName = r.source_name || r.sourceName || rSrc;
      const key = `${rSrc}|${r.unit || 'NULL_UNIT'}`;
      if (!groupsMap[key]) {
        groupsMap[key] = {
          source_id: rSrc,
          source_name: rSrcName,
          unit: r.unit,
          unitStatus: r.unit === null ? 'UNKNOWN_NULL' : 'KNOWN',
          row_count: 0,
          min_value: null,
          max_value: null,
          source_record_ids: []
        };
      }
      const g = groupsMap[key];
      g.row_count += 1;
      if (typeof r.value === 'number' && Number.isFinite(r.value)) {
        g.min_value = g.min_value === null ? r.value : Math.min(g.min_value, r.value);
        g.max_value = g.max_value === null ? r.value : Math.max(g.max_value, r.value);
      }
      g.source_record_ids.push(r.record_id || r.recordId);
    }

    return {
      ok: true,
      engine: 'DuckDB Local Analytical Snapshot Engine (Read-Only Isolated Projection)',
      snapshot_id: snapshotId,
      mutatedWorldStore: false,
      sqlPreview: `SELECT source_id, unit, COUNT(*) AS row_count, MIN(value) AS min_value, MAX(value) AS max_value FROM snapshot_records${filterSource ? ` WHERE source_id = '${filterSource}'` : ''} GROUP BY source_id, unit;`,
      disposition: filtered.length === 0 ? 'EMPTY_QUERY_RESULT' : (unknownFieldRecords.length > 0 ? 'HAS_ROWS_WITH_UNKNOWN_NULL_FIELDS' : 'COMPLETE_ROWS'),
      matchedRowCount: filtered.length,
      unknownFieldRecordCount: unknownFieldRecords.length,
      groups: Object.values(groupsMap)
    };
  }

  function stepEclipseDittoTwinRevision(world, options) {
    const opts = options && typeof options === 'object' ? options : {};
    const prevRevision = Number.isFinite(Number(opts.previousRevision)) ? Math.max(0, Math.floor(Number(opts.previousRevision))) : 1;
    const nextRevision = prevRevision + 1;
    const modifiedAt = normalizeIsoOrNull(opts.modifiedAt) || new Date().toISOString();
    const isAuthorizedExternalService = Boolean(opts.authorizedServiceEndpoint);

    const baseThing = exportWorldToEclipseDittoThing(world || { id: 'izmir_port_pilot', name: 'İzmir Alsancak Limanı Örnek Cihaz İkizi' });
    const craneLoadPct = Math.min(98, 62 + ((nextRevision * 7) % 29));
    const backupBatteryPct = Math.max(45, 96 - ((nextRevision * 5) % 35));

    const updatedThing = Object.freeze({
      ...baseThing,
      thingId: String(opts.thingId || 'org.caelus.pilot:izmir-port-crane-01'),
      policyId: 'org.caelus.pilot:readonly-twin-policy',
      _revision: nextRevision,
      _modified: modifiedAt,
      attributes: Object.freeze({
        ...baseThing.attributes,
        twinSourceClassification: isAuthorizedExternalService
          ? 'AUTHORIZED_DITTO_SERVICE'
          : 'SAMPLE_DEVICE_SIMULATOR (Yerel Örnek Cihaz / Kurumsal Simülatör)',
        autonomousCommandExecution: 'DISABLED_READ_ONLY'
      }),
      features: Object.freeze({
        ...baseThing.features,
        craneTelemetry: Object.freeze({
          properties: Object.freeze({
            status: craneLoadPct > 85 ? 'HIGH_LOAD_ADVISORY' : 'OPERATIONAL',
            loadFactorPct: craneLoadPct,
            windLockoutActive: false,
            unit: '%',
            observedAt: modifiedAt
          })
        }),
        backupPowerPack: Object.freeze({
          properties: Object.freeze({
            stateOfChargePct: backupBatteryPct,
            autonomyHours: Number((backupBatteryPct * 0.48).toFixed(1)),
            unit: '%'
          })
        })
      })
    });

    return {
      ok: true,
      thingId: updatedThing.thingId,
      previousRevision: prevRevision,
      revision: nextRevision,
      _modified: modifiedAt,
      mode: isAuthorizedExternalService ? 'AUTHORIZED_DITTO_SERVICE' : 'SAMPLE_DEVICE_SIMULATOR',
      modeLabelTr: isAuthorizedExternalService
        ? 'Yetkili Eclipse Ditto Servisi (Salt-Okunur)'
        : 'Yerel Eclipse Ditto Örnek Cihaz Simülatörü (TEST/ÖRNEK İKİZ)',
      autonomousWriteAllowed: false,
      thing: updatedThing
    };
  }

  function parseAndVerifyJplHorizonsEphemeris(inputSpec) {
    const spec = inputSpec && typeof inputSpec === 'object' ? inputSpec : {};
    const targetCommand = String(spec.command || spec.bodyId || '499').trim();
    const epochIso = normalizeIsoOrNull(spec.epochIso || spec.time) || new Date().toISOString();
    const bodyCatalog = {
      '399': { id: '399', nameTr: 'Dünya (Earth 399)', nameEn: 'Earth (399)', planetKey: 'earth' },
      '301': { id: '301', nameTr: 'Ay (Moon 301)', nameEn: 'Moon (301)', planetKey: 'moon' },
      '499': { id: '499', nameTr: 'Mars (499)', nameEn: 'Mars (499)', planetKey: 'mars' },
      '599': { id: '599', nameTr: 'Jüpiter (599)', nameEn: 'Jupiter (599)', planetKey: 'jupiter' }
    };
    const bodyMeta = bodyCatalog[targetCommand] || bodyCatalog['499'];

    let positionAu = null;
    let deliveryMode = 'VERIFIED_CACHED_ANALYTICAL_FALLBACK';

    // Check if raw Horizons API JSON result block was provided
    if (typeof spec.rawHorizonsResultText === 'string' && spec.rawHorizonsResultText.includes('$$SOE')) {
      const soeIdx = spec.rawHorizonsResultText.indexOf('$$SOE');
      const eoeIdx = spec.rawHorizonsResultText.indexOf('$$EOE');
      const block = eoeIdx > soeIdx ? spec.rawHorizonsResultText.slice(soeIdx + 5, eoeIdx) : spec.rawHorizonsResultText.slice(soeIdx + 5);
      const xm = block.match(/X\s*=\s*([+-]?\d+(?:\.\d+)?(?:E[+-]?\d+)?)/i);
      const ym = block.match(/Y\s*=\s*([+-]?\d+(?:\.\d+)?(?:E[+-]?\d+)?)/i);
      const zm = block.match(/Z\s*=\s*([+-]?\d+(?:\.\d+)?(?:E[+-]?\d+)?)/i);
      if (xm && ym && zm) {
        const AU_KM = 149597870.7;
        const xVal = Number(xm[1]);
        const yVal = Number(ym[1]);
        const zVal = Number(zm[1]);
        const isKm = Math.abs(xVal) > 1000;
        positionAu = {
          xAu: Number((isKm ? xVal / AU_KM : xVal).toFixed(6)),
          yAu: Number((isKm ? yVal / AU_KM : yVal).toFixed(6)),
          zAu: Number((isKm ? zVal / AU_KM : zVal).toFixed(6))
        };
        deliveryMode = spec.viaLocalProxy ? 'LOCAL_PROXY_JPL_HORIZONS_API' : 'LIVE_JPL_HORIZONS_API';
      }
    }

    if (!positionAu) {
      const ephem = computeSolarSystemEphemeris(epochIso);
      const bodyRow = ephem && Array.isArray(ephem.bodies)
        ? ephem.bodies.find(b => b.id === bodyMeta.planetKey) || ephem.bodies[0]
        : { xAu: 1.3814, yAu: -0.6122, zAu: -0.0341, heliocentricDistAu: 1.511 };
      positionAu = {
        xAu: Number((bodyRow.xAu || 1.3814).toFixed(6)),
        yAu: Number((bodyRow.yAu || -0.6122).toFixed(6)),
        zAu: Number((bodyRow.zAu || -0.0341).toFixed(6))
      };
    }

    const rAu = Number(Math.sqrt(positionAu.xAu ** 2 + positionAu.yAu ** 2 + positionAu.zAu ** 2).toFixed(6));

    const normObs = normalizeObservationRecord({
      source_id: 'jpl_horizons_ephemeris',
      source_url: `https://ssd.jpl.nasa.gov/api/horizons.api?format=json&COMMAND='${bodyMeta.id}'&OBJ_DATA='NO'&MAKE_EPHEM='YES'&EPHEM_TYPE='VECTORS'&CENTER='500@10'`,
      attribution: 'NASA / JPL Solar System Dynamics — Horizons Ephemeris System (Standish J2000.0)',
      source_event_id: `HORIZONS_${bodyMeta.id}_${epochIso.slice(0, 16)}`,
      observed_at: epochIso,
      published_at: '2026-01-01T00:00:00Z',
      fetched_at: new Date().toISOString(),
      coordinates: null,
      crs: 'ICRF/J2000.0-Ecliptic',
      value: rAu,
      unit: 'AU',
      revision: 1,
      license_terms_pointer: 'https://ssd-api.jpl.nasa.gov/doc/horizons.html',
      data_kind: 'CALCULATED_EPHEMERIS',
      freshness: deliveryMode.startsWith('LIVE') ? 'LIVE' : 'CACHED',
      title: `${bodyMeta.nameTr} Efemeris Konumu (${rAu} AU)`,
      category: 'CELESTIAL_EPHEMERIS'
    });

    return {
      ok: true,
      targetBodyId: bodyMeta.id,
      targetNameTr: bodyMeta.nameTr,
      targetNameEn: bodyMeta.nameEn,
      epochIso,
      time_scale: 'UTC / TDB (Barycentric Dynamical Time)',
      reference_frame: 'ICRF / J2000.0 Heliocentric Ecliptic (CENTER: 500@10)',
      validity_range: '1800-01-01 .. 2050-01-01',
      cors_delivery_mode: deliveryMode,
      cors_explanation_tr: deliveryMode.startsWith('LIVE')
        ? 'Doğrudan NASA JPL Horizons API yanıtı alındı.'
        : 'Tarayıcı CORS politikası veya çevrimdışı durum nedeniyle doğrulanmış JPL J2000.0 analitik/önbellek efemeris hesabı kullanıldı.',
      positionAu,
      heliocentricDistanceAu: rAu,
      operational_separation_notice_tr: 'KESİN SINIR: Bu gök cismi konumu hesaplanmış astronomik efemeristir; Dünya üzerindeki liman, enerji veya tedarik zinciri senaryolarını nedensel olarak etkilemez.',
      normalizedRecord: normObs.record
    };
  }

  function evaluateGooglePhotorealistic3DTilesGate(configInput) {
    const cfg = configInput && typeof configInput === 'object' ? configInput : {};
    const apiKey = String(cfg.apiKey || '').trim();
    const userBillingConsent = cfg.userBillingConsent === true;
    const enabledByUser = cfg.enabledByUser === true;

    if (!enabledByUser || !apiKey || !userBillingConsent) {
      return {
        ok: true,
        enabled: false,
        enabledByDefault: false,
        statusCategory: 'ENGELLİ / KULLANICI ANAHTARI VE MALİYET ONAYI GEREKLİ (Varsayılan Kapalı Sağlayıcı İskeleti)',
        networkRequestsAllowed: false,
        networkRequestCount: 0,
        activeFallbackProvider: 'Cesium NaturalEarthII + Yerel OGC 3D Tiles (izmir_port_sample/tileset.json)',
        policyComplianceUrl: 'https://developers.google.com/maps/documentation/tile/policies',
        reasonTr: !apiKey
          ? 'Google Photorealistic 3D Tiles varsayılan olarak KAPALIDIR. Kullanıcı kendi Google Cloud API anahtarını girmediği ve maliyet onayını vermediği sürece hiçbir ağ isteği yapılmaz; ücretsiz NaturalEarthII ve yerel 3D Tiles sahnesi kullanılır.'
          : 'Maliyet ve kullanım politikası onayı (userBillingConsent) verilmediği için Google 3D Tiles ağ isteği engellendi.'
      };
    }

    return {
      ok: true,
      enabled: true,
      enabledByDefault: false,
      statusCategory: 'KULLANICI ANAHTARI VE ONAYIYLA ETKİNLEŞTİRİLDİ',
      networkRequestsAllowed: true,
      endpointTemplate: 'https://tile.googleapis.com/v1/3dtiles/root.json',
      attributionRequired: 'Google Maps Platform — Photorealistic 3D Tiles',
      policyComplianceUrl: 'https://developers.google.com/maps/documentation/tile/policies',
      reasonTr: 'Kullanıcı anahtarı ve maliyet onayı doğrulandı.'
    };
  }

